// object moves the hash, and a network id that did not move would mean the new
// field was not in it. The DONATION KEYS below are unchanged and were not
// regenerated - `make-genesis.mjs` makes new ones every run, and the ids are a
// function of these same public keys, so recomputing beat rerunning.

const GENESIS_CONFIG_HASH = fromHex('bbae68dc11e6e25f3dbb4d225cd52f2d4b32095a61a3bd1d8ced655eed82a5f1');
const NETWORK_ID_REGTEST = fromHex('30927357ec8945494d397ad427df5fb34702e1dd69608ac92f9b61f00b10649d');
const NETWORK_ID_TESTNET4 = fromHex('bf876cb1a9cb671ba127e40e242ac9a79d82259ec28f8900f94faf5b1005604d');
const AUTHORITY_PUBKEY_REGTEST = fromHex('6a0bbf5d24255489cdd44d0c33ac1e3ff4006491ec7d76bc1ea5723e5c59b700');
const RECOVERY_PUBKEY_REGTEST = fromHex('981ca74b57d303c6053b9c1335d111817a74bd82ced80f87491d1d9a4fb9d7ae');
const AUTHORITY_PUBKEY_TESTNET4 = fromHex('ea65169edd6387d681a3c6b14c5a17243d49fcdcdbf60816b0e2cb2771a8c9bc');
const RECOVERY_PUBKEY_TESTNET4 = fromHex('6aa9f9a67f0dba65360fadaff996b3bc0223283b3a88d527df6970625ecec453');

/**
 * THE ARBITRATION SET, 5A.3B's script path B, as a GENESIS FACT.
 *
 * The bond's slash leaf hashes these keys, so they decide what a bond's output
 * key even is. A poster who could name their own set could name themselves and
 * hold a bond nobody else can ever slash - so the set is the network's, like
 * BOND_MARKER, and not a field on the advertisement.
 *
 * ON THESE TWO TEST NETWORKS THE SECRETS ARE DERIVABLE BY ANYONE, and that is
 * deliberate rather than careless:
 *
 *     secret_i = taggedHash('BLWP/v1/TestArbitration', `${chain}:${i}`)
 *     pubkey_i = x-only public key of secret_i
 *
 * Regtest and testnet4 distribute no money (M2 asks for none), and an
 * arbitration set whose keys nobody holds could never slash anything - so a
 * test network with an unusable set would be testing a slash that cannot
 * happen. Anyone can reproduce these and exercise path B.
 *
 * MAINNET HAS NO SET HERE, exactly as it has no BOND_MARKER: real keys held by
 * real people are a decision, not a derivation, and this file will not invent
 * one.
 */
