//---------------------------------------------------------------------
// qrBitBuffer
//---------------------------------------------------------------------

const qrBitBuffer = function() {

  const _buffer = [];
  let _length = 0;

  const _this = {};

  _this.getBuffer = function() {
    return _buffer;
  };

  _this.getAt = function(index) {
    const bufIndex = Math.floor(index / 8);
    return ( (_buffer[bufIndex] >>> (7 - index % 8) ) & 1) == 1;
  };

  _this.put = function(num, length) {
    for (let i = 0; i < length; i += 1) {
      _this.putBit( ( (num >>> (length - i - 1) ) & 1) == 1);
    }
  };

  _this.getLengthInBits = function() {
    return _length;
  };

  _this.putBit = function(bit) {

    const bufIndex = Math.floor(_length / 8);
    if (_buffer.length <= bufIndex) {
      _buffer.push(0);
    }

    if (bit) {
      _buffer[bufIndex] |= (0x80 >>> (_length % 8) );
    }

    _length += 1;
  };

  return _this;
};

//---------------------------------------------------------------------
// qrNumber
//---------------------------------------------------------------------

const qrNumber = function(data) {

  const _mode = QRMode.MODE_NUMBER;
  const _data = data;

  const _this = {};

  _this.getMode = function() {
    return _mode;
  };

  _this.getLength = function(buffer) {
    return _data.length;
  };

  _this.write = function(buffer) {

    const data = _data;

    let i = 0;

    while (i + 2 < data.length) {
      buffer.put(strToNum(data.substring(i, i + 3) ), 10);
      i += 3;
    }

    if (i < data.length) {
      if (data.length - i == 1) {
        buffer.put(strToNum(data.substring(i, i + 1) ), 4);
      } else if (data.length - i == 2) {
        buffer.put(strToNum(data.substring(i, i + 2) ), 7);
      }
    }
  };

  const strToNum = function(s) {
    let num = 0;
    for (let i = 0; i < s.length; i += 1) {
      num = num * 10 + chatToNum(s.charAt(i) );
    }
    return num;
  };

  const chatToNum = function(c) {
    if ('0' <= c && c <= '9') {
      return c.charCodeAt(0) - '0'.charCodeAt(0);
    }
    throw 'illegal char :' + c;
  };

  return _this;
};

//---------------------------------------------------------------------
// qrAlphaNum
//---------------------------------------------------------------------

const qrAlphaNum = function(data) {

  const _mode = QRMode.MODE_ALPHA_NUM;
  const _data = data;

  const _this = {};

  _this.getMode = function() {
    return _mode;
  };

  _this.getLength = function(buffer) {
    return _data.length;
  };

  _this.write = function(buffer) {

    const s = _data;

    let i = 0;

    while (i + 1 < s.length) {
      buffer.put(
        getCode(s.charAt(i) ) * 45 +
        getCode(s.charAt(i + 1) ), 11);
      i += 2;
    }

    if (i < s.length) {
      buffer.put(getCode(s.charAt(i) ), 6);
    }
  };

  const getCode = function(c) {

    if ('0' <= c && c <= '9') {
      return c.charCodeAt(0) - '0'.charCodeAt(0);
    } else if ('A' <= c && c <= 'Z') {
      return c.charCodeAt(0) - 'A'.charCodeAt(0) + 10;
    } else {
      switch (c) {
      case '\u0020' : return 36;
      case '$' : return 37;
      case '%' : return 38;
      case '*' : return 39;
      case '+' : return 40;
      case '-' : return 41;
      case '.' : return 42;
      case '/' : return 43;
      case ':' : return 44;
      default :
        throw 'illegal char :' + c;
      }
    }
  };

  return _this;
};

//---------------------------------------------------------------------
// qr8BitByte
//---------------------------------------------------------------------

const qr8BitByte = function(data) {

  const _mode = QRMode.MODE_8BIT_BYTE;
  const _data = data;
  const _bytes = qrcode.stringToBytes(data);

  const _this = {};

  _this.getMode = function() {
    return _mode;
  };

  _this.getLength = function(buffer) {
    return _bytes.length;
  };

  _this.write = function(buffer) {
    for (let i = 0; i < _bytes.length; i += 1) {
      buffer.put(_bytes[i], 8);
    }
  };

  return _this;
};

//---------------------------------------------------------------------
// qrKanji
//---------------------------------------------------------------------

const qrKanji = function(data) {

  const _mode = QRMode.MODE_KANJI;
  const _data = data;

  const stringToBytes = qrcode.stringToBytes;
  !function(c, code) {
    // self test for sjis support.
    const test = stringToBytes(c);
    if (test.length != 2 || ( (test[0] << 8) | test[1]) != code) {
      throw 'sjis not supported.';
    }
  }('\u53cb', 0x9746);

  const _bytes = stringToBytes(data);

  const _this = {};

  _this.getMode = function() {
    return _mode;
  };

  _this.getLength = function(buffer) {
    return ~~(_bytes.length / 2);
  };

  _this.write = function(buffer) {

    const data = _bytes;

    let i = 0;

    while (i + 1 < data.length) {

      let c = ( (0xff & data[i]) << 8) | (0xff & data[i + 1]);

      if (0x8140 <= c && c <= 0x9FFC) {
        c -= 0x8140;
      } else if (0xE040 <= c && c <= 0xEBBF) {
        c -= 0xC140;
      } else {
        throw 'illegal char at ' + (i + 1) + '/' + c;
      }

      c = ( (c >>> 8) & 0xff) * 0xC0 + (c & 0xff);

      buffer.put(c, 13);

      i += 2;
    }

    if (i < data.length) {
      throw 'illegal char at ' + (i + 1);
    }
  };

  return _this;
};

//=====================================================================
// GIF Support etc.
//

//---------------------------------------------------------------------
// byteArrayOutputStream
//---------------------------------------------------------------------

const byteArrayOutputStream = function() {

  const _bytes = [];

  const _this = {};

  _this.writeByte = function(b) {
    _bytes.push(b & 0xff);
  };

  _this.writeShort = function(i) {
    _this.writeByte(i);
    _this.writeByte(i >>> 8);
  };

  _this.writeBytes = function(b, off, len) {
    off = off || 0;
    len = len || b.length;
    for (let i = 0; i < len; i += 1) {
      _this.writeByte(b[i + off]);
    }
  };

  _this.writeString = function(s) {
    for (let i = 0; i < s.length; i += 1) {
      _this.writeByte(s.charCodeAt(i) );
    }
  };

  _this.toByteArray = function() {
    return _bytes;
  };

  _this.toString = function() {
    let s = '';
    s += '[';
    for (let i = 0; i < _bytes.length; i += 1) {
      if (i > 0) {
        s += ',';
      }
      s += _bytes[i];
    }
    s += ']';
    return s;
  };

  return _this;
};

//---------------------------------------------------------------------
// base64EncodeOutputStream
//---------------------------------------------------------------------

const base64EncodeOutputStream = function() {

  let _buffer = 0;
  let _buflen = 0;
  let _length = 0;
  let _base64 = '';

  const _this = {};

  const writeEncoded = function(b) {
    _base64 += String.fromCharCode(encode(b & 0x3f) );
  };

  const encode = function(n) {
    if (n < 0) {
      throw 'n:' + n;
    } else if (n < 26) {
      return 0x41 + n;
    } else if (n < 52) {
      return 0x61 + (n - 26);
    } else if (n < 62) {
      return 0x30 + (n - 52);
    } else if (n == 62) {
      return 0x2b;
    } else if (n == 63) {
      return 0x2f;
    } else {
      throw 'n:' + n;
    }
  };

  _this.writeByte = function(n) {

    _buffer = (_buffer << 8) | (n & 0xff);
    _buflen += 8;
    _length += 1;

    while (_buflen >= 6) {
      writeEncoded(_buffer >>> (_buflen - 6) );
      _buflen -= 6;
    }
  };

  _this.flush = function() {

    if (_buflen > 0) {
      writeEncoded(_buffer << (6 - _buflen) );
      _buffer = 0;
      _buflen = 0;
    }

    if (_length % 3 != 0) {
      // padding
      const padlen = 3 - _length % 3;
      for (let i = 0; i < padlen; i += 1) {
        _base64 += '=';
      }
    }
  };

  _this.toString = function() {
    return _base64;
  };

  return _this;
};

//---------------------------------------------------------------------
// base64DecodeInputStream
//---------------------------------------------------------------------

const base64DecodeInputStream = function(str) {

  const _str = str;
  let _pos = 0;
  let _buffer = 0;
  let _buflen = 0;

  const _this = {};

  _this.read = function() {

    while (_buflen < 8) {

      if (_pos >= _str.length) {
        if (_buflen == 0) {
          return -1;
        }
        throw 'unexpected end of file./' + _buflen;
      }

      const c = _str.charAt(_pos);
      _pos += 1;

      if (c == '=') {
        _buflen = 0;
        return -1;
      } else if (c.match(/^\s$/) ) {
        // ignore if whitespace.
        continue;
      }

      _buffer = (_buffer << 6) | decode(c.charCodeAt(0) );
      _buflen += 6;
    }

    const n = (_buffer >>> (_buflen - 8) ) & 0xff;
    _buflen -= 8;
    return n;
  };

  const decode = function(c) {
    if (0x41 <= c && c <= 0x5a) {
      return c - 0x41;
    } else if (0x61 <= c && c <= 0x7a) {
      return c - 0x61 + 26;
    } else if (0x30 <= c && c <= 0x39) {
      return c - 0x30 + 52;
    } else if (c == 0x2b) {
      return 62;
    } else if (c == 0x2f) {
      return 63;
    } else {
      throw 'c:' + c;
    }
  };

  return _this;
};

//---------------------------------------------------------------------
// gifImage (B/W)
//---------------------------------------------------------------------

const gifImage = function(width, height) {

  const _width = width;
  const _height = height;
  const _data = new Array(width * height);

  const _this = {};

  _this.setPixel = function(x, y, pixel) {
    _data[y * _width + x] = pixel;
  };

  _this.write = function(out) {

    //---------------------------------
    // GIF Signature

    out.writeString('GIF87a');

    //---------------------------------
    // Screen Descriptor

    out.writeShort(_width);
    out.writeShort(_height);

    out.writeByte(0x80); // 2bit
    out.writeByte(0);
    out.writeByte(0);

    //---------------------------------
    // Global Color Map

    // black
    out.writeByte(0x00);
    out.writeByte(0x00);
    out.writeByte(0x00);

    // white
    out.writeByte(0xff);
    out.writeByte(0xff);
    out.writeByte(0xff);

    //---------------------------------
    // Image Descriptor

    out.writeString(',');
    out.writeShort(0);
    out.writeShort(0);
    out.writeShort(_width);
    out.writeShort(_height);
    out.writeByte(0);

    //---------------------------------
    // Local Color Map

    //---------------------------------
    // Raster Data

    const lzwMinCodeSize = 2;
    const raster = getLZWRaster(lzwMinCodeSize);

    out.writeByte(lzwMinCodeSize);

    let offset = 0;

    while (raster.length - offset > 255) {
      out.writeByte(255);
      out.writeBytes(raster, offset, 255);
      offset += 255;
    }

    out.writeByte(raster.length - offset);
    out.writeBytes(raster, offset, raster.length - offset);
    out.writeByte(0x00);

    //---------------------------------
    // GIF Terminator
    out.writeString(';');
  };

  const bitOutputStream = function(out) {

    const _out = out;
    let _bitLength = 0;
    let _bitBuffer = 0;

    const _this = {};

    _this.write = function(data, length) {

      if ( (data >>> length) != 0) {
        throw 'length over';
      }

      while (_bitLength + length >= 8) {
        _out.writeByte(0xff & ( (data << _bitLength) | _bitBuffer) );
        length -= (8 - _bitLength);
        data >>>= (8 - _bitLength);
        _bitBuffer = 0;
        _bitLength = 0;
      }

      _bitBuffer = (data << _bitLength) | _bitBuffer;
      _bitLength = _bitLength + length;
    };

    _this.flush = function() {
      if (_bitLength > 0) {
        _out.writeByte(_bitBuffer);
      }
    };

    return _this;
  };

  const getLZWRaster = function(lzwMinCodeSize) {

    const clearCode = 1 << lzwMinCodeSize;
    const endCode = (1 << lzwMinCodeSize) + 1;
    let bitLength = lzwMinCodeSize + 1;

    // Setup LZWTable
    const table = lzwTable();

    for (let i = 0; i < clearCode; i += 1) {
      table.add(String.fromCharCode(i) );
    }
    table.add(String.fromCharCode(clearCode) );
    table.add(String.fromCharCode(endCode) );

    const byteOut = byteArrayOutputStream();
    const bitOut = bitOutputStream(byteOut);

    // clear code
    bitOut.write(clearCode, bitLength);

    let dataIndex = 0;

    let s = String.fromCharCode(_data[dataIndex]);
    dataIndex += 1;

    while (dataIndex < _data.length) {

      const c = String.fromCharCode(_data[dataIndex]);
      dataIndex += 1;

      if (table.contains(s + c) ) {

        s = s + c;

      } else {

        bitOut.write(table.indexOf(s), bitLength);

        if (table.size() < 0xfff) {

          if (table.size() == (1 << bitLength) ) {
            bitLength += 1;
          }

          table.add(s + c);
        }

        s = c;
      }
    }

    bitOut.write(table.indexOf(s), bitLength);

    // end code
    bitOut.write(endCode, bitLength);

    bitOut.flush();

    return byteOut.toByteArray();
  };

  const lzwTable = function() {

    const _map = {};
    let _size = 0;

    const _this = {};

    _this.add = function(key) {
      if (_this.contains(key) ) {
        throw 'dup key:' + key;
      }
      _map[key] = _size;
      _size += 1;
    };

    _this.size = function() {
      return _size;
    };

    _this.indexOf = function(key) {
      return _map[key];
    };

    _this.contains = function(key) {
      return typeof _map[key] != 'undefined';
    };

    return _this;
  };

  return _this;
};

const createDataURL = function(width, height, getPixel) {
  const gif = gifImage(width, height);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      gif.setPixel(x, y, getPixel(x, y) );
    }
  }

  const b = byteArrayOutputStream();
  gif.write(b);

  const base64 = base64EncodeOutputStream();
  const bytes = b.toByteArray();
  for (let i = 0; i < bytes.length; i += 1) {
    base64.writeByte(bytes[i]);
  }
  base64.flush();

  return 'data:image/gif;base64,' + base64;
};


const stringToBytes = qrcode.stringToBytes;

// ---- blwp-client/src/qr.js
// THE DEPOSIT INVOICE AS A QR CODE (Daniel 2026-09-30: the deposit needs a QR code).
// A phone's Lightning wallet scans it instead of the player copying the invoice. Encoded here, in the pinned bundle, with
// qrcode-generator (MIT, no dependencies): a QR picture is what a player pays, so it is built by the same audited script
// that made the invoice, not by a loose one beside the page. BOLT11 is case-insensitive and its upper case fits the
// QR alphanumeric mode, as wallets write it; the `lightning:` scheme is the one wallets open.

/** An SVG tag of `lightning:<INVOICE>` as a QR code, error correction L. */
function invoiceQrSvg(invoice, { cellSize = 4, margin = 4 } = {}) {
  const text = String(invoice || '').trim();
  if (!/^ln[a-z0-9]+$/i.test(text)) throw new Error('that is not a Lightning invoice, so no QR code is drawn');
  const qr = qrcode(0, 'L');   // L: fewest modules - a screen, not a printed label, so no damage to recover from
  qr.addData(`LIGHTNING:${text.toUpperCase()}`, 'Alphanumeric');
  qr.make();
  return qr.createSvgTag({ cellSize, margin, scalable: true });
}

// ---- protocol/src/ghost.js
// A GHOST: A PICTURE OF ANOTHER PLAYER'S TRUCK, WHICH IS NEVER AN INPUT.
//
// 0.9: "Other trucks are visible ghosts with no collision. Another player must
// not be able to change my financial odds by ramming me, blocking a road,
// pushing me, damaging me, drawing my enemies away, pulling enemies toward me,
// sacrificing themselves for me, or colluding physically."
//
// 0.10 states the shape of the guarantee rather than a promise about it:
//
//     financial_world(p) = deterministic_sim(RoundContract, map, player_seed,
//                                            player_inputs)
//     Ghost snapshots are never inputs to this calculation.
//
// THE GUARANTEE IS THE MISSING PARAMETER, and it is already there: the core's
// `step(st, throttle, steer, brake, handbrake, practice)` has no argument a
// ghost could arrive through, and the state holds one truck at one `O_TRUCK`
// offset. Nothing in this file is a way in - it encodes a picture and says
// whether the picture is one somebody actually drove.
//
// A GHOST IS A PICTURE FROM A TRANSCRIPT, NOT A POSITION A NODE ANNOUNCES.
// Without that, a node fans out whatever coordinates it likes: a competitor
// painted somewhere they never were, or one who never entered at all. That is
// the same fault a payout table had before `payoutInputsId` and a census had
// before `censusInputsId` - the thing being asserted has to be bound to the
// inputs it came from. Here the binding already exists on the wire: §11's
// input chain. A ghost names the head of the chain it was taken from, exactly
// as a checkpoint does, so anyone holding that transcript can say whether the
// picture belongs to it.






/**
 * One picture: whose, when, from where in their chain, and where the truck was.
 *
 * THREE WORDS OF TRUCK AND NO MORE. `T_X`, `T_Z` and `T_HEADING` are what
 * draws a truck on a map; the core's other nine truck words - hp, cargo,
 * flags, wheel, throttle, steer, velocities, impact - are not carried, because
 * each one would be a claim about somebody's run that this frame cannot prove
 * and that nothing needs in order to render a ghost. 0.9 allows watching
 * competitors "drive, struggle, fail and arrive"; arriving and failing are the
 * leaderboard's to say, from signed results, not a 5 Hz picture's.
 *
 * The words are Q16.16, the units the core keeps, unscaled at this boundary
 * for the reason `encodeInputBatch` gives: a rounding rule applied here is a
 * rounding rule two implementations could differ on.
 */
function encodeGhost(g) {
  const w = new Writer();
  w.u8(TYPE_GHOST);
  w.u16(PROTOCOL_VERSION);
  w.bytes32(g.roundId);
  w.bytes32(g.entryId);

  // WHOSE TRUCK, named rather than looked up. The entry id identifies the run,
  // but a renderer holding one frame would have to hold every Entry Contract
  // to say who is driving. It is carried AND checked: `ghostBinds` refuses a
  // frame whose key is not the one that entry was signed for, so it is not a
  // label anybody can write - and when no entry is offered it is reported as
  // unchecked rather than believed.
  w.bytes32(g.playerPubkey);

  w.u32(g.tick);

  // WHERE IN THEIR INPUT CHAIN THIS WAS TAKEN. The head, the same value a
  // checkpoint commits to, and the whole reason a ghost cannot be invented.
  w.bytes32(g.inputChainHash);

  w.i32(g.x);
  w.i32(g.z);
  w.i32(g.heading);
  return w.finish();
}

function decodeGhost(bytes) {
  const r = new Reader(bytes);
  if (r.u8() !== TYPE_GHOST) throw new Error('not a ghost');
  if (r.u16() !== PROTOCOL_VERSION) throw new Error('unknown protocol version');
  const g = {
    roundId: r.bytes32(),
    entryId: r.bytes32(),
    playerPubkey: r.bytes32(),
    tick: r.u32(),
    inputChainHash: r.bytes32(),
    x: r.i32(),
    z: r.i32(),
    heading: r.i32(),
  };
  r.end();
  return g;
}

const ghostId = (g) => taggedHash(TAG.ghost, encodeGhost(g));

/** Fixed: nothing here is variable-length, so a reader can cut at a stride. */
const GHOST_BYTES = 1 + 2 + 32 + 32 + 32 + 4 + 32 + 4 + 4 + 4;

/**
 * IS THIS A PICTURE OF A RUN THAT HAPPENED?
 *
 * Answered against the transcript and nothing else - the same discipline
 * `censusRootMatchesRound` needed for its entries: whoever shows the picture
 * does not get to choose what it is checked against.
 *
 * Three things have to hold, and none of them is about the coordinates. This
 * cannot say the truck was AT x,z - only a replay says that, and a replay is
 * the objection path's job (§13A), not a 5 Hz frame's. What it can say is that
 * the frame belongs to a run somebody published inputs for:
 *
 *   - the round and the entry are this transcript's
 *   - the head it names is one this transcript actually reaches, which is
 *     §11's "a transcript whose inputs were never published cannot be
 *     replayed" applied to a picture instead of a mark
 *   - the tick is one those inputs cover
 *
 * GENESIS IS NOT A HEAD A PICTURE CAN COME FROM. It is the head before any
 * input went out, so a ghost on it is a picture of a truck that has not been
 * driven yet - which is exactly the frame a node would fabricate for a
 * competitor who never entered.
 */
function ghostBinds(ghost, transcript, entry) {
  if (!ghost || !(ghost.inputChainHash instanceof Uint8Array))
    return { ok: false, why: 'that ghost names no input chain head' };
  if (!transcript || !Array.isArray(transcript.batches))
    return { ok: false, why: 'no transcript to check that ghost against' };

  const same = (a, b) => a instanceof Uint8Array && b instanceof Uint8Array
    && a.length === b.length && a.every((v, i) => v === b[i]);

  if (!same(ghost.roundId, transcript.roundId))
    return { ok: false, why: 'that ghost is for another round' };
  if (!same(ghost.entryId, transcript.entryId))
    return { ok: false, why: 'that ghost is for another entry' };

  // AND IF AN ENTRY IS OFFERED, THE KEY IS THAT ENTRY'S. Not optional in the
  // sense of nice-to-have: a caller that has the entry gets the check, and a
  // caller that does not is told the key was not checked rather than left to
  // assume it was.
  const unchecked = [];
  if (entry) {
    if (!same(entryId(entry), ghost.entryId))
      return { ok: false, why: 'that is a different entry than the ghost names' };
    if (!same(entry.playerPubkey, ghost.playerPubkey))
      return { ok: false, why: 'that ghost names a key that entry was not signed for' };
  } else {
    unchecked.push('the player key (no entry contract offered to check it against)');
  }

  if (same(ghost.inputChainHash, GENESIS))
    return {
      ok: false,
      why: 'that ghost is taken before any input went out, so there is nothing '
        + 'it could be a picture of',
    };

  // Walk the chain the way `checkTranscript` does, and stop at the head the
  // ghost names. What that head covers is every tick up to the last one of the
  // batch that produced it.
  let previous = GENESIS;
  let firstTick = null;
  for (const b of transcript.batches) {
    if (!same(b.previousHash, previous))
      return { ok: false, why: 'that transcript\'s input chain is broken' };
    const at = batchTicks(b);
    if (firstTick === null && at.length) firstTick = at[0];
    previous = batchId(b);

    if (same(previous, ghost.inputChainHash)) {
      if (!at.length)
        return { ok: false, why: 'that head carries no ticks to be a picture of' };
      if (ghost.tick < firstTick || ghost.tick > at[at.length - 1])
        return {
          ok: false,
          why: `that ghost is at tick ${ghost.tick}, and the inputs it names `
            + `cover ${firstTick} to ${at[at.length - 1]}`,
        };
      return { ok: true, throughTick: at[at.length - 1], unchecked };
    }
  }

  return {
    ok: false,
    why: `no batch of that transcript hashes to ${toHex(ghost.inputChainHash).slice(0, 16)}, `
      + 'so that picture was taken from inputs nobody published',
  };
}

// ---- blwp-client/src/bond.js
// THE BOND, IN A BLOCK THAT WAS ACTUALLY MINED.
//
// Section 25.1 gives a browser three lines of work: headers from several
// independent sources with most work winning, "bond transaction plus a merkle
// proof, from any chain API", and then "verify: proof against header,
// H(advertisement) against the bond output's commitment".
//
// The first line is `headers.js` and it needs AGREEMENT, because the weight of
// a chain means nothing except in comparison. This line does not, and the
// difference is worth saying out loud rather than copying the pattern: a bond
// proof carries its own proof. It rebuilds a merkle root that a mined header
// already commits to, so a provider cannot forge one at any price - the only
// lie available is to withhold it, and withholding is answered by asking the
// next provider, not by taking a vote.
//
// SO ONE PROVIDER IS ENOUGH HERE, and two are needed there, and neither is a
// preference.



/**
 * Does this proof land in a block of this chain?
 *
 * The chain is re-checked here rather than taken on the caller's word - it is
 * one pass over headers that are already in hand, and it is the difference
 * between "a block" and "80 bytes somebody handed me". Every header in a chain
 * that passes has met the target it claims, so a fabricated header carrying a
 * merkle root of the attacker's choosing cannot be the block a bond is proven
 * into: the chain holding it is not a chain.
 *
 * The txid is computed from the transaction, never accepted beside it, for the
 * same reason it is computed in `acceptAdvert`.
 */
function provenBond({ chain, transaction, branch, position }) {
  const linked = chainWork(chain || []);
  if (!linked.ok)
    return { ok: false, why: `that is not a mined chain: ${linked.why}` };

  let tx;
  try { tx = parseTransaction(transaction); }
  catch (e) { return { ok: false, why: `that is not a transaction: ${e.message}` }; }

  for (const header of chain) {
    if (!provesTransaction(header, tx.txid, branch, position)) continue;
    return {
      ok: true,
      txid: tx.txid,
      transaction,
      branch,
      position,
      header,
      blockHash: blockHashOf(header),
    };
  }
  return {
    ok: false,
    why: `the transaction ${toHex(tx.txid.slice().reverse())} is not proven `
      + 'into any block of that chain',
  };
}

/**
 * Ask providers for a bond until one of them proves it.
 *
 * IN ORDER, AND THE FIRST PROOF WINS, which is not laziness: a proof is not an
 * opinion, so there is nothing for a second provider to add except the same
 * bytes. What a second provider is for is the case where the first says
 * nothing - "omission is answered by asking a second one" - and that is why
 * every refusal is kept and handed back rather than swallowed.
 *
 * A provider is a function, like a header provider is, and for the same
 * reason: the shape a chain API puts a merkle proof in is nobody's standard,
 * and writing one API's field names into the client would be adopting a second
 * protocol without saying so.
 */
async function askForBond(providers, { chain, ask, timeoutMs = 10000 } = {}) {
  const refused = [];
  for (let at = 0; at < (providers || []).length; at++) {
    let timer;
    try {
      const stop = new AbortController();
      const offer = await Promise.race([
        Promise.resolve().then(() => providers[at](ask, { signal: stop.signal })),
        new Promise((_, no) => {
          timer = setTimeout(() => {
            stop.abort();
            no(new Error(`no answer in ${timeoutMs} ms`));
          }, timeoutMs);
          if (timer.unref) timer.unref();
        }),
      ]);
      const seen = provenBond({ chain, ...offer });
      if (seen.ok) return { ...seen, from: at, refused };
      refused.push(`provider ${at}: ${seen.why}`);
    } catch (e) {
      refused.push(`provider ${at}: ${e.message}`);
    } finally { clearTimeout(timer); }
  }
  return {
    ok: false,
    why: refused.length
      ? 'no provider proved that bond into the chain'
      : 'no providers to ask for the bond',
    refused,
  };
}

// ---- blwp-client/src/directory.js
// WHERE TO TALK, AND WHY.
//
// Section 25.1: "A client finds nodes by reading Bitcoin. There is no
// directory, no relay network and no seed list belonging to this protocol."
// This file is the client's half of step 4 - "where do I reach them? the
// NodeAdvertisement, carried by the bond funding transaction".
//
// WHAT IT REPLACES. The endpoint used to be `BLWP_NODE`, a page global. Every
// stranger who loaded the page reached whatever address whoever shipped the
// page had written into it, and there was nothing in the client that could
// tell a real node from any other server. Section 25.1 is normative about
// exactly that: a client "MUST NOT take a census, a committee or an endpoint on
// the word of any API, including one operated by the same party that ships the
// client", because "there is no symptom to notice and nothing for the player to
// check".
//
// A PAGE MAY STILL CARRY THE BYTES. That is not the same thing and it is the
// whole design: the page hands over a transaction, a branch and headers, and
// none of those are things it can choose. The txid is computed from the
// transaction, the branch has to rebuild a header's own merkle root, and the
// endpoint is only read out of a body an output of that transaction commits
// to. A page that swaps the endpoint is refused by name.
//
// WHAT IS STILL MISSING, AND IT IS NOT THIS SLICE. Where the headers come from.
// One source cannot be weighed: "block headers from several independent
// sources, most work wins", and then "a list provider can omit but not forge,
// and omission is answered by asking a second one". `mostWork` is here and takes
// as many chains as it is given - nothing fetches yet, and until something does,
// a client is only as sure as the chain it was handed.





/**
 * Is this a socket address at all?
 *
 * Section 25.1: "Then connect `wss://` to the `endpoint` from the verified
 * advertisement." The endpoint is a string a bonded operator committed to on
 * chain, which makes it THEIRS - it does not make it a URL. Without this the
 * client would take whatever was committed and hand it to `WebSocket` after a
 * blind `replace(/^ws/, 'http')`, so a body carrying `http://...`, a bare
 * host, or something that is not an address at all would become the base a
 * round is played on.
 *
 * `ws://` is allowed for loopback only, because a test node on this machine
 * has no certificate and refusing it would mean the tests could not drive the
 * real door. Nothing else: a plaintext socket to another host is exactly the
 * one thing a committed endpoint must not be able to ask a player for.
 */
const LOOPBACK = /^ws:\/\/(127\.0\.0\.1|localhost|\[::1\])(:\d+)?(\/|$)/;
function isSocketAddress(endpoint) {
  if (typeof endpoint !== 'string') return false;
  if (LOOPBACK.test(endpoint)) return true;
  return /^wss:\/\/[^/?#\s]+(\/|$)/.test(endpoint);
}

/**
 * The endpoint, or the reason there is not one.
 *
 * The proof is tried against every header of the best chain rather than
 * against a header named by the caller: being handed a header is not being
 * handed a block, and a header that is not in the chain the client accepted is
 * one somebody made up. The transaction has to be in a block that is in the
 * chain, not merely in something 80 bytes long.
 *
 * AND THE NODE HAS TO BE ONE OF THIS ROUND'S. Section 25.1 is four steps, and
 * step 3 - "which are on the committee?" - is computed rather than fetched, so
 * the answer is already in the round's own contract. Step 4 is "where do I
 * reach THEM". Proving an advertisement without reading step 3's answer proves
 * only that somebody, somewhere, posted a bond: a page could hand over a real,
 * bonded, header-proven node with no standing in this round and the client
 * would open the round there and publish its whole section 11 transcript to a
 * stranger before the first receipt refused. A committee is therefore
 * REQUIRED, not optional - an absent one is a refusal, because the version of
 * this that takes an empty list and shrugs is the version that ships.
 */
function reach({
  chain, chains, transaction, signedAdvert, branch, position, committee, bond, network,
}) {
  if (!committee || !committee.length)
    return { ok: false, why: 'no committee to check the node against' };

  // A CHAIN THAT WAS ALREADY AGREED, or a list to weigh here. `chain` is what
  // `agreedChain` hands back after two independent providers were compared,
  // and it is the one a live client should be passing: weighing a single list
  // handed over by one party is arithmetic, not evidence. Both are re-checked
  // - every header must link and must have met the target it claims - so a
  // fabricated block cannot be the one a bond is proven into whichever door it
  // came through.
  let headers; let work; let from = null;
  if (chain) {
    const linked = chainWork(chain);
    if (!linked.ok) return { ok: false, why: `that is not a mined chain: ${linked.why}` };
    headers = chain; work = linked.work;
  } else {
    const best = mostWork(chains || []);
    if (!best) return { ok: false, why: 'no chain of headers to check against' };
    headers = best.headers; work = best.work; from = best.at;
  }

  let refusal = 'the transaction is not in any block of that chain';
  for (const header of headers) {
    // The bond option travels with it: a page holding the network's
    // arbitration set and a curve can have the output key rebuilt, and one
    // that holds neither gets exactly what it got before.
    const seen = acceptAdvert({ transaction, signedAdvert, header, branch, position, bond, network });
    if (!seen.ok) {
      // A header that proves the transaction and then fails on the commitment
      // is a more specific answer than "not in this one", and it is the answer
      // that matters: the block is real and the endpoint was swapped anyway.
      if (seen.why !== 'the transaction is not in that block') refusal = seen.why;
      continue;
    }

    if (!committee.some((n) => toHex(n) === toHex(seen.nodePubkey))) {
      return {
        ok: false,
        why: `the advertisement is for ${toHex(seen.nodePubkey)}, `
          + "which is not on this round's committee",
      };
    }
    if (!isSocketAddress(seen.endpoint)) {
      return {
        ok: false,
        why: `the advertisement's endpoint ${JSON.stringify(seen.endpoint)} `
          + 'is not a secure socket address',
      };
    }

    return {
      ok: true,
      endpoint: seen.endpoint,
      nodePubkey: seen.nodePubkey,
      signature: seen.signature,
      advertId: advertId(seen.advert),
      txid: seen.txid,
      blockHash: blockHashOf(header),
      work,
      from,
    };
  }
  return { ok: false, why: refusal };
}

/**
 * The base URL a client talks to, from a proven advertisement only.
 *
 * Throws rather than answering, because there is no degraded mode here: a
 * client that could not prove where to go has nothing to fall back to that
 * would not be the page's word again.
 *
 * THIS DOES NOT CHECK THE SIGNATURE - it cannot, because verifying is
 * asynchronous in a browser and this answer is wanted synchronously, and
 * because a curve does not belong in this package. It is a gate, not the door:
 * `Client.at` is the door, it is asynchronous, and nothing is sent to the node
 * until the signature has verified there.
 */
function endpointFor(discovery) {
  const seen = reach(discovery);
  if (!seen.ok) throw new Error(`no proven endpoint: ${seen.why}`);
  // 25.1 connects `wss://` to the endpoint; the client's own base is the HTTP
  // origin of the same node, and `connect()` turns it back into a socket.
  return seen.endpoint.replace(/^ws/, 'http');
}

/**
 * THE WHOLE OF STEP 4, FROM PROVIDERS RATHER THAN FROM A PAGE.
 *
 * Everything above this was a library nothing used. `reach` verified whatever
 * chain it was handed, which proves that a chain and a proof agree with each
 * other and NOTHING about Bitcoin: a page that wrote both wrote a consistent
 * pair. Section 25.1 is normative about what a CLIENT does, so until the door
 * asks providers itself, the chain source is not the client's chain source.
 *
 * A PROVIDER IS A FUNCTION AND THE CLIENT SPEAKS BITCOIN'S OWN SHAPES:
 * 80-byte headers back to back, and a merkle proof as 32-byte hashes with an
 * index. No explorer's JSON is parsed in here and no host or path is written
 * here. Translating a real chain API into these functions is an adapter, it
 * belongs to whoever runs the page or the node, and it is deliberately not
 * part of this package - a client that spoke one explorer's schema would have
 * adopted a second protocol without saying so.
 *
 * `anchor` is an argument for the same reason: which block a deployment
 * anchors on is a constant somebody must choose, and choosing it here would
 * settle it by accident.
 */
/** Two, and it is the whole property rather than a setting. */
const PROVIDERS_NEEDED = 2;

/** How long the client waits on a provider before giving up on it. */
const PROVIDER_WAIT_MS = 10000;

async function discover({
  headers, bonds, anchor, committee, signedAdvert, ask, least, timeoutMs, proved,
}) {
  // THE RULES ARE THE CLIENT'S. THE PAGE SAYS WHERE TO ASK, AND NOTHING ELSE.
  //
  // Each of these was a caller's argument, which meant a page's argument, and
  // each one alone undoes the whole chain source:
  //
  //   least       set it to 1 and "several independent sources, most work
  //               wins" becomes one source, whose short chain and whose
  //               hidden block are the same bytes. Measured before this was
  //               refused: a page passing `least: 1` opened a round on a
  //               single provider it also supplied.
  //   timeoutMs   how long a client waits is the client's patience, not the
  //               page's. Zero refuses every honest provider; enormous hangs
  //               the run on one the page controls.
  //
  // `ask` is deliberately NOT here. It names the range of chain to fetch, and
  // a lie about it can only omit - which is what a second provider answers.
  // AND EVERY PROVIDER HAS TO SAY WHO IT IS.
  //
  // "Several independent SOURCES" is the rule, and a source is a server, not a
  // call. Two functions closing over one address are one source however they
  // are listed, and on this path the page writes the functions - so without a
  // declared tag the two-provider floor counted calls, which is weaker than
  // the words and is the same shape of hole as `least`: a rule that held in
  // the library and never fired at the door.
  //
  // A tag is a DECLARATION and not a proof. A page that puts two different
  // tags on one machine is believed, and cannot be caught from in here: two
  // honest providers on the same chain return the same bytes, so there is no
  // signal to read. What the tag buys is that the obvious case - one address
  // listed twice - is refused, and that a lie has to be written down as a lie
  // rather than being the default.
  for (const [what, list] of [['header', headers], ['bond', bonds]]) {
    const said = new Map();
    for (let i = 0; i < (list || []).length; i++) {
      const tag = list[i] && list[i].tag;
      if (typeof tag !== 'string' || !tag.length)
        return {
          ok: false,
          why: `${what} provider ${i} does not say which source it is: a `
            + 'provider must carry a tag, or two calls to one server count as two sources',
        };
      if (said.has(tag))
        return {
          ok: false,
          why: `${what} providers ${said.get(tag)} and ${i} are the same source, `
            + `${tag}: one server listed twice is not two`,
        };
      said.set(tag, i);
    }
  }

  for (const [name, value] of [['least', least], ['timeoutMs', timeoutMs]]) {
    if (value !== undefined)
      return {
        ok: false,
        why: `${name} is the client's own and may not be supplied: how many `
          + 'providers must agree, and how long to wait for them, are not '
          + 'settings for whoever handed over the providers',
      };
  }

  // THE ANCHOR IS THE CLIENT'S, AND A PAGE THAT OFFERS ONE IS REFUSED.
  //
  // This was the last hop where the whole chain source came apart. Weighing,
  // mining and the bond proof were all honest, and then the block everything
  // was anchored TO arrived from the page - so an attacker who supplied the
  // providers supplied the block he wanted to sit on, and his own little mined
  // world contained it by construction. An anchor somebody else chooses is not
  // an anchor; it is the same trust, one level down, wearing the word.
  //
  // Genesis is the one block that needs no decision from anybody: it is
  // mainnet's identity, it cannot go stale, and anyone can check it. Whether a
  // deployment later anchors on a nearer block to avoid carrying history is a
  // constant somebody must choose, and choosing it here would settle it by
  // accident.
  if (anchor !== undefined)
    return {
      ok: false,
      why: 'the anchor is the client\'s own and may not be supplied: a block '
        + 'chosen by whoever handed over the chain is not a block the client knows',
    };

  // A CHAIN THIS PAGE HAS ALREADY PROVED IS NOT PROVED AGAIN FOR THE NEXT ROUND (Daniel 2026-09-18 16:45).
  //
  // Measured in two real browsers: on PLAY again both tabs joined the next round and neither got a client, because
  // this read wants both signer nodes inside PROVIDER_WAIT_MS and a starved tab took 8746 ms for 240 bytes - where
  // curl on the same host gets them in 0.52 s. The page then sat in a joined round with nothing publishing, and the
  // other tab was shown no truck at all for the whole round.
  //
  // Headers do not change behind us: a chain proved a minute ago is the same chain, and the round that follows is
  // played under it. So a caller may hand back what it proved, and only a page that has never proved one reads.
  // WHAT IS NOT REUSED IS THE BOND: it is checked against the chain every time, and a bond in a block the old proof
  // does not reach refuses here - which is the one case that falls back to a fresh read rather than failing.
  let chain = proved && proved.ok && Array.isArray(proved.headers) && proved.headers.length ? proved : null;
  let reusedChain = !!chain;
  if (!chain) {
    chain = await agreedChain(headers, {
      anchor: BITCOIN_MAINNET_GENESIS, ask,
      least: PROVIDERS_NEEDED, timeoutMs: PROVIDER_WAIT_MS,
    });
    if (!chain.ok) return { ok: false, why: `no chain: ${chain.why}`, refused: chain.refused };
  }

  let bond = await askForBond(bonds, {
    chain: chain.headers, ask, timeoutMs: PROVIDER_WAIT_MS,
  });
  if (!bond.ok && reusedChain) {
    // THE KEPT PROOF DID NOT CARRY THIS ROUND'S BOND: read the chain afresh once and try again, rather than playing
    // under a chain that cannot reach it. IF THAT READ FAILS, the answer is still the BOND's own refusal: the kept
    // proof was good enough to be asked, and replacing the reason with "no chain" would name the wrong fault.
    const bondWhy = bond.why, bondRefused = bond.refused;
    reusedChain = false;
    const fresh = await agreedChain(headers, {
      anchor: BITCOIN_MAINNET_GENESIS, ask,
      least: PROVIDERS_NEEDED, timeoutMs: PROVIDER_WAIT_MS,
    });
    if (!fresh.ok) return { ok: false, why: `no bond: ${bondWhy}`, refused: bondRefused };
    chain = fresh;
    bond = await askForBond(bonds, { chain: chain.headers, ask, timeoutMs: PROVIDER_WAIT_MS });
  }
  if (!bond.ok) return { ok: false, why: `no bond: ${bond.why}`, refused: bond.refused };

  const seen = reach({
    chain: chain.headers,
    transaction: bond.transaction,
    branch: bond.branch,
    position: bond.position,
    signedAdvert,
    committee,
  });
  if (!seen.ok) return seen;
  return {
    ...seen,
    work: chain.work,
    agreed: chain.agreed,
    fromChain: chain.from,
    fromBond: bond.from,
    // WHAT WAS PROVED, so the next round of this same page can be opened from it instead of reading the headers
    // again, and whether this call read or reused.
    chain,
    reusedChain,
  };
}

// ---- protocol/src/donation-keys.js
/**
 * THE DONATION AUTHORITY AND RECOVERY KEYS, BY THE NETWORK ID A ROUND CONTRACT
 * CARRIES (M3.2 6e, §27A.4). A signer node and a page know a round's network by its
 * id, not by a name; a network with no generated donation authority answers
 * null. Its own module, reading only genesis-ids.js, so the page bundle can use
 * it without genesis.js (which reads the core's game rules).
 */


function donationKeysForNetworkId(networkId) {
  const is = (known) => networkId instanceof Uint8Array && networkId.length === 32
    && networkId.every((x, i) => x === known[i]);
  if (is(NETWORK_ID_REGTEST)) return { network: 'regtest', authority: AUTHORITY_PUBKEY_REGTEST, recovery: RECOVERY_PUBKEY_REGTEST };
  if (is(NETWORK_ID_TESTNET4)) return { network: 'testnet4', authority: AUTHORITY_PUBKEY_TESTNET4, recovery: RECOVERY_PUBKEY_TESTNET4 };
  // PICK B (old-series.js): the same testnet4 authority signed the set series 3cfbe516 names under the old id
  if (isOldTestnet4Id(networkId)) return { network: 'testnet4', authority: AUTHORITY_PUBKEY_TESTNET4, recovery: RECOVERY_PUBKEY_TESTNET4 };
  return null;
}

// ---- protocol/src/lnurl-pay.js
/**
 * LNURL-PAY (LUD-06, LUD-12), THE DONOR'S SIDE, AS RULES (M3.2 item 6e;
 * ruled 2026-09-13).
 *
 * A donation share is paid to a recipient's LNURL endpoint: the wallet asks the
 * endpoint for its pay request, asks the callback for an invoice of exactly the
 * share, and pays it only if the invoice is that - "the invoice amount equals
 * the user's requested amount" and "the description hash matches SHA256 of the
 * metadata string" (LUD-06, MUST). These are the decisions; the fetching and
 * the paying are the client's.
 *
 * The comment is the player's public key as hex (§22A, Daniel 2026-09-08), and
 * it is left out when the endpoint takes fewer than 64 characters (LUD-12).
 */


/** A player's public key as hex is 64 characters; an endpoint allowing fewer gets no comment. */
const COMMENT_KEY_CHARS = 64;

/** Does this first answer stand as a pay request for `amountMsat`? `{ ok, callback, metadata, commentAllowed }` or why not. */
/**
 * A LIGHTNING ADDRESS IS AN LNURL-PAY ENDPOINT WITH A FRIENDLIER SPELLING (LUD-16).
 *
 * `name@host` means `https://host/.well-known/lnurlp/name`, and nothing else: no redirect is followed
 * here, no scheme is guessed, and a host with a path or a port dressed into it is refused rather than
 * normalised. It is where a player's winnings are sent when they have no NWC wallet connected (Daniel
 * 2026-09-21 13:54), so it is checked the way an address that money leaves for should be.
 *
 * `.onion` is allowed over http, because that is what LUD-16 says and a Tor host cannot hold a
 * certificate; everything else is https.
 */
function lightningAddressEndpoint(address) {
  const said = String(address || '').trim().toLowerCase();
  if (!said) return { ok: false, why: 'there is no Lightning address here' };
  const at = said.indexOf('@');
  if (at <= 0 || said.indexOf('@', at + 1) !== -1)
    return { ok: false, why: `${said} is not a Lightning address: it is name@host` };
  const name = said.slice(0, at);
  const host = said.slice(at + 1);
  if (!/^[a-z0-9._-]+$/.test(name))
    return { ok: false, why: 'the name of a Lightning address is letters, digits, dot, dash or underscore' };
  if (!/^[a-z0-9.-]+(:[0-9]{1,5})?$/.test(host) || host.startsWith('.') || host.endsWith('.'))
    return { ok: false, why: `${host} is not a host a Lightning address can name` };
  const scheme = /\.onion(:[0-9]{1,5})?$/.test(host) ? 'http' : 'https';
  return { ok: true, url: `${scheme}://${host}/.well-known/lnurlp/${name}`, name, host };
}

function payRequestStands(said, amountMsat) {
  if (!said || typeof said !== 'object') return { ok: false, why: 'the endpoint did not answer with a pay request' };
  if (said.status === 'ERROR') return { ok: false, why: `the endpoint refused: ${String(said.reason || '').slice(0, 120)}` };
  if (said.tag !== 'payRequest') return { ok: false, why: `the endpoint answered a "${String(said.tag).slice(0, 20)}", not a payRequest` };
  if (typeof said.callback !== 'string' || !/^https?:\/\//.test(said.callback))
    return { ok: false, why: 'the pay request names no callback URL' };
  if (typeof said.metadata !== 'string') return { ok: false, why: 'the pay request carries no metadata to hash' };
  const min = said.minSendable;
  const max = said.maxSendable;
  if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max) || min < 1 || min > max)
    return { ok: false, why: 'the pay request names no sendable range' };
  if (typeof amountMsat !== 'bigint' || amountMsat < BigInt(min) || amountMsat > BigInt(max))
    return { ok: false, why: `${amountMsat} msat is outside what the endpoint takes (${min}..${max} msat)` };
  const commentAllowed = Number.isSafeInteger(said.commentAllowed) && said.commentAllowed > 0 ? said.commentAllowed : 0;
  return { ok: true, callback: said.callback, metadata: said.metadata, commentAllowed };
}

/** The callback asked for exactly `amountMsat`, with the comment only if the endpoint takes a whole key. */
function callbackFor({ callback, amountMsat, comment, commentAllowed = 0 }) {
  const u = new URL(callback);
  u.searchParams.set('amount', String(amountMsat));
  if (comment && commentAllowed >= COMMENT_KEY_CHARS && String(comment).length <= commentAllowed)
    u.searchParams.set('comment', String(comment));
  return u.toString();
}

/** Round networks as an invoice names them. */
const INVOICE_NETWORK = { regtest: 'regtest', testnet4: 'testnet', testnet: 'testnet', bitcoin: 'bitcoin', mainnet: 'bitcoin' };

/**
 * IS THIS THE INVOICE THE SHARE MAY BE PAID WITH? Exactly `amountMsat`, under
 * the endpoint's own metadata hash, and - when named - on the round's network.
 */
function invoiceAnswersPayRequest({ invoice, amountMsat, metadata, network } = {}) {
  if (typeof invoice !== 'string' || !invoice) return { ok: false, why: 'the callback handed no invoice' };
  let d;
  try { d = decodeBolt11(invoice); }
  catch (e) { return { ok: false, why: `that is not an invoice: ${e.message}` }; }
  if (d.amountMsat !== amountMsat)
    return { ok: false, why: `the invoice asks ${d.amountMsat === null ? 'any amount' : `${d.amountMsat} msat`}, and this recipient's share is ${amountMsat} msat` };
  const want = sha256(new TextEncoder().encode(String(metadata)));
  if (!d.descriptionHash || toHex(d.descriptionHash) !== toHex(want))
    return { ok: false, why: 'the invoice\'s description hash is not the endpoint\'s own metadata (LUD-06)' };
  if (network && INVOICE_NETWORK[network] && d.network !== INVOICE_NETWORK[network])
    return { ok: false, why: `that invoice is for ${d.network}, and this round is on ${network}` };
  return { ok: true, paymentHash: d.paymentHash, amountMsat: d.amountMsat, network: d.network };
}

// ---- protocol/src/authority.js
// 27A.4: WHICH DONATION SET IS THE NETWORK'S, FROM WHEN, AND WHO SAID SO.
//
// `donation.js` answers a different question and answers it well: given a list
// of payees and shares, does it stand, and what is each owed. It cannot answer
// this one. A list that stands is a list ANYBODY can write - the bytes are
// checked against their own shares and against nothing else - so before this
// file a thief and the network's own operator published objects that were
// indistinguishable.
//
// The section gives the object:
//
//     DonationSet {
//       network_id
//       serial          monotonic; the highest validly signed one wins
//       entries[]       lnurl + share_bps, summing to 10000
//       valid_from      block height
//       signature       by donation_authority_pubkey
//     }
//
// Four of those five fields had no code. What each one is for, in the order
// they stop a different failure:
//
//   network_id   27A.9: "the trust anchor is the client's own built-in
//                network_id, NEVER A VALUE FROM THE CONTRACT". A set for
//                another network is somebody else's payees, and forking the
//                code to write your own address in "has not captured the
//                donations - you have left".
//   serial       Two sets and no order is two nodes paying different people.
//                The highest validly signed one wins, and an older one
//                published later changes nothing - that is what "cannot be
//                rolled back" means when the publication is on a chain that
//                anybody can add to.
//   valid_from   A set with no start applies from whenever each node happened
//                to see it, which is not a time two nodes can agree on.
//   signature    The whole point. One key signs this object and nothing else
//                in the protocol.
//
// AND THE ROTATION, which is the half that is easy to leave for later and must
// not be. 27A.4's own row: authority stolen, "the thief signs a set with a
// higher serial pointing at their own LNURLs" - and the remedy is a rotation
// from the cold key, "no fork, the census survives". A revocation path nobody
// has exercised is a revocation path that does not work, so the rotation here
// is not a field: it is checked, it is ordered, and from its `valid_from` the
// old key's sets are refused whatever serial they carry.
//
// WHAT THE KEYS CANNOT DO is not enforced here because it cannot be reached
// from here: 27A.4's exhaustive list - no pause, no fee, no threshold, no
// node, no round, no result, no player's money - is a statement about which
// objects carry an authority signature, and this file is the only one that
// checks for one. Nothing else in the protocol reads these keys, and that is
// the enforcement.
//
// NO CURVE, like every other file in this package: `verify` is injected, and
// the caller one package over brings the real BIP-340. NO MONEY: nothing here
// pays an LNURL, and what a donation costs a player is 6e's letter, not this
// one.




/** The 64 bytes beside the object, as for every other signature in here. */
const DONATION_SIGNATURE_BYTES = 64;

const isDonationBytes32 = (b) => b instanceof Uint8Array && b.length === 32;
const sameDonationBytes32 = (a, b) => a.every((x, i) => x === b[i]);

/**
 * THE BYTES THE AUTHORITY SIGNS.
 *
 * The recipients go in AS THE SET'S OWN ENCODING - `encodeDonationSet`, the
 * function 22A's id is taken over - and not as a second copy of the same
 * vector written out again here. A signed publication holding a differently
 * encoded version of the list would be an object whose signature covers bytes
 * that are not the set the Round Contract names, and then the network's
 * authority has endorsed one thing while the round binds another.
 *
 * That import also means a set that does not stand cannot be published: the
 * encoder refuses it, so there are no signed bytes naming shares that sum to
 * 9999.
 */
function encodeDonationSetBody(set) {
  if (!isDonationBytes32(set.networkId)) throw new Error('a donation set names a 32-byte network');
  if (typeof set.serial !== 'bigint') throw new Error('a serial is a BigInt');
  if (set.serial < 0n) throw new Error('a serial cannot be negative');
  if (!Number.isInteger(set.validFrom) || set.validFrom < 0)
    throw new Error('valid_from is a block height');

  const entries = encodeDonationSet(set.recipients);
  const w = new Writer();
  w.u8(TYPE_SIGNED_DONATION_SET);
  w.u16(PROTOCOL_VERSION);
  w.bytes32(set.networkId);
  w.u64(set.serial);
  w.u32(set.validFrom);
  w.u16(entries.length);
  w.bytes(entries);
  return w.finish();
}

function decodeDonationSetBody(bytes) {
  const r = new Reader(bytes);
  if (r.u8() !== TYPE_SIGNED_DONATION_SET) throw new Error('not a signed donation set');
  if (r.u16() !== PROTOCOL_VERSION) throw new Error('unknown protocol version');
  const networkId = r.bytes32();
  const serial = r.u64();
  const validFrom = r.u32();
  const entries = r.bytes(r.u16());
  if (r.at !== bytes.length) throw new Error('trailing bytes after the donation set');
  // Through the set's own decoder, so a publication inherits every check the
  // list has: the shares, the duplicates, the mixed case, and the one byte
  // string a set is allowed to have.
  return { networkId, serial, validFrom, recipients: decodeDonationSet(entries) };
}

/** What a marked output commits to: H(DonationSet), 27A.4's publication. */
const donationSetBodyId = (set) =>
  taggedHash(TAG.signedDonationSet, encodeDonationSetBody(set));

/**
 * THE COLD KEY'S ONLY SENTENCE.
 *
 *     AuthorityRotation { network_id, serial, new_authority, valid_from,
 *                         signature by donation_recovery_pubkey }
 *
 * Its own serial, "monotonic, separate from the donation set's", because the
 * two objects are ordered against their own kind: a rotation is not newer than
 * a set and the question never arises.
 */
function encodeAuthorityRotation(rotation) {
  if (!isDonationBytes32(rotation.networkId)) throw new Error('a rotation names a 32-byte network');
  if (typeof rotation.serial !== 'bigint') throw new Error('a serial is a BigInt');
  if (rotation.serial < 0n) throw new Error('a serial cannot be negative');
  if (!isDonationBytes32(rotation.newAuthority))
    throw new Error('a rotation names a 32-byte authority key');
  if (!Number.isInteger(rotation.validFrom) || rotation.validFrom < 0)
    throw new Error('valid_from is a block height');

  const w = new Writer();
  w.u8(TYPE_AUTHORITY_ROTATION);
  w.u16(PROTOCOL_VERSION);
  w.bytes32(rotation.networkId);
  w.u64(rotation.serial);
  w.bytes32(rotation.newAuthority);
  w.u32(rotation.validFrom);
  return w.finish();
}

function decodeAuthorityRotation(bytes) {
  const r = new Reader(bytes);
  if (r.u8() !== TYPE_AUTHORITY_ROTATION) throw new Error('not an authority rotation');
  if (r.u16() !== PROTOCOL_VERSION) throw new Error('unknown protocol version');
  const rotation = {
    networkId: r.bytes32(),
    serial: r.u64(),
    newAuthority: r.bytes32(),
    validFrom: r.u32(),
  };
  if (r.at !== bytes.length) throw new Error('trailing bytes after the rotation');
  return rotation;
}

const authorityRotationId = (rotation) =>
  taggedHash(TAG.authorityRotation, encodeAuthorityRotation(rotation));

/**
 * ONE PUBLICATION, CHECKED. Answered rather than thrown, like every other
 * decision in this package: a malformed object from a stranger is a refusal.
 *
 * `signature` is not in the encoded body and cannot be - the id is what the
 * key signs, so an object whose bytes included its own signature could not be
 * signed at all. It rides beside it, as the advertisement's does.
 */
function signedBy(object, { id, key, signature, verify, what }) {
  if (!isDonationBytes32(key)) return { ok: false, why: `no ${what} key to check that against` };
  if (!(signature instanceof Uint8Array) || signature.length !== DONATION_SIGNATURE_BYTES)
    return { ok: false, why: `a ${what} signature is ${DONATION_SIGNATURE_BYTES} bytes` };
  if (typeof verify !== 'function')
    return { ok: false, why: 'no verifier: this package carries no curve' };

  let digest;
  try { digest = id(object); }
  catch (e) { return { ok: false, why: e.message }; }

  let ok = false;
  try { ok = !!verify(signature, digest, key); }
  catch { ok = false; }
  return ok
    ? { ok: true, id: digest, why: `signed by ${toHex(key).slice(0, 16)}` }
    : { ok: false, id: digest, why: `that ${what} signature is not ${toHex(key).slice(0, 16)}'s` };
}

const donationSetSignedBy = (set, { authority, verify }) =>
  signedBy(set, {
    id: donationSetBodyId, key: authority, signature: set && set.signature,
    verify, what: 'authority',
  });

const rotationSignedBy = (rotation, { recovery, verify }) =>
  signedBy(rotation, {
    id: authorityRotationId, key: recovery, signature: rotation && rotation.signature,
    verify, what: 'recovery',
  });

/**
 * THE HIGHEST VALIDLY SIGNED ONE WINS, and equivocation at a serial loses that
 * serial rather than picking a winner.
 *
 * 27A.4 orders publications by serial and says nothing about two of them
 * carrying the same one, because an honest authority does not do that. A
 * dishonest or duplicated key does, and then "the highest validly signed one"
 * names two different objects - so a rule is needed, and the choice is between
 * two deterministic answers.
 *
 * PICKING ONE BY ITS BYTES was rejected. It would pay whichever list happened
 * to hash lower, which is a coin flip decided by a party who has already shown
 * they will sign twice - and it would do it silently.
 *
 * SO A CONTESTED SERIAL IS UNUSABLE and the search falls back to the highest
 * serial below it that is not. Every node reaches the same answer from the
 * same objects, nobody is paid on a signature the authority contradicted, and
 * the network lands exactly where 27A.4's "both lost" row already puts it:
 * "the set freezes at its last published serial and every donation keeps going
 * where it was already going". A frozen set is a bounded failure. Paying a
 * thief is not.
 */
function bestBySerial(accepted, idOf) {
  const bySerial = new Map();
  for (const item of accepted) {
    const list = bySerial.get(item.serial);
    if (list) list.push(item);
    else bySerial.set(item.serial, [item]);
  }

  const serials = [...bySerial.keys()].sort((a, b) => (a < b ? 1 : a > b ? -1 : 0));
  const contested = [];
  for (const serial of serials) {
    const list = bySerial.get(serial);
    const ids = new Set(list.map((item) => toHex(idOf(item))));
    if (ids.size === 1) return { best: list[0], contested };
    contested.push(serial);
  }
  return { best: null, contested };
}

/**
 * WHO THE AUTHORITY IS AT A HEIGHT.
 *
 * 27A.4: "Published like the donation set. From `valid_from`, sets signed by
 * the old authority are rejected and only the new one is accepted, WHATEVER
 * SERIAL THE OLD KEY PUBLISHES." So the answer is a function of the height a
 * node is asking about and not of when anything arrived, and it is the genesis
 * key until a rotation is in force.
 *
 * ROTATIONS ARE CHECKED AGAINST THE GENESIS RECOVERY KEY AND ONLY IT. The
 * section's table is exhaustive - "recovery CAN name a new authority" - and
 * that is the whole list. A rotation that could name a new recovery key would
 * let one theft of the cold key close the door behind itself, which is the
 * fault the two-key split exists to prevent.
 */
function authorityAt({
  networkId, authority, recovery, rotations = [], height, verify,
}) {
  const refused = [];
  if (!isDonationBytes32(authority)) throw new Error('a network has a 32-byte donation authority');
  if (!Number.isInteger(height) || height < 0) throw new Error('a height is a block height');

  const accepted = [];
  for (const [at, rotation] of rotations.entries()) {
    if (!rotation || !isDonationBytes32(rotation.networkId) || !sameDonationBytes32(rotation.networkId, networkId)) {
      refused.push(`rotation ${at} is for another network`);
      continue;
    }
    if (!Number.isInteger(rotation.validFrom) || rotation.validFrom > height) {
      refused.push(`rotation ${at} is not in force at ${height}`);
      continue;
    }
    const signed = rotationSignedBy(rotation, { recovery, verify });
    if (!signed.ok) {
      refused.push(`rotation ${at}: ${signed.why}`);
      continue;
    }
    accepted.push(rotation);
  }

  const { best, contested } = bestBySerial(accepted, authorityRotationId);
  for (const serial of contested)
    refused.push(`two different rotations are signed at serial ${serial}, so that serial is unusable`);

  return best
    ? {
      authority: best.newAuthority,
      serial: best.serial,
      rotated: true,
      validFrom: best.validFrom,
      refused,
      why: `the recovery key named ${toHex(best.newAuthority).slice(0, 16)} from height ${best.validFrom}`,
    }
    : {
      authority, serial: null, rotated: false, validFrom: 0, refused,
      why: 'no rotation is in force, so the genesis authority still signs',
    };
}

/**
 * AND THE ANSWER THE REST OF THE PROTOCOL WANTS: which recipients, at this
 * height, on this network.
 *
 * The refusals are returned rather than swallowed. A node that pays nobody
 * because every set it holds is for another network must be able to say so -
 * "no set is in force" and "I threw them all away" are different facts, and
 * only one of them is a bug.
 *
 * A ROTATION BLANKS THE LIST, and that is 27A.4's own reading rather than a
 * strictness of taste: "from `valid_from`, sets signed by the old authority
 * are rejected". Every set the old key signed dies with it, including the
 * honest ones it signed before the theft - so between a rotation and the new
 * authority's first publication this network has no set in force and pays
 * nobody.
 *
 * The alternative was measured and is worse: grandfathering what the old key
 * published before the rotation keeps the THIEF'S set alive too, because the
 * thief published before the rotation as well. A revocation that leaves the
 * stolen list in force is not a revocation.
 *
 * NO SET IN FORCE IS NOT AN ERROR. A network can run without one and 22A's
 * player donating nothing is unaffected: `splitDonation` already answers a
 * zero donation without judging a set at all. What must never happen is a set
 * being IN FORCE without a signature to point at, and that is what this
 * returns `ok` for.
 */
function donationSetInForce({
  networkId, authority, recovery, sets = [], rotations = [], height, verify,
}) {
  if (!isDonationBytes32(networkId)) throw new Error('a network is a 32-byte id');
  const inForce = authorityAt({ networkId, authority, recovery, rotations, height, verify });
  const refused = [...inForce.refused];

  const accepted = [];
  for (const [at, set] of sets.entries()) {
    if (!set || !isDonationBytes32(set.networkId) || !sameDonationBytes32(set.networkId, networkId)) {
      refused.push(`set ${at} is for another network`);
      continue;
    }
    if (!Number.isInteger(set.validFrom) || set.validFrom > height) {
      refused.push(`set ${at} is not in force at ${height}`);
      continue;
    }
    // The list itself, before the key: a set that does not stand is not a set,
    // and saying so names the actual fault rather than reporting a signature
    // over bytes that could not be produced.
    const stands = donationSetStands(set.recipients);
    if (!stands.ok) {
      refused.push(`set ${at}: ${stands.why}`);
      continue;
    }
    const signed = donationSetSignedBy(set, { authority: inForce.authority, verify });
    if (!signed.ok) {
      refused.push(`set ${at}: ${signed.why}`);
      continue;
    }
    accepted.push(set);
  }

  const { best, contested } = bestBySerial(accepted, donationSetBodyId);
  for (const serial of contested)
    refused.push(`two different sets are signed at serial ${serial}, so that serial is unusable`);

  if (!best)
    return {
      ok: false, recipients: null, serial: null, validFrom: null,
      authority: inForce.authority, rotated: inForce.rotated, refused,
      why: sets.length
        ? `none of the ${sets.length} sets offered is in force at height ${height}`
        : 'this network has published no donation set',
    };

  return {
    ok: true,
    recipients: best.recipients,
    serial: best.serial,
    validFrom: best.validFrom,
    setId: donationSetBodyId(best),
    authority: inForce.authority,
    rotated: inForce.rotated,
    refused,
    why: `serial ${best.serial}, in force from height ${best.validFrom}, `
      + `${best.recipients.length} recipients`,
  };
}

// ---- blwp-client/src/donation-pay.js
/**
 * THE PLAYER'S DONATION, PAID (M3.2 item 6e; §22A, §24A.2, §27A.4; ruled
 * 2026-09-13).
 *
 * "Donations are paid: LNURL per recipient, by share, from the player's wallet
 * directly at entry - never through the federation" (§24A.2). Two halves:
 *
 * `fetchDonationSet` - the set the round names, as EVERY signer node of the round
 * serves it (a signer node that serves another, or none, is a refusal), signed by the
 * network's donation authority at the round's height with rotations included,
 * checked with Ed25519 (the authority's scheme). The page shows every
 * recipient from it before the wallet approves (§22A).
 *
 * `Client.payDonation(entry, set)` (client.js, beside `payStake`) - AN ENTRY AND
 * A SET, NEVER AN INVOICE. The amounts
 * come from `splitDonation` over the entry's own donation; each recipient's
 * endpoint is asked for its pay request and then for an invoice of exactly its
 * share, and only an invoice that is that share under the endpoint's own
 * metadata hash (LUD-06) reaches the wallet, through the same `payInvoice` the
 * stake uses. A failed share is reported and never redirected to the others
 * (§22A); the entry stands either way. A 0% entry pays nothing and asks nobody.
 *
 * MEASURED BEFORE: no LNURL, bech32 or BOLT11 code existed; `splitDonation`
 * had no caller; `pay_invoice` had one call site, the stake; a 2% donor's 2000
 * msat was taken by nobody.
 */







/**
 * WHAT THIS TAB HAS ALREADY ASKED ITS WALLET TO DONATE, per round and player
 * key, share by share (M3.2 6e). Measured before: the page's once-only flag
 * and its spend log were page memory while the lock, the chosen donation and
 * the wallet survived a reload in sessionStorage, so a reload over a kept lock
 * paid every share again.
 *
 * KEYED BY ROUND AND PLAYER, NOT BY ENTRY ID: a reload keeps the player's key
 * and draws a NEW entry (client.js, `join`), so an entry-id key would miss the
 * very reload it is for. One donation per player per round.
 *
 * A share's note is `asked` (written BEFORE the wallet is asked, so a tab that
 * dies mid-payment never asks twice), then `paid` or `unpaid`. Any note at all
 * means the share is not asked again.
 */
const DONATION_PAID_PREFIX = 'blwp-donation-paid:';
const donationPaidKey = ({ roundId, playerPubkey }) => `${DONATION_PAID_PREFIX}${toHex(roundId)}:${toHex(playerPubkey)}`;

function donationPaidRecord(storage, whose) {
  let raw;
  try { raw = storage && storage.getItem(donationPaidKey(whose)); } catch { return null; }
  if (!raw) return null;
  try { const o = JSON.parse(raw); return o && o.shares && typeof o.shares === 'object' ? o : null; } catch { return null; }
}

/** Answers false when the tab could not keep the note - and then the wallet must not be asked. */
function noteDonationShare(storage, whose, lnurl, { amountMsat, ...note }) {
  try {
    const was = donationPaidRecord(storage, whose) || { shares: {} };
    was.shares[lnurl] = { ...note, amountMsat: String(amountMsat) };
    storage.setItem(donationPaidKey(whose), JSON.stringify(was));
    return true;
  } catch { return false; }
}

/**
 * EACH SHARE OF THE DONATION, AS THE PLAYER SEES IT (M3.2 6e): paid, unpaid
 * with its why, or outcome unknown - off `payDonation`'s answer, which on a
 * reload is read back from the tab's notes, so the screen says what the notes
 * say. In the set's order; a share that floored to 0 msat was owed nothing and
 * has no row. Measured before: the page kept `{ state, paidMsat, unpaid }` on
 * `window` and painted none of it - 0 of 2 shares on screen in every case.
 */
function donationPaidState(set, said) {
  if (!said) return null;
  const recipients = set && Array.isArray(set.recipients) ? set.recipients : [];
  const noted = new Map();
  for (const p of said.paid || []) noted.set(p.lnurl, { state: 'paid', amountMsat: p.amountMsat });
  for (const f of said.failed || []) noted.set(f.lnurl, { state: 'unpaid', amountMsat: f.amountMsat, why: f.why });
  for (const u of said.unknown || []) noted.set(u.lnurl, { state: 'unknown', amountMsat: u.amountMsat, why: u.why });
  const shares = [];
  for (const r of recipients) {
    const s = noted.get(r.lnurl);
    if (!s) continue;
    let url;
    try { url = urlOfLnurl(r.lnurl); } catch { url = r.lnurl; }
    shares.push({ url, lnurl: r.lnurl, shareBps: r.shareBps, ...s });
  }
  const of = (st) => shares.filter((s) => s.state === st);
  const sum = (list) => list.reduce((t, s) => t + s.amountMsat, 0n);
  const paid = of('paid').length;
  const state = !shares.length ? (said.ok ? 'none' : 'error')
    : paid === shares.length ? 'paid'
      : paid ? 'part'
        : of('unpaid').length ? 'unpaid' : 'unknown';
  return { state, shares, paidMsat: sum(of('paid')), unpaidMsat: sum(of('unpaid')), unknownMsat: sum(of('unknown')), why: said.why };
}

const msatOrSat = (msat) => (msat % 1000n === 0n ? `${msat / 1000n} sat` : `${msat} msat`);
const SHARE_WORD = { paid: 'paid', unpaid: 'UNPAID', unknown: 'outcome unknown' };

/**
 * THE DONATION AS ONE LINE, so the page renders and does not compute. What is
 * unpaid stays in the player's wallet (ruled 2026-09-13: never sent to the
 * operator or the other recipient); an unknown share is said to be unknown.
 */
function donationPaidLine(p) {
  if (!p || p.state === 'none') return '';
  if (p.state === 'paying') return 'Donation: paying each recipient its share…';
  if (!Array.isArray(p.shares) || !p.shares.length) return `Donation not paid: ${p.why || 'no answer'}`;
  const each = p.shares.map((s) => `${msatOrSat(s.amountMsat)} ${SHARE_WORD[s.state]} to ${s.url}`
    + (s.state === 'paid' ? '' : ` (${s.why})`));
  const kept = p.unpaidMsat > 0n ? ` · ${msatOrSat(p.unpaidMsat)} unpaid stays in your wallet, sent nowhere else` : '';
  return `Donation: ${each.join(' · ')}${kept}`;
}

const SHARE_OF_NOTE = { paid: 'paid', unpaid: 'unpaid', asked: 'unknown' };
const UNKNOWN_WHY = 'this tab asked its wallet for it before a reload and never heard the answer, so it is not asked again';

/**
 * THE DONATION AS THE TAB'S NOTES HAVE IT - NO SIGNER NODE, NO SET (M3.2 6e). Measured
 * before, on the daily page: a reload whose round link failed to fetch showed
 * the loading screen's refusal and nothing else - no wallet panel, no line -
 * while the notes held "paid 1334, unpaid 666". The line was painted only after
 * `payDonation`, which needs a signer node. The notes are what the wallet was asked and
 * what it answered, so they are enough to say it. Null when the tab has none.
 */
function donationNotedState(storage, whose) {
  const noted = donationPaidRecord(storage, whose);
  if (!noted) return null;
  const said = { ok: true, paid: [], failed: [], unknown: [] };
  const recipients = [];
  for (const [lnurl, n] of Object.entries(noted.shares)) {
    let amountMsat;
    try { amountMsat = BigInt(n.amountMsat); } catch { continue; }
    const as = SHARE_OF_NOTE[n.state];
    if (!as) continue;
    recipients.push({ lnurl });
    if (as === 'paid') said.paid.push({ lnurl, amountMsat });
    else if (as === 'unpaid') { said.failed.push({ lnurl, amountMsat, why: n.why || 'unpaid' }); said.ok = false; }
    else { said.unknown.push({ lnurl, amountMsat, why: UNKNOWN_WHY }); said.ok = false; }
  }
  if (!recipients.length) return null;
  return { ...donationPaidState({ recipients }, said), from: 'notes' };
}

/**
 * AND FOR THE ROUND A LINK NAMES, when the round itself cannot be reached: the
 * round id off the link, this tab's key for it from the tab's own seed (read,
 * never minted - a tab with no seed has donated nothing), and that key's notes.
 * Nothing is asked of a node or a wallet.
 */
function notedDonationForLink(search, { storage, curve } = {}) {
  let hex = null;
  try { hex = new URLSearchParams(String(search || '')).get('round'); } catch { return null; }
  if (!hex || !/^[0-9a-f]{64}$/i.test(hex) || !storage) return null;
  let seedHex = null;
  try { seedHex = storage.getItem(TAB_SEED_KEY); } catch { return null; }
  if (!seedHex || !/^[0-9a-f]{64}$/i.test(seedHex)) return null;
  let player;
  try { player = playerFor({ id: fromHex(hex.toLowerCase()) }, { seed: fromHex(seedHex.toLowerCase()), curve }); } catch { return null; }
  return donationNotedState(storage, { roundId: player.roundId, playerPubkey: player.pubkey });
}

/** Every recipient of a set, with its share and where it is paid - what the page shows before the wallet approves. */
function donationRecipientsLine(set) {
  if (!set || !Array.isArray(set.recipients)) return 'no donation set';
  return 'Recipients: ' + set.recipients.map((r) => {
    let where;
    try { where = urlOfLnurl(r.lnurl); } catch { where = r.lnurl; }
    return `${(r.shareBps / 100).toFixed(2)}% to ${where}`;
  }).join(', ');
}

/**
 * THE DONATION SET THIS ROUND NAMES, AS ALL OF ITS SIGNER NODES SERVE IT, CHECKED.
 * `verifyEd25519(sig, msg, pub)` may be async (the browser's crypto.subtle);
 * every answer is awaited here before `authorityAt` sees a settled boolean.
 * `keys` overrides the network's donation keys (tests only).
 */
async function fetchDonationSet({ round, nodes, fetcher = (u) => fetch(u), verifyEd25519, keys } = {}) {
  if (!round || !(round.donationSetId instanceof Uint8Array)) return { ok: false, why: 'there is no round to fetch a donation set for' };
  if (typeof verifyEd25519 !== 'function') return { ok: false, why: 'checking a donation set needs an Ed25519 verifier, and none was injected' };
  const networkKeys = keys || donationKeysForNetworkId(round.networkId);
  if (!networkKeys) return { ok: false, why: 'this round\'s network has no donation authority this page knows' };
  if (!Array.isArray(nodes) || !nodes.length) return { ok: false, why: 'the round names no signer nodes to ask for its donation set' };
  const rid = toHex(roundId(round));
  const answers = await Promise.all(nodes.map(async (node) => {
    const base = String(node).replace(/\/+$/, '');
    try {
      const r = await fetcher(`${base}/donation-set?round=${rid}`);
      if (r.status !== 200) return { node: base, why: `${r.status} ${(await r.text()).trim().slice(0, 100)}` };
      const bytes = new Uint8Array(await r.arrayBuffer());
      let rotations = [];
      try {
        const rr = await fetcher(`${base}/donation-rotations?round=${rid}`);
        if (rr.status === 200) rotations = (await rr.json()).rotations || [];
      } catch { rotations = []; }
      return { node: base, bytes, rotations };
    } catch (e) { return { node: base, why: e.message }; }
  }));
  const missing = answers.filter((a) => !a.bytes);
  if (missing.length)
    return { ok: false, why: `not every signer node of this round serves its donation set: ${missing.map((a) => `${a.node}: ${a.why}`).join('; ')}` };
  const served = toHex(answers[0].bytes);
  if (answers.some((a) => toHex(a.bytes) !== served)) return { ok: false, why: 'the signer nodes of this round serve different donation sets' };
  const bytes = answers[0].bytes;
  if (bytes.length <= DONATION_SIGNATURE_BYTES) return { ok: false, why: 'that is no signed donation set' };
  let set;
  try { set = { ...decodeDonationSetBody(bytes.slice(0, -DONATION_SIGNATURE_BYTES)), signature: bytes.slice(-DONATION_SIGNATURE_BYTES) }; }
  catch (e) { return { ok: false, why: `that is no donation set: ${e.message}` }; }
  if (toHex(set.networkId) !== toHex(round.networkId)) return { ok: false, why: 'that donation set is for another network' };
  const named = donationSetMatchesRound(round, set.recipients);
  if (!named.ok) return { ok: false, why: named.why };
  if (!(set.validFrom <= round.censusHeight)) return { ok: false, why: 'that donation set is not in force at the round\'s height' };

  // EVERY SIGNER NODE'S ROTATIONS, EACH CHECKED HERE against the network's recovery
  // key: a signer node that hides a rotation cannot hide it from the other signer nodes.
  const offered = new Map();
  for (const a of answers) for (const r of a.rotations) {
    try { offered.set(`${r.body}:${r.signature}`, { ...decodeAuthorityRotation(fromHex(String(r.body))), signature: fromHex(String(r.signature)) }); }
    catch { /* not a rotation: nothing to apply */ }
  }
  const rotations = [...offered.values()];
  const signedRotations = new Set();
  for (const rot of rotations)
    if (await verifyEd25519(rot.signature, authorityRotationId(rot), networkKeys.recovery) === true) signedRotations.add(toHex(rot.signature));
  const inForce = authorityAt({ networkId: round.networkId, authority: networkKeys.authority, recovery: networkKeys.recovery,
    rotations, height: round.censusHeight, verify: (sig) => signedRotations.has(toHex(sig)) });
  if (await verifyEd25519(set.signature, donationSetBodyId(set), inForce.authority) !== true)
    return { ok: false, why: 'that donation set is not signed by the network\'s donation authority at the round\'s height' };
  return { ok: true, set, signerNodes: answers.length, rotated: inForce.rotated,
    why: `${answers.length} signer node(s) serve the set this round names, signed by its donation authority` };
}

// ---- blwp-client/src/client.js
// THE PLAYER'S HALF OF THE PROTOCOL.
//
// The node is a store. It takes rounds, entries, batches and checkpoints and
// refuses the ones that break a rule, and it does not recompute any of them
// WHILE THE RUN IS ON: a daemon stepping the core alongside the player would
// be a second simulator, two engines each with its own idea of the present,
// and nothing to say which one is the game.
//
// So the state hash of a LIVE run has to come from HERE, off the same core the
// player is watching. That is the whole reason this file exists.
//
// After the run is over the node does replay it, in `blwp-node/src/replay.js`
// and nowhere else - section 13 makes a result final when five of seven nodes
// agree, and a node that could not replay would be agreeing to whatever it was
// told. That is one simulator run twice over the same inputs, which is the
// only claim determinism ever made; it is not a second engine.
//
// WHAT IT IS NOT. It is not a simulator and it holds no rule: it never decides
// a score, a crater, a hit or a winner. It reads a hash the core produced,
// wraps it in the protocol's own encoding, signs it, and puts it on a socket.
// Every byte that crosses the wire is written by `@blwp/protocol` - there is
// no second encoder here, and there must never be one, because a wire format
// with two implementations is a wire format with two answers.
//
// WHAT IS INJECTED, AND WHY. The core and the signing function are handed in
// rather than imported. In a browser the core is the bundle already running in
// the page - the very object the game is drawing from - and the session key
// belongs to the run, not to this module; in a test the core is that same
// bundle loaded through `require`. Importing either here would give this file
// an opinion about which core the player is running, which is the one thing it
// must not have.






// THE RULE A PLAYER CHECKS AN INVOICE WITH, IMPORTED AND NOT REWRITTEN.
//
// `server.js` says at its own /invoice door that this rule "lives on their
// side too", and until M3.2 item 5 it did not: zero callers here. A second
// formula in the client would be a second opinion about what the player owes,
// which is the one number they are about to part with money over.












// THE PLAYER'S DONATION (M3.2 6e): the split, the failure rule, the LNURL checks.





/**
 * A FEDERATION ROUND'S STAKE: THE INVOICE COMES FIRST (Daniel 2026-09-11).
 *
 * Here, and not in join.js, because this is the file that asks a node what a
 * player pays (session-pay.test.js: one file quotes a player). V1's pool is a
 * federation, and an LNv2 invoice's secret belongs to its receiver - held by
 * the guardians threshold-wise, which is the job the player's dealt shares do
 * on a round without one. So no P is chosen and no handout is dealt: a node
 * asks the federation for the round's invoice (`GET /federation-invoice`),
 * and the entry commits to that invoice's hash, with `NO_SHARES` as its
 * shares reference. The amount must be the entry's net stake - the stake less
 * the 2% fee and the player's donation, `netStakeMsat` as at every other door -
 * or the committee's hold check refuses the entry. Measured before (M3.2 6e):
 * this asked for the stake less the fee only, so a 2% donor's entry was joined
 * on a 980000 msat invoice it could never be quoted (it holds 960000).
 */
async function federationStakeFor(round, { nodes, fetcher = fetch, donationMsat = 0n } = {}) {
  const stakeMsat = BigInt((round && round.stakeMsat) || 0n);
  if (!(stakeMsat > 0n)) throw new Error('a round that asks no stake has nothing to invoice');
  const want = netStakeMsat({ stakeMsat, feeMsat: entryFeeMsat(stakeMsat), donationMsat });
  const id = toHex(round.id);
  const refused = [];
  for (const node of nodes || []) {
    const base = String(node).replace(/\/+$/, '');
    try {
      const r = await readWithOneRetry(fetcher, `${base}/federation-invoice?round=${id}${donationMsat ? `&donation=${donationMsat}` : ''}`);
      const body = await r.text();
      if (!r.ok) { refused.push(`${base}: ${r.status} ${body.trim()}`); continue; }
      const said = JSON.parse(body);
      const hash = fromHex(String(said.paymentHash || ''));
      if (hash.length !== 32) { refused.push(`${base}: a payment hash is 32 bytes`); continue; }
      if (BigInt(said.amountMsat) !== want) {
        refused.push(`${base}: an invoice for ${said.amountMsat} msat, and this round's net stake is ${want}`);
        continue;
      }
      return { federation: true, stakeCommitment: hash, vssSharesRef: NO_SHARES,
        request: said.request, amountMsat: want, node: base };
    } catch (e) { refused.push(`${base}: ${e.message}`); }
  }
  throw new Error(`no node made this round's federation invoice: ${refused.join('; ') || 'no node to ask'}`);
}

/**
 * Five, out of the seven a committee has.
 *
 * Section 13C: the canonical transcript is "the longest checkpoint chain that
 * carries receipts from at least 5 committee nodes". It is a threshold and not
 * a preference - the point of it is that no smaller set of nodes can make a
 * mark count, so an operator cannot spend a short committee as a win.
 */
const RECEIPTS_FOR_LIVE = 5;

/** 2-of-2 on this build's test nets; 5-of-7 on a seven-signer node contract. */
function receiptsForLive(contract) {
  const slots = contract?.gameVerifySlots ?? contract?.nodes?.length;
  if (slots === 2) return 2;
  return RECEIPTS_FOR_LIVE;
}

/**
 * A checkpoint over the state a core is holding, signed and ready for the wire.
 *
 * `core.hash(st)` is the only thing read out of the simulation, and it is read
 * rather than computed: this file could not produce that number if it wanted
 * to, which is the property that keeps the client a television.
 *
 * The tagged id is what gets signed, never the raw encoding - every other
 * object in this protocol is committed to through its tagged hash, and keeping
 * that means a signature here can never be replayed as a signature over some
 * other object that happens to encode to the same bytes.
 *
 * `previousHash` names the chain head, `NO_PREVIOUS` for the first mark of a
 * round; `inputChainHash` names the batches this state claims to come from,
 * `GENESIS` for a mark taken before any batch was sent, which the node allows
 * by name.
 */
async function markState(core, st, {
  roundId, entryId, tick,
  previousHash = NO_PREVIOUS,
  inputChainHash = GENESIS,
}, sign) {
  // THE ONE CONVERSION, and it is the client's to make. The core answers in
  // HEX - `hash(st)` returns 64 characters, and the WebGL bridge writes those
  // same characters as ASCII into a caller's buffer - while the protocol's
  // field is thirty-two raw bytes. `fromHex` is the protocol's own, so the two
  // ends of this line agree by construction rather than by two spellings of
  // the same loop.
  return markHashed(core.hash(st), { roundId, entryId, tick, previousHash, inputChainHash }, sign);
}

/**
 * The same mark, from a hash that was already taken.
 *
 * Separated because a checkpoint says where the world was AT A TICK, and the
 * hash therefore has to be read at that tick - not when a queue gets round to
 * it. Whoever takes it early passes it here. It used to be smuggled through a
 * fake core object whose `hash` returned the string it had been handed, which
 * worked and read like a trick; this is the same thing said plainly.
 */
async function markHashed(hex, {
  roundId, entryId, tick,
  previousHash = NO_PREVIOUS,
  inputChainHash = GENESIS,
}, sign) {
  // Checked rather than trusted: a core that answered anything but 64 hex
  // characters would otherwise be silently truncated or padded into a mark
  // that signs cleanly and commits to the wrong state.
  if (typeof hex !== 'string' || !/^[0-9a-f]{64}$/.test(hex))
    throw new Error(`the core did not answer a state hash: ${String(hex).slice(0, 80)}`);
  const stateHash = fromHex(hex);
  const c = { roundId, entryId, tick, stateHash, inputChainHash, previousHash };
  const id = checkpointId(c);
  // AWAITED, so the browser's own Ed25519 can be used.
  //
  // `crypto.subtle` is async and a vendored JS curve is not - and vendoring
  // one would put a signing implementation in the trust path of the thing
  // that pins money, which is the same objection `tools/bundle.js` records
  // about bundlers. Awaiting a value that is not a promise costs nothing, so
  // a synchronous signer still works exactly as it did.
  return { checkpoint: c, id, bytes: joinSigned(encodeCheckpoint(c), await sign(id)) };
}

/**
 * A player against one node: the two HTTP doors, the socket, and the mark.
 *
 * `fetch` and `WebSocket` are the platform's, in a browser and in Node alike,
 * so this carries no transport dependency of its own.
 */
function agrees(mine, theirs, what) {
  if (theirs.length !== mine.length || mine.some((b, i) => b !== theirs[i]))
    throw new Error(
      `the node calls this ${what} ${toHex(theirs)}, and its contract hashes to ${toHex(mine)}`);
  return mine;
}

/**
 * HOW LONG A CHECKPOINT WAITS FOR EVERY NODE TO HOLD ITS INPUTS, in ms.
 *
 * Longer than the reconnect backoff's 8 s ceiling, so a node that restarts
 * comes back inside it; short enough that a node which never comes back costs
 * a handful of the one-a-second marks, not the run's.
 */
const MARK_INPUT_WAIT_MS = 10000;

/**
 * HOW MANY BATCHES A BEHIND PEER IS CAUGHT UP WITH AT ONCE.
 *
 * A mark at tick T waits until every committee node holds the inputs before T, so a peer that starts late
 * decides when the player's FIRST mark can go out - and §13B judges that mark against a 900-tick window.
 * Measured on the Daily, one paid entry per line, both seats through the same quick tunnels:
 *
 *   peer round trip                  65 ms (median of 2084)
 *   one batch                        6 ticks (BatchEvery, 10 Hz of a 60 Hz run)
 *   one batch per round trip         92 ticks/s against a player making 60 - a surplus of 32 ticks/s
 *   a seat 2280 ticks behind         71 s to close it, and the run's first mark went out at tick 5940
 *                                    of a window ending at 900: FORFEIT, on a player who paid in 10 s
 *
 * The backlog was never the transport's fault - it was spent waiting for one answer before asking the next
 * question. The frames on a socket are ORDERED, `sendPeer` matches answers to askers in the order they were
 * sent, and the node's own handler queues each frame behind the one before it ("every frame on a socket
 * waits for the one before it", server.js), so a window of them is taken in exactly the order one at a time
 * would have been. Nothing here relaxes what a node checks; it only stops making the client wait a round
 * trip per batch. 32 of them turn that 71 s into about 2 s, and a steady run - which has one new batch to
 * send - is byte for byte what it was.
 */
const FEED_WINDOW = 32;

/**
 * THE WORD FOR NO CONNECTION, distinct from every word a node says.
 *
 * A node's own refusal arrives as `error ...`. A peer that could not be reached
 * - down, restarting, unroutable - never said anything, and counting it with
 * the refusals put "inputs refused 20" on the line for a daemon that was off.
 * A refusal and a disconnect decide different things (a node that says no is
 * a node that holds something else; one that is gone holds nothing yet), so
 * they are kept apart from the first place they could be confused.
 */
const CLOSED = 'closed: ';

/** How long `finish` waits for the held ticks to go out before it ends the run anyway. */
const FINISH_WAIT_MS = 300;
// HOW OFTEN THE FINAL MARK IS OFFERED AGAIN to a signer node that has not receipted it - a cadence, not a timeout: the
// window is the ruled one (from the ask until the settlement is combined, or the page leaves), and nothing ends it early.
const FINAL_RELINK_EVERY_MS = 1000;
/** The core's own words for a run that is over (core rules/gate.js RUN_DELIVERED 1, RUN_WRECKED 2, RUN_MISSED 3), as they read off the state. */
const RUN_ENDING_WORDS = Object.freeze({ 1: 'DELIVERED', 2: 'WRECKED', 3: 'MISSED' });

class Client {
  /**
   * A client that reaches a node because Bitcoin says where it is, AND because
   * this round's own contract says that node is one of its committee.
   *
   * The one door the game uses, and everything it refuses it refuses HERE -
   * before the round is opened, before an entry is joined, before a single
   * batch of section 11 input is published. That ordering is the whole point.
   * A proven advertisement for a node with no standing in this round used to
   * be caught at the first receipt, which is one round trip too late: by then
   * the entry contract and the opening batches are on a stranger's disk, and
   * section 11 makes publishing the client's duty, not something it can take
   * back.
   *
   * Asynchronous because the last check is a signature and the browser's
   * Ed25519 is asynchronous. `verify` is injected for the same reason it is
   * injected everywhere else here: the curve belongs to whoever runs the
   * client. The constructor below still takes a bare `base`, because tests and
   * the node's own fixtures talk to a process on localhost that has no bond
   * and never will - and a test that wants the real door calls this one.
   */
  static async at(discovery, { core, sign, verify, contract, roundIdGiven, stakeLock }) {
    if (!contract || !contract.nodes)
      throw new Error('no round contract, so there is no committee to check against');

    // WHICH ROUND, AND WHO SAYS SO. This is checked before anything else,
    // because everything else is checked AGAINST it.
    //
    // Section 25.1 step 1 is "a link, QR, copied round_id - carries nothing",
    // and the "carries nothing" is the point: the id is all the player has,
    // and it is enough, because every id in this protocol is the tagged hash
    // OF the object. So the contract the page hands over must hash to the id
    // the player was given, or it is a different round.
    //
    // Without this the committee check below is circular. The page writes the
    // contract, so the page writes `nodes`, so the page chooses the committee
    // its own advertisement then satisfies - with a real bond, a real merkle
    // proof and a real signature, every one of which would pass. Binding the
    // id costs one hash and makes the whole door mean something: change a
    // single node in that list and the contract hashes to something else.
    //
    // Required, not optional. A player who arrived with no id has nothing to
    // check and there is no safe way to guess one.
    if (!(roundIdGiven instanceof Uint8Array) || roundIdGiven.length !== 32)
      throw new Error('no round id from the player, so there is nothing to '
        + 'check the page\'s contract against');
    const named = roundId(contract);
    if (toHex(named) !== toHex(roundIdGiven))
      throw new Error(`the page offered round ${toHex(named)}, which is not `
        + `the round ${toHex(roundIdGiven)} you were given`);

    // THE CHAIN AND THE BOND ARE ASKED FOR, NEVER ACCEPTED. A ready-made chain
    // or a ready-made proof is refused here rather than verified, because
    // verifying a pair somebody else chose proves only that they agree with
    // each other. This is the door; the library below it will still check
    // anything it is handed, and that is exactly why the door must not hand it
    // what the page said.
    for (const handed of ['chain', 'chains', 'transaction', 'branch', 'position']) {
      if (discovery[handed] !== undefined)
        throw new Error(`the ${handed} must come from a provider, not from whoever `
          + 'opened the page: two things that agree with each other are not Bitcoin');
    }

    const seen = await discover({ ...discovery, committee: contract.nodes });
    // WHICH PROVIDER, AND WHY (M3.3-27): `discover` hands back each provider's
    // own refusal, and the door used to drop it - the rehearsal's flake read
    // "only 1 of 2 providers gave a chain" and nothing more.
    if (!seen.ok)
      throw Object.assign(new Error(`no proven endpoint: ${seen.why}`
        + (seen.refused ? ` (${seen.refused})` : '')), { refused: seen.refused });

    // 5A.1 ends the body with "signature - by node_pubkey over all of the
    // above". The tagged id is what is signed, as everywhere else in this
    // protocol, so a signature here can never be replayed as a signature over
    // some other object that happens to encode to the same bytes. Weaker than
    // the bond output's commitment - which already binds this body to money on
    // chain - but it is what says the key the advertisement NAMES is the key
    // that wrote it, and it is listed.
    if (!await verify(seen.signature, seen.advertId, seen.nodePubkey))
      throw new Error(`the advertisement for ${toHex(seen.nodePubkey)} `
        + 'is not signed by the node it names');

    const client = new Client({
      base: seen.endpoint.replace(/^ws/, 'http'), core, sign, verify,
    });
    // THE CHAIN THIS CALL PROVED, carried on the client so the page can open its NEXT round from it rather than
    // proving the same headers again at a boundary where a starved tab misses the ten seconds (Daniel 2026-09-18).
    client.provedChain = seen.chain || null;
    client.reusedChain = !!seen.reusedChain;
    // AND EVERY OTHER COMMITTEE NODE, for the checkpoints. Section 10: "a
    // checkpoint is accepted when enough nodes receive it"; section 11: "the
    // client periodically sends batches and checkpoints". The proven endpoint is
    // one node, and the rest arrive as `discovery.nodes` - handed in by the
    // page's own wrapper of this call, from the same list the bridge already
    // asks for the round's randomness; nothing in here reads the page. They
    // need no proof of their own because they are DELIVERY addresses, not
    // trust: an entry and a checkpoint are public, and a receipt only counts
    // once it verifies under a key the round's own contract names. A page that
    // lies here can make a checkpoint fail to go live, never make one live.
    client.deliverTo(discovery.nodes || []);
    // THE PLAYER'S STAKE LOCK, made by the page before the entry was built
    // (W1b), handed to the signer nodes by `join` once they hold the entry.
    if (stakeLock) client.stakeLock = stakeLock;
    return client;
  }

  /**
   * WHERE ELSE A CHECKPOINT GOES: every committee node's base, less this one.
   *
   * Measured 2026-09-10 on the Daily's 2-of-2: every checkpoint reached daemon A
   * alone, B held not even the entry, `receiptsForLive` is 2 there - so the
   * first checkpoint never went live, the head never moved, and every later one
   * was refused as "not following the chain head". 1 stored on A, 0 on B.
   */
  deliverTo(bases) {
    const norm = (u) => String(u).replace(/^ws/, 'http').replace(/\/+$/, '');
    const mine = norm(this.base);
    this.peers = [...new Set((bases || []).map(norm))].filter((b) => b && b !== mine);
    return this.peers;
  }

  constructor({ base, core, sign, verify }) {
    this.base = base;
    this.core = core;
    this.sign = sign;
    // Verifying is injected for the same reason signing is: the curve belongs
    // to whoever runs the client, and this file should not decide it.
    this.verify = verify;
    this.sock = null;
    this.head = NO_PREVIOUS;      // the mark chain head this client has published
    // WHO HAS WITNESSED WHAT. Mark id -> the distinct committee keys that have
    // receipted it. A Set because five receipts from one node is one node
    // saying the same thing five times, and 13C counts NODES.
    this.witnesses = new Map();
    this.batchHead = GENESIS;     // and the input chain's, which is a separate chain
    // WHETHER THIS CLIENT'S OWN INPUTS ARE LANDING. A run whose batches are
    // refused looks exactly like a healthy one from outside - the socket is
    // up and the player is driving - so the fact is counted and the node's
    // own sentence is kept for whoever draws the page.
    this.refusals = 0;
    // Batches answered "stake not seen" - a wallet still paying, not a refusal.
    this.stakeWaits = 0;
    this.stakeWhy = null;
    // How many settlement signer nodes have seen this entry's stake held (23.1 step 5).
    // `stakeCommitted` is a label: it gates nothing. NOT `stakeSeen`, which is a method of this class - a
    // field of that name once hid it and every call threw "this.stakeSeen is not a function".
    this.stakeCount = null;
    this.stakeCommitted = false;
    this.stakePolls = 0;
    this.stakeWatchStopped = false;
    this.stakeWatch = null;         // the running count, so a second start joins it
    // AND WHERE THE STAKE STANDS AFTER THE RUN (MF item 14), asked once it is
    // committed and until every signer node has moved the hold.
    this.settlement = null;
    this.settlementWatch = null;
    this.settlementPolls = 0;
    this.settlementOver = false;
    this.refusedWhy = null;
    this.refusedAt = null;
    this.resynced = false;
    this.recovering = null;
    this.nextTick = 0;            // the tick the node is owed next
    this.loads = [];              // [tick, feeSats, btcHundredths], not yet published
    this.samples = [];            // [tick, price], the live price samples not yet published
    this.tapes = [];              // [tick, p0 .. p63], the live tape not yet published
    this.nodes = [];              // the committee, off the round's own contract
    this.gameVerifySlots = 7;
    this.hold = [];               // ticks waiting to go out
    this.held = 0;
    this.dropped = 0;
    this.maxHold = 0;
    this.chunk = 600;
    this.batchesSent = 0;
    this.marksSent = 0;
    this.marksSkipped = 0;
    // WHAT BECAME OF EACH CHECKPOINT ON THE COMMITTEE. `marksSent` counts a
    // receipt from this client's own node, as it always has; `marksAccepted`
    // counts checkpoints that went LIVE (enough committee nodes receipted
    // them, so the head moved on); `marksRefused` counts checkpoints any node
    // refused, and the node's own words are kept. A refusal was counted as
    // nothing at all, which is how "sent 1, skipped 0" hid three refused.
    this.marksAccepted = 0;
    this.marksRefused = 0;
    this.marksRefusedWhy = null;
    this.peers = [];              // the other committee nodes' bases
    this.peerLinks = new Map();   // base -> { sock, said, opening }
    this.peerJoins = [];
    // THE RUN'S INPUTS, FOR THE OTHER COMMITTEE NODES. Measured 2026-09-10 on
    // the Daily: with checkpoints reaching both daemons, B held 0 ticks of
    // either run (A: 588 and 630) - B was receipting runs it could not replay.
    // Every batch this client's node took is kept here, and each peer is fed
    // them in order from where it last answered.
    this.published = [];          // { bytes, through } per accepted batch
    this.peerFeeds = new Map();   // base -> { next, ticks, refused, why, running }
    this.batchesInterrupted = 0;  // own socket closed with a batch in flight (not a refusal)
    this.batchesLandedUnheard = 0; // batches the node took whose answer was lost
    this.peerBatchesRefused = 0;  // a peer node SAID NO to a batch
    this.peerInputsClosed = 0;    // a batch could not reach a peer at all
    this.peerDowns = 0;           // times a peer went from answering to unreachable
    this.marksUnreached = 0;      // marks some peer never received (not refusals)
    this.marksUnreachedWhy = null;
    this.inputWaiters = [];       // marks waiting for every node to hold their inputs
    this.marksWaited = 0;
    this.markWaitMs = MARK_INPUT_WAIT_MS;
    this.markWaiting = null;      // the tick of the mark now waiting for its inputs
    this.marksTimedOut = 0;       // marks never sent: a node did not hold their inputs in time
    this.marksTimedOutWhy = null;
    this.pendingLink = null;      // { id, bytes, tick }: stored by some node, not carried by the committee
    this.marksRelinked = 0;       // pending links re-sent until the committee carried them
    this.publishing = null;
    this.marking = null;
    this.said = [];

    // WHAT ARRIVES UNASKED. A GHOSTS frame is not an answer to anything: the
    // node pushes it when somebody else's truck moves, so it cannot go into
    // the queue that pairs replies with requests. Measured before this
    // existed: every message went to `said.shift()`, so a picture arriving
    // while a batch was in flight WAS the answer to that batch - the client
    // read "the node stored N ticks" off 147 bytes of somebody's truck, and
    // the real answer then went to the next request, and so on for the rest
    // of the run. One socket, two kinds, and the type byte says which - the
    // same rule the node applies to what comes the other way.
    this.ghosts = 0;
    this.onGhost = null;
    // WHAT THIS CLIENT ASKED TO BE SHOWN, remembered so a reconnect can ask
    // again. The node keys subscribers BY CONNECTION and a reconnect is a new
    // one, so without this a player who dropped for two seconds came back
    // publishing and blind for the rest of the run - no error and no counter,
    // the pictures just stopped.
    this.watchingWhat = null;
    this.rewatched = 0;

    // THE RECONNECT, which used to live in the jslib where nothing could
    // measure it. `reconnecting` is the one in flight; `drops`, `tries` and
    // `backoff` are what a status line reads. `sleep` and `now` are injected
    // for the same reason `sign` is: a test that had to wait eight real
    // seconds to see the cap would not be run.
    // THE SESSION'S ONE WORD, and it lives here rather than in the page.
    //
    // `opening` until a socket is up, `ready` while one is, `dropped` while
    // the loop is trying, `ended` once the run is over and never anything
    // again. It was the page's before: the page learned `ended` only when
    // `reconnect` answered null, which is the socket-DOWN path - so a VOID
    // that happened with the socket still up (a slow node filling the hold)
    // left the page printing `ready` beside the run's own ENDED VOID. Two
    // words about one session, and the first is the one a reader trusts.
    // Here there is one word, and `node --test` can load the file it is in.
    this.state = 'opening';
    this.reconnecting = null;
    this.drops = 0;
    this.tries = 0;
    this.backoff = 0;
    this.resumedAt = null;
    this.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  }

  /**
   * Opens a round, and does NOT take the node's word for what it is called.
   *
   * An id here is the tagged hash of a contract the client itself wrote, so
   * the client can compute it and has no reason to be told it. Taking the
   * answer instead would mean every mark of the round is filed under an id
   * the player cannot show belongs to their own contract - and the whole
   * point of this protocol is that a node is not trusted. The node's answer
   * is still read, and it is read as AGREEMENT: if it names something else,
   * that is a disagreement about which round this is and there is nothing to
   * play until it is settled.
   */
  async openRound(contract) {
    // The committee is in the contract the client itself wrote, so the key a
    // receipt must carry is known before a single mark is sent - no census,
    // no directory, nothing taken on a node's word.
    this.nodes = [...contract.nodes];
    this.gameVerifySlots = contract.gameVerifySlots || this.nodes.length;
    const mine = roundId(contract);
    const r = await fetch(`${this.base}/round`, {
      method: 'POST', body: encodeRoundContract(contract),
    });
    if (r.status !== 201) throw new Error(`the node refused the round: ${(await r.text()).trim()}`);
    return agrees(mine, new Uint8Array(await r.arrayBuffer()), 'round');
  }

  /**
   * Joins it. The entry contract carries the session key the marks are signed
   * with, and its id is checked the same way and for the same reason.
   */
  async join(entry) {
    const mine = entryId(entry);
    const r = await fetch(`${this.base}/entry`, {
      method: 'POST', body: encodeEntryContract(entry),
    });
    if (r.status !== 201) throw new Error(`the node refused the entry: ${(await r.text()).trim()}`);

    // WHO THIS CLIENT JOINED, kept for the ghost field. A reload keeps the
    // player's key (sessionStorage) and draws a NEW entry, so the signer node this tab
    // held before the reload is still in the round, frozen - and it is this
    // player. A field that knew only its entry id kept it as somebody else:
    // measured 2026-09-10, each tab held its own pre-reload signer node as an "other",
    // and the chip named it because its frozen run had gone furthest.
    this.playerPubkey = entry.playerPubkey;

    const joined = agrees(mine, new Uint8Array(await r.arrayBuffer()), 'entry');

    // AND ON EVERY OTHER COMMITTEE NODE, or it refuses this entry's checkpoints
    // as "no such entry" - measured: daemon B answered 404 for every Daily signer node.
    // A node that will not take it is written down, not thrown: this node took
    // the entry, and the run can still be played.
    this.joinedEntry = entry;
    this.peerJoins = await Promise.all(this.peers.map((base) => this.joinOn(base)));

    // AND THE STAKE LOCK GOES TO EVERY SIGNER NODE NOW THAT THE ENTRY IS THERE (§23.1
    // step 5, W1b). A signer node verifies it in the federation and only then counts
    // the stake; before the entry is joined it has nothing to check it against.
    // The count is kept, not thrown: the round is joined either way, and the
    // stake is committed or not by the signer nodes' own answers.
    if (this.stakeLock) {
      this.lockHanded = await handLock({ entryId: mine, fields: this.stakeLock.fields,
        nodes: [this.base, ...this.peers], needed: this.stakeLock.needed });
      // AND THE PAGE IS TOLD WHICH SIGNER NODE NOW HOLDS IT, so a reload does not
      // hand the same lock to a second entry (a signer node refuses that anyway).
      if (this.lockHanded.ok && typeof this.stakeLock.onCommitted === 'function') {
        try { this.stakeLock.onCommitted(mine); } catch { /* the page's bookkeeping, not the signer node's */ }
      }
      // AND THE FEE LOCK, WHEN THE PAGE MADE ONE (Pick b: only when it can pay a
      // signer node): each signer node checks it against the entry's F and fee and keeps it for
      // the round's one settlement.
      if (this.stakeLock.feeLock) {
        this.feeLockHanded = await handLock({ entryId: mine, fields: this.stakeLock.feeLock.fields,
          nodes: [this.base, ...this.peers], needed: this.stakeLock.needed, door: 'fee-lock' });
      }
    }
    return joined;
  }

  /** A socket to another committee node, for checkpoints only. */
  peerLink(base) {
    const had = this.peerLinks.get(base);
    if (had && had.sock && had.sock.readyState === 1) return Promise.resolve(had);
    if (had && had.opening) return had.opening;
    const link = { sock: null, said: [], opening: null };
    link.opening = new Promise((resolve) => {
      const sock = new WebSocket(`${base.replace(/^http/, 'ws')}/play`);
      sock.binaryType = 'arraybuffer';
      sock.addEventListener('message', (e) => {
        const waiting = link.said.shift();
        if (waiting) waiting(typeof e.data === 'string' ? e.data : new Uint8Array(e.data));
      });
      sock.addEventListener('open', () => { link.sock = sock; link.opening = null; resolve(link); });
      sock.addEventListener('error', () => { link.opening = null; resolve(link); });
      sock.addEventListener('close', () => {
        const waiting = link.said; link.said = [];
        for (const w of waiting) w(`${CLOSED}the socket to ${base} closed`);
        if (link.sock === sock) link.sock = null;
      });
    });
    this.peerLinks.set(base, link);
    return link.opening;
  }

  /** One message to another committee node, answered the way `send` answers. */
  async sendPeer(base, message) {
    const link = await this.peerLink(base);
    if (!link.sock || link.sock.readyState !== 1) return `${CLOSED}no socket to ${base}`;
    return new Promise((r) => { link.said.push(r); link.sock.send(message); });
  }

  /** Signer nodes this client's entry on one other committee node. */
  async joinOn(base) {
    try {
      const p = await fetch(`${base}/entry`, { method: 'POST', body: encodeEntryContract(this.joinedEntry) });
      return { base, ok: p.status === 201, why: p.status === 201 ? null : (await p.text()).trim() };
    } catch (e) { return { base, ok: false, why: e.message }; }
  }

  /**
   * THE SAME INPUTS TO EVERY OTHER COMMITTEE NODE. Section 11: "the client
   * periodically sends batches and checkpoints" - both, to the committee.
   *
   * Each peer is fed the batches this client's node took, IN ORDER, from the
   * first one it has not answered: the node refuses a batch that does not
   * follow its own chain head, so a peer that missed one is caught up rather
   * than skipped past. A repeat is answered "0" and is not an error, so a
   * retry costs nothing. A refusal stops that peer's feed until the next batch
   * or checkpoint tries again, and is counted with the node's own words. The
   * node's answer to a batch is a count of new ticks and is not signed - there
   * is no batch receipt in the protocol to verify - so what is checked is that
   * the answer IS a count, from that node, for that batch.
   */
  pumpPeers() {
    for (const base of this.peers) this.#feed(base);
  }

  peerFeed(base) {
    let f = this.peerFeeds.get(base);
    if (!f) {
      f = { base, next: 0, ticks: 0, refused: 0, closed: 0, down: false, downs: 0,
        why: null, running: null, again: false };
      this.peerFeeds.set(base, f);
    }
    return f;
  }

  #feed(base) {
    const f = this.peerFeed(base);
    if (f.running) { f.again = true; return f.running; }
    f.running = (async () => {
      do {
        f.again = false;
        while (f.next < this.published.length) {
          // ASKED AS A WINDOW, READ AS A QUEUE (`FEED_WINDOW`). The frames go out back to back and the
          // answers are read in the order they were asked for, which is the order the node takes them in.
          // A steady run has one batch to send and this is one frame, as before; a peer that is behind
          // stops costing a round trip per batch of it.
          const window = this.published.slice(f.next, f.next + FEED_WINDOW);
          const asked = window.map((one) => ({ one, said: this.sendPeer(base, one.bytes) }));
          // EVERY ANSWER IS READ, INCLUDING THE ONES AFTER A REFUSAL. They are already on the wire, and a
          // promise nobody reads would leave `sendPeer`'s queue matching the next batch to this one's
          // answer. `stop` is what the old `return` said: the feed ends at the first batch that did not
          // land, `f.next` stays on it, and the next batch or mark asks again from exactly there.
          let stop = null;
          for (const { one, said } of asked) {
            const a = await said;
            if (stop) continue;
            // NO CONNECTION IS NOT A NO: counted as closed, and as one drop per
            // time the peer went away, never as a refusal. The feed stops and
            // the next batch or mark tries again, exactly as it did.
            if (typeof a === 'string' && a.startsWith(CLOSED)) {
              f.closed++;
              this.peerInputsClosed++;
              if (!f.down) { f.down = true; f.downs++; this.peerDowns++; }
              f.why = a;
              stop = 'closed';
              continue;
            }
            // A PEER THAT HAS NOT SEEN THE STAKE YET is waiting too: the feed
            // stops uncounted and the next batch or mark asks it again.
            if (typeof a === 'string' && a.startsWith(`error ${STAKE_NOT_SEEN}`)) {
              f.why = a;
              stop = 'waiting';
              continue;
            }
            if (typeof a !== 'string' || !/^[0-9]+$/.test(a)) {
              f.refused++;
              this.peerBatchesRefused++;
              f.why = typeof a === 'string' ? a : `${a.length} bytes where a tick count was due`;
              stop = /no such entry/.test(f.why) ? 'no entry' : 'refused';
              continue;
            }
            f.down = false;
            f.next++;
            f.ticks = one.through;
            this.#wakeMarks();
          }
          // A NODE THAT LOST THE SIGNER NODE IS GIVEN IT AGAIN; the next feed retries.
          if (stop === 'no entry' && this.joinedEntry) await this.joinOn(base);
          if (stop) return;
        }
      } while (f.again);
    })().finally(() => { f.running = null; });
    return f.running;
  }

  /**
   * THE FINAL MARK, RE-OFFERED (ruled 2026-09-23): the same object - its parent and tick the ones `finish` asked - to
   * every signer node that has not receipted it, feed first, once a second, from the ask until every signer node
   * holds it, the page leaves, or the round's settlement is combined. Never a second mark; never after the combine.
   */
  async #catchUpFinal() {
    if (this.catchingUp) return this.catchingUp;
    this.catchingUp = (async () => {
      for (;;) {
        const link = this.finalLink;
        if (!link || this.leftPage) return 'left';
        if (this.witnessed(link.id) >= this.nodes.length) return 'receipted';
        if (await this.#combined()) return 'combined';
        try {
          const got = await this.#relink(link);
          // WHAT A SIGNER NODE THAT HAS NOT RECEIPTED IT SAID, kept for the status line and a reader.
          this.finalRelinkWhy = [...got.refused, ...got.unreached].join('; ') || null;
        } catch (e) { this.finalRelinkWhy = e.message; }
        this.finalRelinks = (this.finalRelinks || 0) + 1;
        if (this.witnessed(link.id) >= this.nodes.length) return 'receipted';
        await new Promise((r) => { const t = setTimeout(r, FINAL_RELINK_EVERY_MS); if (t.unref) t.unref(); });
      }
    })().then((why) => { this.finalCatchUp = why; this.catchingUp = null; return why; });
    return this.catchingUp;
  }

  /** Whether the round's settlement is combined, as this client's own node answers it (none for a free round). */
  async #combined() {
    try {
      const r = await fetch(`${this.base}/lock-settlement?round=${toHex(this.where.roundId)}`);
      if (!r.ok) return false;
      const s = await r.json();
      return s && (s.state === 'SUBMITTING' || s.state === 'ACCEPTED');
    } catch { return false; }
  }

  /** Every peer's feed settled - for tests and for measuring the lag. */
  async awaitPeers() {
    for (;;) {
      const running = [...this.peerFeeds.values()].map((f) => f.running).filter(Boolean);
      if (!running.length) return;
      await Promise.all(running.map((p) => p.catch(() => {})));
    }
  }

  /** How far each peer holds this run's inputs, against this client's node. */
  peerBatches() {
    return [...this.peerFeeds.values()].map(({ base, ticks, refused, closed, down, downs, why }) =>
      ({ base, ticks, lag: this.nextTick - ticks, refused, closed, down, downs, why }));
  }

  /** Has every committee node answered that it holds this run's inputs before `tick`? */
  #holdsThrough(tick) {
    if (this.nextTick < tick) return false;
    for (const base of this.peers) if (this.peerFeed(base).ticks < tick) return false;
    return true;
  }

  /** Which committee nodes do not yet hold the inputs before `tick`, and how far they got. */
  #behind(tick) {
    const out = [];
    if (this.nextTick < tick) out.push(`${this.base} holds inputs before tick ${this.nextTick}`);
    for (const base of this.peers) {
      const f = this.peerFeed(base);
      if (f.ticks < tick)
        out.push(`${base} holds inputs before tick ${f.ticks}${f.why ? ` (${f.why})` : ''}`);
    }
    return out;
  }

  /**
   * THE PENDING LINK AGAIN, THE SAME BYTES, TO EVERY NODE.
   *
   * A node that already stored it answers with the receipt it issued (a repeat
   * writes nothing and is not an error); a node that missed it stores it now.
   * Each receipt is checked the way every receipt is, and when the committee
   * carries it `readReceipt` moves the head onto it.
   */
  async #relink(link = this.pendingLink) {
    // FEED FIRST, FOR THE FINAL MARK (ruled 2026-09-23): a peer behind on the inputs that mark commits to is fed from
    // the first batch it never answered - its feed restarts here, not only on a new batch that will never come - and
    // is offered the same mark only once it holds them. Nothing past the mark's tick exists to send: recording stopped.
    let peers = this.peers;
    if (link.final) {
      for (const b of this.peers) if (this.peerFeed(b).ticks < link.tick) await this.#feed(b);
      peers = this.peers.filter((b) => this.peerFeed(b).ticks >= link.tick);
    }
    const bases = [this.base, ...peers];
    const answers = await Promise.all([
      this.send(link.bytes), ...peers.map((b) => this.sendPeer(b, link.bytes))]);
    const refused = [];
    const unreached = [];
    answers.forEach((a, i) => {
      if (typeof a === 'string') {
        (a.startsWith(CLOSED) ? unreached : refused).push(`${bases[i]}: ${a}`);
        return;
      }
      try { this.readReceipt(a, link.id); } catch (e) { refused.push(`${bases[i]}: ${e.message}`); }
    });
    const live = this.live(link.id);
    if (live && this.pendingLink && this.pendingLink.id === link.id) { this.pendingLink = null; this.marksRelinked++; }
    return { live, refused, unreached, tick: link.tick, witnessed: this.witnessed(link.id) };
  }

  /** Sends every waiting mark whose inputs every node now holds. */
  #wakeMarks() {
    if (!this.inputWaiters.length) return;
    const still = [];
    for (const w of this.inputWaiters) {
      if (w.final ? this.nextTick >= w.tick : this.#holdsThrough(w.tick)) { clearTimeout(w.timer); w.resolve(true); } else still.push(w);
    }
    this.inputWaiters = still;
  }

  /**
   * The play socket. One connection carries both kinds - the first byte is the
   * protocol's type - so there is no second socket and no envelope.
   *
   * Answers are matched to sends in order, which is what the node does: it
   * replies to each message on the same socket in the order they arrive.
   */
  connect() {
    return new Promise((resolve, reject) => {
      const sock = new WebSocket(`${this.base.replace(/^http/, 'ws')}/play`);
      // Binary arrives as a Blob otherwise, and `new Uint8Array(blob)` is
      // silently EMPTY rather than an error - measured: a 139-byte receipt
      // read back as a zero-length array and the reply was never understood.
      sock.binaryType = 'arraybuffer';
      sock.addEventListener('error', (e) => reject(new Error(e.message || 'socket error')));
      sock.addEventListener('message', (e) => {
        if (typeof e.data !== 'string') {
          const bytes = new Uint8Array(e.data);
          // A PICTURE IS NOT A REPLY. Everything else binary that comes back -
          // a receipt for a mark - is, so the test is the type byte and not
          // "is it binary": a client that routed all bytes to a handler would
          // lose its receipts instead of its answers.
          if (bytes[0] === TYPE_GHOST) return this.takeGhost(bytes);
          const waitingForBytes = this.said.shift();
          if (waitingForBytes) waitingForBytes(bytes);
          return undefined;
        }
        const waiting = this.said.shift();
        if (waiting) waiting(e.data);
        return undefined;
      });
      sock.addEventListener('open', () => {
        this.sock = sock;
        if (!this.ended) this.state = 'ready';
        resolve(this);
      });

      // A DROPPED SOCKET IS NOT AN ERROR, it is the normal thing that happens
      // to a socket. Everything still waiting for an answer is told so by
      // name, or it would wait for one that can no longer arrive - a publish
      // that never settles stops the queue behind it for the rest of the run.
      sock.addEventListener('close', () => {
        if (this.ended) return;                         // the run is over, not dropped
        if (this.sock !== sock) return;                 // already replaced
        this.sock = null;
        const waiting = this.said;
        this.said = [];
        // NOT A REFUSAL: the node said nothing. Answered with the CLOSED word,
        // so the batch and the mark that were waiting know it was the link.
        for (const w of waiting) w(`${CLOSED}the socket closed`);
        this.drops++;
        this.state = 'dropped';
        if (this.onDrop) this.onDrop();
      });
    });
  }

  /**
   * THE SOCKET CAME BACK, OR IT DID NOT YET.
   *
   * This loop was in `blwp.jslib`, which is the one file the JS suites cannot
   * reach - so the rule that decides whether a dropped player keeps their run
   * had no test at all, while the hold and the drain beside it had a file of
   * their own. It is here now and the page calls it, so there is one set of
   * rules instead of two that look alike.
   *
   * ONE IN FLIGHT, whatever the drop rate. A second caller gets the promise
   * the first is already waiting on: two loops would open two sockets, and the
   * `close` handler on the losing one would fire a third.
   *
   * IT KEEPS TRYING, with a backoff, and that is deliberate. One attempt was
   * the whole of it once, and a node still restarting at that moment left the
   * session finished - every tick and every mark after it unpublished, which
   * §11 is blunt about the cost of. A two-second restart must not end a run.
   *
   * AND IT STOPS WHEN THE RUN HAS ENDED. `endRun` has already said VOID on
   * the publish path; a loop that went on reconnecting would hand the page a
   * live socket for a run with no honest transcript, and the page would show
   * `ready`. Nothing here decides an outcome - it only declines to re-open a
   * door on a run that is over.
   */
  reconnect(where = this.where) {
    if (this.ended) return null;
    if (this.reconnecting) return this.reconnecting;
    if (!where) throw new Error('no round to reconnect to: setRound was never called');

    this.tries = 0;
    this.backoff = 0;
    this.reconnecting = (async () => {
      // Checked EVERY time round, not once on the way in: a run can end while
      // this is asleep - the game keeps handing over ticks, and the tick that
      // will not fit the hold ends it.
      while (!this.ended) {
        this.tries++;
        try {
          await this.connect();
          const r = await this.resume(where);
          // AND ASK TO BE SHOWN THE OTHERS AGAIN. Third of the three things a
          // reconnect owes a run: a socket, the tick to carry on from, and the
          // subscription the old connection took with it.
          if (this.watchingWhat) {
            const said = await this.send(
              `watch ${toHex(this.watchingWhat.round)} ${toHex(this.watchingWhat.entry)}`);
            if (/^watching /.test(said)) this.rewatched++;
            else this.error = `the subscription did not come back: ${said}`;
          }
          this.resumedAt = r.nextTick;
          this.backoff = 0;
          this.state = 'ready';
          return r;
        } catch (e) {
          this.error = String(e.message || e);
          this.state = this.ended ? 'ended' : 'dropped';
          if (this.sock) { const sk = this.sock; this.sock = null; try { sk.close(); } catch { /* gone */ } }
          this.backoff = this.backoff ? Math.min(this.backoff * 2, 8000) : 1000;
          await this.sleep(this.backoff);
        }
      }
      return null;
    })().finally(() => { this.reconnecting = null; });

    return this.reconnecting;
  }

  /**
   * ONE PICTURE IN. Decoded here so a page never sees bytes, counted so a
   * status line can say the world is populated, and handed on if anybody is
   * listening. A frame nobody listens for is dropped rather than queued: it is
   * a 5 Hz picture of a truck that has already moved, and a backlog of them is
   * worse than none.
   *
   * NOTHING HERE IS AN INPUT. 0.10: another player's truck is a picture, never
   * an input to my simulation. This client hands it to a renderer and to
   * nothing else.
   */
  takeGhost(bytes) {
    let ghost;
    try { ghost = decodeGhost(bytes); }
    catch { this.badGhosts = (this.badGhosts || 0) + 1; return; }
    this.ghosts++;
    if (this.onGhost) this.onGhost(ghost);
  }

  /**
   * SUBSCRIBE: tell the node which round and entry this is, and be shown the
   * others. The answer is `watching N` and the N frames follow it, which is
   * why they cannot share the answer queue.
   */
  watch(round, entry) {
    this.watchingWhat = { round, entry };
    return this.send(`watch ${toHex(round)} ${toHex(entry)}`);
  }

  send(message) {
    // Answered rather than thrown, and in the same shape a refusal takes, so
    // a caller that already handles "the node said no" handles this too. A
    // throw here would escape the publish queue and take the run with it.
    if (!this.sock || this.sock.readyState !== 1)
      return Promise.resolve('error there is no socket');
    return new Promise((r) => { this.said.push(r); this.sock.send(message); });
  }

  /**
   * Commits to where the world is, at a tick, and remembers the head.
   *
   * The head is advanced only when the node says it STORED the mark. A client
   * that moved its own head on a refusal would chain the next one onto a
   * parent nobody has, and every mark after it would be refused for a reason
   * that had nothing to do with it.
   */
  /** A mark from a hash already taken - see `markHashed`. */
  async mark(hex, { roundId, entryId, tick, inputChainHash = GENESIS, final = false }) {
    const built = await markHashed(hex, {
      roundId, entryId, tick, previousHash: this.head, inputChainHash,
    }, this.sign);
    // A FINAL MARK GOES ONLY TO THE PEERS THAT HOLD ITS INPUTS; the others get it, feed first, when they catch up.
    const to = final ? this.peers.filter((b) => this.peerFeed(b).ticks >= tick) : this.peers;
    // TO EVERY COMMITTEE NODE AT ONCE, and each receipt checked on its own.
    // `readReceipt` counts the signer and moves the head only when the mark is
    // LIVE, so the next checkpoint names this one exactly when enough of the
    // committee holds it - on the Daily's 2-of-2, both.
    const [answer, ...theirs] = await Promise.all([
      this.send(built.bytes), ...to.map((b) => this.sendPeer(b, built.bytes))]);
    // A PEER THAT NEVER GOT IT IS `unreached`, NOT `refused` - see CLOSED.
    const refused = [];
    const unreached = [];
    to.forEach((base, i) => {
      const a = theirs[i];
      if (typeof a === 'string') { (a.startsWith(CLOSED) ? unreached : refused).push(`${base}: ${a}`); return; }
      try { this.readReceipt(a, built.id); } catch (e) { refused.push(`${base}: ${e.message}`); }
    });
    let receipt = null;
    if (typeof answer === 'string')
      (answer.startsWith(CLOSED) ? unreached : refused).unshift(`${this.base}: ${answer}`);
    else receipt = this.readReceipt(answer, built.id);
    const live = this.live(built.id);

    // A MARK SOME NODE STORED AND THE COMMITTEE DID NOT CARRY IS KEPT.
    //
    // Measured 2026-09-10 on two real daemons: B went down after it held the
    // inputs for tick 60, mark 60 reached A alone and never went live, and the
    // head stayed put - so the next mark named the old head. A refused it and
    // KEPT it: the second child of one parent, 13B's fork proof, published
    // against an honest player (/equivocation 200). B, which never had mark
    // 60, stored the new one, and the two daemons held two chains. So a mark
    // any node holds is remembered until the committee carries it, and no new
    // mark goes out before then - see `markNow`.
    if (live) this.pendingLink = null;
    else if (this.witnessed(built.id) > 0) this.pendingLink = { id: built.id, bytes: built.bytes, tick, final };
    // THE FINAL MARK IS RE-OFFERED UNTIL EVERY SIGNER NODE HAS RECEIPTED IT - five of seven ends the ask, not the
    // catch-up of a signer node still behind on its inputs - or the page leaves, or the settlement is combined.
    if (final && this.witnessed(built.id) > 0) {
      this.finalLink = { id: built.id, bytes: built.bytes, tick, final: true };
      if (this.witnessed(built.id) < this.nodes.length) this.#catchUpFinal();
    }
    return { ...built, answer: receipt ? 'receipted' : answer, receipt, refused, unreached, live, sentTo: to.length + 1 };
  }

  async checkpoint(st, { roundId, entryId, tick, inputChainHash = GENESIS }) {
    const mark = await markHashed(this.core.hash(st), {
      roundId, entryId, tick, previousHash: this.head, inputChainHash,
    }, this.sign);
    const answer = await this.send(mark.bytes);

    // A REFUSAL IS A STRING AND STAYS ONE. The node names its reasons -
    // "equivocation at tick 60", "expected a tick after 60" - and a client
    // that turned them into an exception would lose the name.
    if (typeof answer === 'string') return { ...mark, answer, receipt: null };

    return { ...mark, answer: 'receipted', receipt: this.readReceipt(answer, mark.id) };
  }

  /**
   * The node's answer to a mark, checked rather than believed.
   *
   * A receipt is the only thing the player gets back that is worth anything
   * later: section 12 puts `receipts[]` in the round record, and section 13B's
   * equivocation proof is built out of signed objects, not out of a node
   * having said a word once. So every part of it is checked here, and each
   * way it can be wrong is refused BY NAME - a receipt for another mark, a
   * key that is not on this round's committee, and a signature that does not
   * verify are three different failures and a client that reported them as
   * one would be hiding which.
   *
   * The head moves only after all three pass. It used to move on the word
   * 'stored'; a client that advanced its chain on an answer it had not
   * checked would be chaining onto a commitment nobody has promised to hold.
   */
  readReceipt(bytes, markId) {
    if (bytes.length !== SIGNED_RECEIPT_BYTES)
      throw new Error(`a receipt is ${SIGNED_RECEIPT_BYTES} bytes, the node sent ${bytes.length}`);
    const { body, signature } = splitSignedReceipt(bytes);
    const r = decodeCheckpointReceipt(body);

    if (toHex(r.checkpointId) !== toHex(markId))
      throw new Error(
        `the receipt is for ${toHex(r.checkpointId)}, and the mark just sent was ${toHex(markId)}`);

    if (!this.nodes.some((n) => toHex(n) === toHex(r.nodePubkey)))
      throw new Error(
        `the receipt is signed by ${toHex(r.nodePubkey)}, which is not on this round's committee`);

    if (!this.verify(signature, receiptId(r), r.nodePubkey))
      throw new Error(
        `the receipt from ${toHex(r.nodePubkey)} does not verify under its own key`);

    // THE HEAD MOVES ON LIVE, NOT ON THE FIRST RECEIPT.
    //
    // It used to move here, on one verified receipt out of seven - which was
    // true as far as it went and thinner than it sounded. Section 13C counts
    // FIVE committee nodes before a checkpoint chain is canonical, so between
    // one and four a mark is PENDING: witnessed by somebody, carried by
    // nobody. Chaining the next mark onto a parent that four nodes have never
    // agreed to would build a run on a link that cannot be canonical, and the
    // operator of a short committee could then be paid for it.
    //
    // Pending is not failed. Nothing here voids a run or loses it for the
    // player: what happens to a run whose marks never reach five is the
    // no-quorum rule, it decides FORFEIT against VOID, and it is settlement
    // rather than a client.
    this.witness(r);
    if (this.live(markId)) this.head = markId;
    return r;
  }

  /** Records one verified receipt against its mark, and answers the count. */
  witness(r) {
    const id = toHex(r.checkpointId);
    const seen = this.witnesses.get(id) || new Set();
    seen.add(toHex(r.nodePubkey));
    this.witnesses.set(id, seen);
    return seen.size;
  }

  /** How many DISTINCT committee members have receipted this mark. */
  witnessed(markId) {
    const seen = this.witnesses.get(toHex(markId));
    return seen ? seen.size : 0;
  }

  /** Is this mark carried by enough of the committee to be worth anything? */
  live(markId) {
    return this.witnessed(markId) >= receiptsForLive({
      gameVerifySlots: this.gameVerifySlots,
      nodes: this.nodes,
    });
  }

  /**
   * The receipts this node holds for a round, checked the same way as the ones
   * that came back live.
   *
   * This is what a client asks for after a reconnect. It can recompute every
   * mark it ever sent, because it built them; it cannot rebuild a signature
   * over one, so the receipts are the only part of its own round it has to
   * fetch. Verified rather than trusted for the same reason as before: a
   * receipt taken on a node's word is not evidence of anything.
   */
  async recoverReceipts({ roundId, entryId }) {
    const r = await readWithOneRetry(fetch,
      `${this.base}/receipts?round=${toHex(roundId)}&entry=${toHex(entryId)}`);
    if (!r.ok) throw new Error(`the node refused the receipts: ${(await r.text()).trim()}`);
    const bytes = new Uint8Array(await r.arrayBuffer());
    if (bytes.length % SIGNED_RECEIPT_BYTES !== 0)
      throw new Error(
        `${bytes.length} bytes is not a whole number of ${SIGNED_RECEIPT_BYTES}-byte receipts`);

    const out = [];
    for (let at = 0; at < bytes.length; at += SIGNED_RECEIPT_BYTES) {
      const one = bytes.subarray(at, at + SIGNED_RECEIPT_BYTES);
      const { body, signature } = splitSignedReceipt(one);
      const rec = decodeCheckpointReceipt(body);
      if (!this.nodes.some((n) => toHex(n) === toHex(rec.nodePubkey)))
        throw new Error(
          `a receipt signed by ${toHex(rec.nodePubkey)}, which is not on this round's committee`);
      if (!this.verify(signature, receiptId(rec), rec.nodePubkey))
        throw new Error(
          `the receipt from ${toHex(rec.nodePubkey)} does not verify under its own key`);
      this.witness(rec);
      out.push({ receipt: rec, bytes: one });
    }
    return out;
  }

  /**
   * Publishes a stretch of inputs.
   *
   * Section 11: inputs are hash-chained, and the client keeps its own copy -
   * "publishing is the client's duty, and unpublished inputs cost the player
   * the run". So the chain head and the next due tick live here, and the node
   * is never asked to remember them on the client's behalf.
   *
   * `ticks` is five Q16.16 words each, exactly what the core's `step` takes.
   * Nothing is computed from them here; they are carried.
   */
  async batch(ticks, { roundId, entryId, liquidations = [], loads = [], samples = [], tapes = [] }) {
    const b = {
      roundId, entryId,
      previousHash: this.batchHead,
      firstTick: this.nextTick,
      ticks,
      liquidations,
      loads,
      samples,
      tapes,
    };
    const bytes = encodeInputBatch(b);
    const answer = await this.send(bytes);

    // The node answers how many ticks were NEW. A refusal is a named string
    // and the chain must not move on one, the same rule the marks follow.
    if (typeof answer !== 'string' || !/^[0-9]+$/.test(answer)) return { batch: b, answer };
    this.batchHead = batchId(b);
    this.nextTick = b.firstTick + ticks.length;
    // AND THE SAME BYTES GO TO EVERY OTHER COMMITTEE NODE, in the order this
    // node took them - see `pumpPeers`. Every batch is KEPT, peers or not: a
    // node refuses a batch that does not follow its own head, so a peer that
    // arrives late can only be caught up from the run's first batch. A whole
    // run is at most blockTicks x 20 bytes of words.
    this.published.push({ bytes, through: this.nextTick });
    if (this.peers.length) this.pumpPeers();
    this.#wakeMarks();
    return { batch: b, answer, accepted: Number(answer) };
  }

  // NO `invoice()` AND NO `payStake()` (§23.6, RULED 2026-09-22 22:59). They quoted a joined player the
  // hold invoice their entry named and paid it through the wallet - the withdrawn Lightning custody's stake-in, gone with it.
  // A lock round's stake is locked in the federation by `page-lock.js`, and the page already refused
  // to reach either of these for a lock round or a free one, which is every round that can exist now.

  /**
   * PAY THE ENTRY'S DONATION TO THE SET, SHARE BY SHARE. Takes an entry and a
   * set; there is no argument an invoice could arrive in.
   *
   * ONCE PER PLAYER PER ROUND, ACROSS A RELOAD, when handed the tab's
   * `storage`: every share is noted there before the wallet is asked, and a
   * share already noted is never asked again - a reload over a kept lock
   * reports what was paid and left unpaid, and sends nothing.
   */
  async payDonation(entry, set, { round, connection, curve, fetcher = (u) => fetch(u), log, random, storage, payWith = null, ...options } = {}) {
    const none = { paid: [], failed: [], unknown: [], paidMsat: 0n, asked: 0 };
    if (!entry || typeof entry.donationMsat !== 'bigint') return { ok: false, ...none, why: 'there is no entry whose donation to pay' };
    if (entry.donationMsat === 0n) return { ok: true, ...none, why: 'this entry donates nothing, so nothing is paid' };
    // NOT BEFORE THE SIGNER NODES HOLD THE STAKE (M3.2 6e, §22A): the donation is part of
    // one wallet commitment, counted over financially activated entries only.
    // Measured before: a joined entry whose stake nobody had seen paid 2000 msat
    // to the recipients - a player who never paid the stake had donated anyway.
    // `stakeCommitted` is the settlement signer nodes' own count (`watchStake`), not
    // this page's memory of having paid.
    if (this.stakeCommitted !== true)
      return { ok: false, ...none, why: 'the stake is not in yet: no signer node has counted it, so no donation leaves the wallet' };
    if (!set || !Array.isArray(set.recipients)) return { ok: false, ...none, why: 'there is no donation set to pay' };
    if (round) {
      const named = donationSetMatchesRound(round, set.recipients);
      if (!named.ok) return { ok: false, ...none, why: named.why };
    }
    // THE PLAYER WALLET PAYS IT (Daniel 2026-10-01: "donation is paid by the player as well"): `payWith(invoice)` -
    // the federation player wallet's own send - in place of a wallet connection; each share's invoice is still the
    // recipient's own, checked against its pay request, as below.
    const where = payWith ? { ok: true } : (typeof connection === 'string' ? parseConnection(connection) : connection);
    if (!where || !where.ok) return { ok: false, ...none, why: (where && where.why) || 'there is no wallet connection to pay the donation with' };
    if (!payWith && (!curve || typeof curve.ecdhShared !== 'function' || typeof curve.signSchnorr !== 'function'))
      return { ok: false, ...none, why: 'talking to a wallet needs a curve, and none was injected' };
    const split = splitDonation({ donationMsat: entry.donationMsat, recipients: set.recipients });
    if (!split.owed) return { ok: false, ...none, why: split.why };
    const network = round && donationKeysForNetworkId(round.networkId) ? donationKeysForNetworkId(round.networkId).network : null;
    const comment = entry.playerPubkey instanceof Uint8Array ? toHex(entry.playerPubkey) : '';
    const whose = storage ? { roundId: entry.roundId || (this.where && this.where.roundId), playerPubkey: entry.playerPubkey } : null;
    if (whose && !(whose.roundId instanceof Uint8Array && whose.roundId.length === 32
      && whose.playerPubkey instanceof Uint8Array && whose.playerPubkey.length === 32))
      return { ok: false, ...none, why: 'the entry names no round and player to keep the donation\'s record under' };
    const noted = whose ? donationPaidRecord(storage, whose) : null;

    const paid = [];
    const failed = [];
    const unknown = [];
    let kept = 0;
    for (const share of split.shares) {
      if (share.amountMsat === 0n) continue;
      // ALREADY NOTED: paid, unpaid, or asked when the tab went away. Never asked again.
      const before = noted && noted.shares[share.lnurl];
      if (before) {
        kept++;
        const at = { lnurl: share.lnurl, amountMsat: BigInt(before.amountMsat), kept: true };
        if (before.state === 'paid') paid.push({ ...at, url: before.url });
        else if (before.state === 'unpaid') failed.push({ ...at, why: before.why });
        else unknown.push({ ...at, why: 'this tab asked its wallet for it before a reload and never heard the answer, so it is not asked again' });
        continue;
      }
      const note = (n) => (whose ? noteDonationShare(storage, whose, share.lnurl, { amountMsat: share.amountMsat, ...n }) : true);
      const unpaid = (why) => { failed.push({ lnurl: share.lnurl, amountMsat: share.amountMsat, why }); note({ state: 'unpaid', why }); };
      let url;
      try { url = urlOfLnurl(share.lnurl); } catch (e) { unpaid(`that recipient is no LNURL: ${e.message}`); continue; }
      let asks;
      try { asks = payRequestStands(await (await fetcher(url)).json(), share.amountMsat); }
      catch (e) { unpaid(`the recipient's endpoint did not answer: ${e.message}`); continue; }
      if (!asks.ok) { unpaid(asks.why); continue; }
      let answer;
      try { answer = await (await fetcher(callbackFor({ callback: asks.callback, amountMsat: share.amountMsat, comment, commentAllowed: asks.commentAllowed }))).json(); }
      catch (e) { unpaid(`the recipient's callback did not answer: ${e.message}`); continue; }
      if (answer && answer.status === 'ERROR') { unpaid(`the recipient refused: ${String(answer.reason || '').slice(0, 120)}`); continue; }
      const fits = invoiceAnswersPayRequest({ invoice: answer && answer.pr, amountMsat: share.amountMsat, metadata: asks.metadata, network });
      if (!fits.ok) { unpaid(fits.why); continue; }
      // NOTED BEFORE THE WALLET IS ASKED: a tab that cannot keep the note does
      // not ask, because a reload would ask again.
      if (!note({ state: 'asked' })) { unpaid('this tab could not keep a record of the payment, so the wallet is not asked - a reload would ask it again'); continue; }
      let wallet;
      if (payWith) { try { wallet = await payWith(answer.pr); } catch (e) { wallet = { ok: false, why: String((e && e.message) || e) }; } }
      else wallet = await payInvoice(where, answer.pr, {
        curve, random: random || ((n) => crypto.getRandomValues(new Uint8Array(n))), ...options,
      });
      if (!wallet.ok) { unpaid(`the wallet did not pay it: ${wallet.why}`); continue; }
      paid.push({ lnurl: share.lnurl, url, amountMsat: share.amountMsat, paymentHash: fits.paymentHash, preimage: wallet.preimage });
      note({ state: 'paid', url });
      if (log && typeof log.record === 'function') log.record({ amountMsat: share.amountMsat, paymentHash: fits.paymentHash, roundId: entry.roundId || (this.where && this.where.roundId), kind: 'donation' });
    }
    const after = donationAfterFailures({ shares: split.shares.filter((s) => s.amountMsat > 0n), failed: failed.map((f) => f.lnurl) });
    const sum = (list) => list.reduce((t, p) => t + p.amountMsat, 0n);
    return { ok: failed.length === 0 && unknown.length === 0, paid, failed, unknown, paidMsat: sum(paid),
      unpaidMsat: after.unpaidMsat, unknownMsat: sum(unknown), kept, asked: paid.length - paid.filter((p) => p.kept).length,
      why: unknown.length ? `${unknown.length} share(s) asked of the wallet before a reload, outcome unknown; ${after.why}` : after.why };
  }

  /**
   * COUNT THE SETTLEMENT SIGNER NODES THAT HAVE SEEN THIS STAKE HELD, until enough
   * have (23.1 step 5). Asked lightly - once every `everyMs` - and stopped the
   * moment N >= T, or when the run ends or this client closes.
   *
   * THE COUNT IS A LABEL AND NOTHING WAITS ON IT. The player drives the whole
   * time: ticks a node has not seen the stake for are held and sent once it
   * has (the late-payer path), and every node refuses its own receipt until it
   * has seen the hold. `stakeCommitted` says what the committee has seen; it
   * does not decide what the player may do.
   */
  //
  // ONE WATCH AT A TIME. The page starts it from the signer node and again after a
  // payment; a second start returns the watch already running rather than
  // polling every signer node twice.
  watchStake({ signerNodes, nodes, contract, everyMs = 2000, settlementEveryMs = 5000, fetcher } = {}) {
    if (this.stakeWatch) return this.stakeWatch;
    // A COUNT THAT IS OVER STAYS OVER. Committed, the run ended, or this client
    // closed: the last count is handed back and no node is asked. The chip
    // paints every 500 ms, and this is what stops it restarting a finished
    // count - a rule here, where the suite runs it, not only in index.html.
    // Measured before: a second call after committed polled every signer node again.
    if (this.stakeCommitted || this.ended || this.stakeWatchStopped)
      return Promise.resolve(this.stakeCount);
    const eid = (this.where && this.where.entryId) || (this.joinedEntry && entryId(this.joinedEntry));
    if (!eid) return Promise.reject(new Error('there is no entry to count: join first'));
    this.stakeWatch = (async () => {
      for (;;) {
        const s = await stakeSeenBy({ entryId: eid, signerNodes, nodes, contract, ...(fetcher ? { fetcher } : {}) });
        this.stakePolls++;
        this.stakeCount = s;
        this.stakeCommitted = s.committed;
        // COMMITTED IS WHERE THE NEXT WAIT BEGINS: the run, the close, the
        // objection window, the settle. The signer nodes are asked about that now.
        if (s.committed && !this.stakeWatchStopped)
          this.watchSettlement({ signerNodes, nodes, everyMs: settlementEveryMs, ...(fetcher ? { fetcher } : {}) })
            .catch(() => { /* a stake with no signer node to ask has nothing to say */ });
        if (s.committed || this.ended || this.stakeWatchStopped) return s;
        await new Promise((r) => setTimeout(r, everyMs));
        if (this.ended || this.stakeWatchStopped) return this.stakeCount;
      }
    })().finally(() => { this.stakeWatch = null; });
    return this.stakeWatch;
  }

  /**
   * WHERE THIS ENTRY'S STAKE STANDS, asked of every settlement signer node (MF item
   * 14): "the player is waiting on other people's machines and must be told
   * so, with the refund path visible the whole time". Started once the stake
   * is committed, asked every `everyMs`, and stopped when every signer node that
   * answers has moved the hold (settled, handed back, expired) or this client
   * closes. The answer rides on `stakeCount`, which is what the page already
   * hands the chip, so the chip says it with no new wiring.
   */
  watchSettlement({ signerNodes, nodes, everyMs = 5000, fetcher } = {}) {
    if (this.settlementWatch) return this.settlementWatch;
    if (this.settlementOver || this.stakeWatchStopped) return Promise.resolve(this.settlement);
    const eid = (this.where && this.where.entryId) || (this.joinedEntry && entryId(this.joinedEntry));
    if (!eid) return Promise.reject(new Error('there is no entry to ask about: join first'));
    this.settlementWatch = (async () => {
      for (;;) {
        const s = await settlementBy({ entryId: eid, signerNodes, nodes, ...(fetcher ? { fetcher } : {}) });
        this.settlementPolls++;
        this.settlement = s;
        this.stakeCount = { ...(this.stakeCount || {}), settlement: s };
        if (s.answered && SETTLEMENT_OVER.includes(s.hold)) { this.settlementOver = true; return s; }
        if (this.stakeWatchStopped) return s;
        await new Promise((r) => setTimeout(r, everyMs));
        if (this.stakeWatchStopped) return this.settlement;
      }
    })().finally(() => { this.settlementWatch = null; });
    return this.settlementWatch;
  }

  /**
   * HAS THE NODE SEEN THIS ENTRY'S STAKE HELD? `GET /stake` (23.1 step 5).
   * An answer, never a throw: `{ ok, state, paidMsat }` or `{ ok: false, why }`.
   */
  async stakeSeen(eid) {
    try {
      const r = await readWithOneRetry(fetch, `${this.base}/stake?entry=${toHex(eid)}`);
      const body = await r.text();
      if (!r.ok) return { ok: false, status: r.status, why: body.trim() };
      const said = JSON.parse(body);
      return { ok: true, state: said.state, paidMsat: BigInt(said.paidMsat) };
    } catch (e) {
      return { ok: false, why: `the node would not say whether it saw the stake: ${e.message}` };
    }
  }

  /**
   * WHERE THE NODE GOT TO, after a socket dropped.
   *
   * The daemon never asks for a retransmission - publishing is the client's
   * duty - so what a reconnecting client needs is not its batches back but
   * the two numbers that let it carry on: the next tick this node is owed and
   * the chain head to hang it off. Both are in the transcript it already
   * serves, and the marks' head is in the checkpoints beside it.
   *
   * Checked, not taken. The node checks the chain before serving, and that is
   * exactly why the client must check it again: a client that resumed from a
   * head a node made up would build every later batch onto a history nobody
   * has, and would only find out at settlement.
   *
   * There is no signature to check here, and none is invented: an `InputBatch`
   * carries none in this protocol - the chain hash is its integrity - so the
   * checks that apply are that the transcript is for the round and entry this
   * client asked about, that the chain is unbroken, and that the records are
   * whole.
   */
  /**
   * This entry's own contract, fetched and then checked against its id.
   *
   * The id IS the hash of the bytes, so this needs no trust: a node that hands
   * back another entry, or the same one with a friendlier `joinTick`, does not
   * hash to what was asked for. 25.1's rule about chain providers is the same
   * rule - a provider may omit, and it may not forge.
   */
  async entryFor(id) {
    const r = await readWithOneRetry(fetch, `${this.base}/entry?id=${toHex(id)}`);
    if (!r.ok) throw new Error(`the node has no entry ${toHex(id)}: ${(await r.text()).trim()}`);

    let entry;
    try { entry = decodeEntryContract(new Uint8Array(await r.arrayBuffer())); }
    catch (e) { throw new Error(`that entry will not decode: ${e.message}`); }

    if (toHex(entryId(entry)) !== toHex(id))
      throw new Error(
        `the node returned entry ${toHex(entryId(entry))} for ${toHex(id)}, `
        + 'so that is not the contract this player signed');
    return entry;
  }

  /**
   * THE ROUND, BY ITS ID, CHECKED AS `entryFor` CHECKS AN ENTRY: its id is the hash of its bytes, so a
   * node that returned another round - or this one with another run length - fails the comparison.
   * What it answers is read, not trusted. (M3 R1 R3: a run's length is its round's, and a client that
   * reconnects before it was told the round still has to know it.)
   */
  async roundFor(id) {
    const r = await readWithOneRetry(fetch, `${this.base}/round?id=${toHex(id)}`);
    if (!r.ok) throw new Error(`the node has no round ${toHex(id)}: ${(await r.text()).trim()}`);
    let round;
    try { round = decodeRoundContract(new Uint8Array(await r.arrayBuffer())); }
    catch (e) { throw new Error(`that round will not decode: ${e.message}`); }
    if (toHex(roundId(round)) !== toHex(id))
      throw new Error(`the node returned round ${toHex(roundId(round))} for ${toHex(id)}, so that is not the round this player entered`);
    return round;
  }

  async resume({ roundId, entryId }) {
    // A RUN THAT ENDED STAYS ENDED, and a socket coming back does not undo it.
    //
    // `endRun` said VOID on the publish path: the hold filled, a tick was
    // dropped, and no transcript from there can be replayed. This used to
    // answer such a client with a tick number and a chain head anyway, and the
    // page read that as a healthy session - status `ready`, the player still
    // driving, every later tick silently discarded and nobody told. That is a
    // disconnect working as an escape hatch, and in the operator's favour: a
    // link the operator owns ends the run and the client shows no sign of it.
    //
    // Refused by name and with NO NUMBERS. This decides nothing - the outcome
    // was decided where the fault happened - it only declines to re-animate it.
    if (this.ended)
      throw new Error(
        `this run ended ${this.ending}: ${this.endingReason} - a socket coming `
        + 'back does not resume it');

    const r = await readWithOneRetry(fetch,
      `${this.base}/transcript?round=${toHex(roundId)}&entry=${toHex(entryId)}`);
    if (!r.ok) throw new Error(`the node refused the transcript: ${(await r.text()).trim()}`);

    let t;
    try { t = decodeTranscript(new Uint8Array(await r.arrayBuffer())); }
    catch (e) { throw new Error(`the transcript will not decode: ${e.message}`); }

    if (toHex(t.roundId) !== toHex(roundId) || toHex(t.entryId) !== toHex(entryId))
      throw new Error(
        `the transcript is for round ${toHex(t.roundId)} entry ${toHex(t.entryId)}, `
        + `and this client asked about ${toHex(roundId)} ${toHex(entryId)}`);

    const ok = checkTranscript(t);
    if (!ok.ok) throw new Error(`the transcript is broken at ${ok.in} ${ok.at}: ${ok.why}`);

    // AND IT BEGINS WHERE THIS PLAYER JOINED, which for a late entrant is not
    // tick zero.
    //
    // 0.8: "late join is a normal feature, not merely reconnect", and section
    // 7: "late joins simply add more Entry Contracts". So the tick a run
    // starts at is in the entry the player signed, and this line used to fall
    // back to 0 when the node returned an empty transcript - a player who
    // joined at 50 and reconnected before publishing anything would have
    // resumed numbering from 0, and every batch after that would be the inputs
    // of one tick carrying the number of another.
    //
    // THE ENTRY IS FETCHED AND THEN HASHED, not taken on the node's word: its
    // id is the hash of its bytes, so a node that returned somebody else's
    // entry - or an edited one with a friendlier join tick - fails the
    // comparison. Nothing here trusts the answer; it checks it.
    const entry = await this.entryFor(entryId);
    // AND IT ENDS WHERE ITS ROUND'S RUN ENDS: the run length off the round, fetched and hashed like the
    // entry (M3 R1 R3) - a reconnect may come before the page was told the round (setRound).
    const round = await this.roundFor(roundId);
    const belongs = transcriptBelongsToEntry(t, entry, round.blockTicks);
    if (!belongs.ok && t.batches.length)
      throw new Error(`the transcript is not this entry's run: ${belongs.why}`);

    const before = this.nextTick;
    const last = t.batches[t.batches.length - 1];
    this.batchHead = last ? batchId(last) : GENESIS;
    this.nextTick = last ? batchTicks(last).at(-1) + 1 : entry.joinTick;

    // THE NODE MAY ALREADY HOLD WHAT THIS CLIENT STILL HOLDS: a batch it took
    // whose answer never arrived. Those words are published, so they leave the
    // hold here - or the next batch would carry them again at the node's next
    // tick. Measured before this: the node took ticks 60..89, the answer was
    // lost, and after the resume tick 90 held the input recorded for 60 - the
    // node ended up with 150 ticks for 120 recorded. Its loads leave with them.
    const landed = this.nextTick - before;
    if (landed > 0 && landed <= this.hold.length) {
      this.hold = this.hold.slice(landed);
      this.held = this.hold.length;
      this.loads = this.loads.filter(([at]) => at >= this.nextTick);
      this.samples = this.samples.filter(([at]) => at >= this.nextTick);
      this.tapes = this.tapes.filter(([at]) => at >= this.nextTick);
      this.batchesLandedUnheard++;
    }
    // AND THE PEERS ARE FED WHAT THIS NODE TOOK, including a batch whose answer
    // was lost, in the node's own order - a peer missing one refuses the rest.
    for (let i = this.published.length; i < t.batches.length; i++) {
      const b = t.batches[i];
      this.published.push({ bytes: encodeInputBatch(b), through: batchTicks(b).at(-1) + 1 });
    }

    // AND THE COUNT OF WHAT THIS CLIENT HAS ACCEPTED IS RECONCILED WITH IT.
    //
    // `offered` exists so that `nextTick + held` can be checked against it
    // before a batch goes out. A resume moves `nextTick` to whatever the node
    // is owed, so the count has to move with it or the very next drain would
    // read as a client that had lost a tick and would end the run for it.
    this.offered = this.nextTick + this.hold.length;

    // AND THE MARKS' HEAD, which is the other chain and was lost the same way -
    // but it is NOT taken from the node's last mark.
    //
    // That is what this used to do, and it was the 5-of-7 rule standing in one
    // function and missing in the next: after a drop the client adopted
    // whatever the node held, on that node's word alone. A run that lost its
    // socket was then chaining onto a mark four committee members had never
    // seen, and the operator of a short committee was paid for it.
    //
    // So the marks are walked NEWEST FIRST and the first one that five
    // distinct committee keys have receipted becomes the head. The receipts
    // are the ones just recovered, each verified here; a duplicate signer
    // cannot inflate the count and a receipt that fails its mark, the
    // committee or its signature never reached the count at all.
    const marks = await this.recoverReceipts({ roundId, entryId });
    const c = await readWithOneRetry(fetch,
      `${this.base}/checkpoints?round=${toHex(roundId)}&entry=${toHex(entryId)}`);
    const cb = new Uint8Array(await c.arrayBuffer());
    if (cb.length % SIGNED_CHECKPOINT_BYTES !== 0)
      throw new Error(
        `${cb.length} bytes is not a whole number of ${SIGNED_CHECKPOINT_BYTES}-byte marks`);

    // AND IF NONE OF THEM IS LIVE, THE HEAD STAYS WHERE THIS CLIENT CAN PROVE
    // IT BELONGS. Not the node's last mark, and not a refusal either: a
    // disconnect is not an escape hatch, and a slow committee must still be
    // able to carry the run. What comes after that head is published again,
    // which is what lets the committee catch up.
    let adopted = null;
    for (let at = cb.length - SIGNED_CHECKPOINT_BYTES; at >= 0; at -= SIGNED_CHECKPOINT_BYTES) {
      const id = checkpointId(decodeCheckpoint(splitSigned(cb.subarray(at, at + SIGNED_CHECKPOINT_BYTES)).body));
      if (this.live(id)) { adopted = id; break; }
    }
    if (adopted) this.head = adopted;

    return { ticks: ok.ticks, batches: t.batches.length, nextTick: this.nextTick,
             batchHead: this.batchHead, head: this.head, receipts: marks.length,
             live: adopted !== null, witnessed: adopted ? this.witnessed(adopted) : 0 };
  }

  /**
   * Which round this client is playing, and how long it is.
   *
   * `blockTicks` is the round's own length, off the contract, and it is the
   * only bound on the hold that means anything: inputs for more ticks than the
   * round HAS are inputs for a round that is over. The node already refuses a
   * batch longer than it, so the number comes from the contract rather than
   * from taste.
   */
  setRound({ roundId, entryId, blockTicks }) {
    this.where = { roundId, entryId };
    this.maxHold = blockTicks | 0;
    this.chunk = Math.min(600, this.maxHold || 600);
    this.hold = [];
    this.held = 0;
    this.loads = [];
    this.samples = [];
    this.tapes = [];
    this.dropped = 0;
    this.batchesSent = 0;
    this.marksSent = 0;
    this.marksSkipped = 0;
    this.marksAccepted = 0;
    this.marksRefused = 0;
    this.marksRefusedWhy = null;
    this.published = [];
    this.peerFeeds = new Map();
    this.batchesInterrupted = 0;
    this.batchesLandedUnheard = 0;
    this.peerBatchesRefused = 0;
    this.peerInputsClosed = 0;
    this.peerDowns = 0;
    this.marksUnreached = 0;
    this.marksUnreachedWhy = null;
    for (const w of this.inputWaiters) clearTimeout(w.timer);
    this.inputWaiters = [];
    this.marksWaited = 0;
    this.markWaiting = null;
    this.marksTimedOut = 0;
    this.marksTimedOutWhy = null;
    this.pendingLink = null;
    this.marksRelinked = 0;
    this.publishing = null;
    this.marking = null;
    this.offered = 0;
    this.ended = false;
    this.ending = null;
    this.endingReason = '';
  }

  /**
   * THE RUN HAS NO HONEST TRANSCRIPT, so it ends here.
   *
   * Not a defeat and not a delivery: this is a publish-path failure, and the
   * spec's word for a fault that is not the player's is VOID. A slow node that
   * filled the hold must not become a house win, and a player must not be able
   * to use a drop as a way out of a run that was going badly - the round simply
   * has no transcript anybody can replay, and that is what is said.
   *
   * Everything outbound stops. A client that cannot be honest about which tick
   * carried which input should say so rather than keep publishing a stream
   * that reads as a valid round and is not one.
   */
  endRun(reason) {
    if (this.ended) return;
    this.ended = true;
    this.ending = 'VOID';
    this.endingReason = reason;

    // SAID BEFORE THE SOCKET IS CLOSED, and that ordering is the whole point.
    // The `close` listener returns at its first line once `ended` is set - the
    // run is over, not dropped - so nothing downstream would ever hear about a
    // VOID that happened while the socket was still up. The word is set and
    // the hook fires here, on the path the fault actually took.
    this.state = 'ended';
    if (this.onEnd) this.onEnd(this.ending, this.endingReason);

    if (this.sock) { const s = this.sock; this.sock = null; try { s.close(); } catch { /* gone */ } }
  }

  /**
   * THE CORE SAID THE RUN IS OVER, AND THE RUN STOPS THERE (Daniel 2026-09-15 16:14).
   *
   * Measured before this, replaying every run a signer node held: each truck that drove into
   * the miner's mouth was DELIVERED in the core and signed so 2 of 2 - and its page went on
   * recording 620 to 5319 more ticks (10-89 s), the truck parked at the tunnel's back wall, the
   * HUD still counting metres to the drop-off, the round never over for the player.
   *
   * NOTHING HERE DECIDES THAT. The caller hands over the core's own word and the state hash at
   * the tick it said it; this stops taking ticks, puts every tick it holds on the wire, sends the
   * last checkpoint at that tick, and closes. Nothing is sent after. The word is FINISHED, not
   * the outcome: what the run came to is the replay's to say, from the ticks that went out.
   */
  finish({ stateHash = null, tick = 0, why = 'the core ended the run' } = {}) {
    if (this.ended) return Promise.resolve(null);
    if (this.finishing) return this.finishing;
    this.finishWhy = why;
    this.finishing = (async () => {
      const deadline = Date.now() + FINISH_WAIT_MS;
      while (!this.ended && (this.hold.length || this.publishing) && Date.now() < deadline) {
        const p = this.drain();
        if (p && p.then) { try { await p; } catch { /* the drain names its own fault */ } }
        else await new Promise((r) => setTimeout(r, 25));
      }
      await this.awaitPublishes();
      let mark = null;
      // THE RUN'S FINAL MARK (ruled 2026-09-23): sent to the nodes that already hold its inputs, not held for every
      // peer - it has no successor, so no second child of its parent can follow it. See `markNow` and `#catchUpFinal`.
      if (!this.ended && stateHash) { try { mark = await this.markNow(stateHash, tick, GENESIS, { final: true }); } catch { mark = null; } }
      const unsent = this.hold.length;
      if (!this.ended) {
        this.ended = true;
        this.ending = 'FINISHED';
        this.endingReason = unsent ? `${why}; ${unsent} tick(s) could not be sent` : why;
        this.state = 'ended';
        if (this.onEnd) this.onEnd(this.ending, this.endingReason);
        // AND THE SOCKET STAYS UP, FOR WATCHING (Daniel 2026-09-18 19:30: "spectate after a round: no action in the
        // world, as if no longer connected to the nodes").
        //
        // This used to close here, and it is the only connection a page has: a player who pressed SPECTATE after
        // their run saw a world with nothing in it, because every other truck reaches them over this socket. Nothing
        // is SENT after a run ends - `ended` refuses every record, drain and mark above - so keeping the line open
        // cannot publish a tick past the end, which is what the closing was for. The page closes it itself when it
        // leaves the round: `close()`, which the bridge calls when another round is joined.
      }
      return { unsent, mark };
    })();
    return this.finishing;
  }

  /**
   * WHETHER THE RUN IS OVER FOR THE GAME: ended, or the core's word taken and the last of it on its
   * way (`finish`). Measured live on the Daily (0.0.1334): the lobby came back 2241 ms after the
   * core said DELIVERED, because the game was told only once the final publish had landed - the
   * held batches and the last checkpoint, one round trip each through the tunnels at 450-500 ms.
   * Nothing is recorded from the moment of the word, so the game is told then; the wire finishes
   * on its own, and `ended` still says when it has.
   */
  get over() { return this.ended || !!this.finishing; }

  /**
   * THE CORE'S WORD FOR THIS RUN, handed over after every tick: the state word (the core's own
   * RUN_* value) and the hash at that tick. On DELIVERED the run finishes; anything else is left
   * alone. Nothing is worked out here - the word is read, not computed.
   *
   * ONLY FOR A RUN THIS CLIENT HAS BEEN TOLD IT IS PLAYING (`setRound`, the same step that puts the
   * page's core into the round's world). Measured live (0.0.1342, the second PLAY in one tab): the
   * page had the new client a few seconds before the core entered the new round, the bridge read the
   * old core - still DELIVERED from the first run - and finished the new run at tick 1.
   */
  coreWord({ state, stateHash = null, tick = 0 } = {}) {
    if (!this.where || this.ended || this.finishing) return null;
    // DELIVERED, WRECKED AND MISSED ALL LATCH IN THE CORE (Daniel 2026-09-15: "end the run here too,
    // same client path") - a run that has an outcome is over, whichever it is.
    const word = RUN_ENDING_WORDS[state | 0];
    if (!word) return null;
    return this.finish({ stateHash, tick, why: `the core said ${word} at tick ${tick}` });
  }

  /** The ending, as the game reads it: FINISHING while the last of the run goes out, then the word it ended with. */
  endingLine() {
    if (this.ended) return `${this.ending} ${this.endingReason || ''}`.trim();
    if (this.finishing) return `FINISHING ${this.finishWhy || ''}`.trim();
    return '';
  }

  /**
   * One tick's five words, kept until they can go out.
   *
   * Ticks are the transcript, so they are never thrown away while there is
   * room: unpublished inputs cannot be replayed and cost the player the run.
   * Past the round's own length they are counted rather than kept, because a
   * hold longer than the round is inputs for a round that has ended - and a
   * count is what makes a stall visible instead of silent.
   */
  /**
   * WHAT WENT ON THE BED, AT THE TICK IT WAS DECLARED.
   *
   * Heat used to be a host write straight into the core - `BlwpSetHeat` - in
   * no batch, no mark and no transcript, so a committee replaying the run and
   * every ghost it drew walked a world the war was hunting less hard than it
   * hunted the player. The LOAD travels instead of the answer: two integers a
   * host honestly knows, and the core's own rule decides what they cost.
   *
   * Held against the tick the run has reached, and published with the batch
   * that covers that tick - a load that went out ahead of its own ticks would
   * name a tick the node has not been given yet.
   *
   * Refused once the run has ended, like every other outbound thing here.
   */
  submitLoad(feeSats, btcHundredths) {
    if (this.ended || !this.where) return false;
    this.loads.push([this.offered, feeSats | 0, btcHundredths | 0]);
    return true;
  }

  /**
   * A LIVE PRICE SAMPLE the page handed its core before the tick it is about to record (Daniel 2026-09-17 16:01: the chart
   * was frozen because nothing ever did). It moves the tape, so it goes into the transcript beside that tick, published
   * with the batch that covers it, exactly as a load is. Refused once the run has ended.
   */
  submitSample(price) {
    if (this.ended || !this.where) return false;
    this.samples.push([this.offered, price | 0]);
    return true;
  }

  /** THE LIVE TAPE the page handed its core (64 prices, oldest first), published with the batch covering its tick. */
  submitTape(prices) {
    if (this.ended || !this.where || !prices || prices.length !== 64) return false;
    this.tapes.push([this.offered, ...Array.from(prices, (p) => p | 0)]);
    return true;
  }

  /**
   * WHETHER THIS RUN HAS REACHED ITS LAST TICK - the signer node's own line,
   * `lastTickOfRun(joinTick)`, and not a number of this file's. The game keeps
   * stepping after a run ends; those ticks are not inputs of the run, and a
   * batch that carries them is refused whole by every signer node. Measured live
   * (round 5, an idle page): recorded to 9113 of a run ending at 8999, refused
   * twice, and the run ended VOID - "inputs past the end". The page's tick loop
   * asks this before it records, drains or marks.
   */
  runOver() {
    if (!this.where || !(this.maxHold > 0)) return false;
    const join = this.joinedEntry && Number.isInteger(this.joinedEntry.joinTick) ? this.joinedEntry.joinTick : 0;
    return this.nextTick + this.hold.length > lastTickOfRun(join, this.maxHold);
  }

  record(words) {
    if (this.ended) return false;
    // AND NOT ONCE THE CORE HAS ENDED THE RUN: `finish` is putting the last of it on the wire.
    if (this.finishing) return false;

    // A CLIENT THAT HAS NOT BEEN TOLD WHICH ROUND IT IS PLAYING IS NOT
    // HOLDING A TRANSCRIPT, and must not end a run it never began.
    //
    // Found in a browser and only findable there. `Client.at` resolves before
    // `setRound` does - opening a round, joining it and connecting are three
    // more round trips - and the game is already ticking at 60 Hz through all
    // of them. So `record` ran against a client whose `maxHold` was still the
    // constructor's 0 and whose `offered` was undefined: the first tick of
    // every session read as a dropped one and VOIDed the run before a byte
    // had been published. `a tick was dropped at NaN: the hold was full at 0`.
    //
    // It was there before any of this door was, and it was invisible: nothing
    // was told, so the page carried on looking healthy while the client had
    // quietly given up. It shows now because a VOID stops the truck, which is
    // what makes this the bug a green suite could not have shown.
    //
    // Refused rather than held: the round these ticks would belong to does not
    // exist yet, and the entry's `joinTick` is what says where a player's
    // transcript begins.
    if (!this.where) return false;

    this.offered++;
    if (this.hold.length >= this.maxHold) {
      // THE FIRST DROPPED TICK ENDS THE RUN. It used to be counted and the
      // publishing carried on, and that was the fault: `batch` numbers a batch
      // by a COUNT of published ticks, so from the first drop onward the chain
      // says 600, 601, 602 while those words are the inputs from tick 1800 -
      // a stream that looks continuous while skipping inputs, which a verifier
      // would replay into a different world than the player was in.
      this.dropped++;
      this.endRun(`a tick was dropped at ${this.offered}: the hold was full at `
        + `${this.maxHold}, so no transcript from here can be replayed`);
      return false;
    }
    this.hold.push(words);
    this.held = this.hold.length;
    return true;
  }

  /**
   * Publish what is held, ONE batch at a time.
   *
   * The old shape appended a link to a promise chain on every sixth tick
   * whether or not the one before had finished, so a slow node grew a queue
   * nobody watched - and the `bufferedAmount` check sat inside a link, which
   * defers work without bounding anything. One in flight means there is no
   * queue to grow: what is not sent yet is simply still held, where it is
   * counted.
   */
  drain() {
    // A DRAIN THAT FINDS A BATCH IN FLIGHT IS OWED, NOT DROPPED (Daniel 2026-09-17 19:15: "updates only every 300-600 ms").
    // The page drains every sixth tick; a slot that found the last batch unanswered used to wait for the next slot, so
    // any link slower than 100 ms round trip halved the pictures - measured through a proxy holding 80 ms each way:
    // 5.0 pictures a second, 200 ms apart, 167 ms old on arrival. The answer now sends what is held at once.
    if (this.publishing && !this.ended) this.drainOwed = true;
    if (this.ended || this.publishing || !this.hold.length || !this.where) return this.publishing;
    this.drainOwed = false;
    // NOTHING GOES OUT WHILE THE TWO NUMBERS ARE BEING RE-READ. A batch built
    // from the old `nextTick` while `resume` is replacing it is the refusal
    // again, one tick later.
    // AND THE SAME WHILE A RECONNECT IS STILL RESUMING: its new socket is open -
    // `state` ready - before `resume` has read where the node is. Measured live
    // on the Daily (2026-09-15 12:21Z, a free round through a quick tunnel): the
    // page drained in that window, a batch went out from the pre-drop tick and
    // head, the node refused it, and the run ended at tick 180 with ticks stored
    // that the client never counted.
    if (this.recovering) return this.recovering;
    if (this.reconnecting) return this.reconnecting;

    // AND NOTHING GOES OUT WHILE THERE IS NO SOCKET. Without this the words
    // were sliced out of the hold, handed to a `send` that answered `error
    // there is no socket`, and concatenated back - 550 of those in a 3000-tick
    // outage, and `held` read up to `chunk` short the whole time because the
    // rows were in a doomed promise rather than in the hold. A status line
    // that under-reports a hold is the one number a stalled player has.
    if (!this.sock || this.sock.readyState !== 1) return null;

    // AND THE NUMBERS MUST AGREE BEFORE ANYTHING LEAVES.
    //
    // A batch goes out as `firstTick: nextTick`, so every tick this client has
    // ever accepted is either published or still held: `nextTick + held` has to
    // equal what was offered. If it does not, a tick went missing somewhere
    // and the next batch would put the wrong words at the wrong tick. The
    // first drop already ends the run; this is the second line, and it catches
    // any other way the two could part.
    if (this.nextTick + this.hold.length !== this.offered) {
      this.endRun(`${this.offered} ticks offered but ${this.nextTick} published and `
        + `${this.hold.length} held: a batch here would name ticks it does not carry`);
      return null;
    }
    if (this.sock && this.sock.bufferedAmount > 262144) return null;

    const words = this.hold.slice(0, this.chunk);
    this.hold = this.hold.slice(words.length);
    this.held = this.hold.length;

    // THE LOADS THIS BATCH COVERS, and no others. A load names an absolute
    // tick and the node checks it against the ticks the batch carries, so one
    // declared while these words were still held goes out with them and one
    // declared after waits for the batch that reaches it.
    const through = this.nextTick + words.length;
    const loads = this.loads.filter(([at]) => at < through);
    const later = this.loads.filter(([at]) => at >= through);
    this.loads = later;
    const samples = this.samples.filter(([at]) => at < through);
    this.samples = this.samples.filter(([at]) => at >= through);
    const tapes = this.tapes.filter(([at]) => at < through).slice(0, 1);
    this.tapes = this.tapes.filter((t) => !tapes.includes(t));

    this.publishing = this.batch(words, { ...this.where, loads, samples, tapes }).then((r) => {
      if (r.accepted) {
        this.batchesSent++;
        // PUBLISHING AGAIN IS NEWS TOO. A run that recovered must stop
        // reporting a refusal, or the page shows a fault that has been over
        // for minutes.
        this.refusedWhy = null;
        this.resynced = false;
      } else {
        // A refused batch is not a published one, and dropping it would leave
        // a hole the node will not accept across - the run would end at the
        // gap. The loads go back with the ticks they were sliced out beside:
        // a load left behind here would be a run whose replay is hunted at
        // zero from the tick the refusal happened at.
        this.hold = words.concat(this.hold); this.held = this.hold.length;
        this.loads = loads.concat(this.loads);
        this.samples = samples.concat(this.samples);
        this.tapes = tapes.concat(this.tapes);
        if (typeof r.answer === 'string' && r.answer.startsWith(CLOSED)) {
          // THE LINK WENT WITH THE BATCH IN FLIGHT. The node refused nothing,
          // so this is not a refusal and does not resync towards VOID -
          // measured before this: two such drops, and an honest run ended
          // "VOID: the node refuses this run's inputs ... error the socket
          // closed". The words are held; the reconnect reads where the node
          // is (`resume`, which drops any the node did take) and the next
          // drain sends the rest.
          this.batchesInterrupted++;
        } else if (typeof r.answer === 'string' && r.answer.startsWith(`error ${STAKE_NOT_SEEN}`)) {
          // THE STAKE IS STILL ON ITS WAY (23.1 step 5). Measured before this:
          // a player paying at wallet speed had the first batch answered "not
          // paid", resynced, got the same again, and the run ended VOID. The
          // words are held and the next drain asks again; a stake never paid
          // ends the run when the hold is full, which is that rule's job.
          this.stakeWaits++;
          this.stakeWhy = r.answer;
        } else {
          this.refusals++;
          this.refusedWhy = typeof r.answer === 'string' ? r.answer : 'the node did not say';
          this.refusedAt = this.nextTick;
          this.#afterRefusal(r);
        }
      }
      this.publishing = null;
      // A MARK IS WAITING ON TICKS STILL HELD, OR A SLOT WAS MISSED WHILE THIS BATCH WAS IN FLIGHT: carry on draining now
      // rather than on the page's next call, so the mark goes as soon as it can and the pictures keep the page's cadence.
      if ((this.inputWaiters.length || (this.drainOwed && r.accepted)) && this.hold.length) {
        const d = this.drain();
        if (d && d.catch) d.catch(() => {});
      }
      return r;
    }).catch((e) => {
      this.hold = words.concat(this.hold);
      this.held = this.hold.length;
      this.loads = loads.concat(this.loads);
      this.samples = samples.concat(this.samples);
      this.tapes = tapes.concat(this.tapes);
      this.publishing = null;
      throw e;
    });
    return this.publishing;
  }

  /**
   * A BATCH THE NODE WOULD NOT TAKE IS RESYNCED ONCE, AND THEN IT ENDS THE RUN.
   *
   * Measured before this existed: a refusal put the words back at the head of
   * the hold and changed nothing else, so the very next `drain` sent the SAME
   * batch, and a node refusing for a reason that does not go away - "expected
   * tick 4242, got 4300", "the batch does not follow the chain head" - was
   * asked the same question for the rest of the round. The socket stayed up,
   * the player kept driving, `nextTick` never moved again, and every watcher's
   * picture of that truck froze at the last tick that landed. That is the 16:08
   * two-Chrome report: P1 in the field, P2's ghost still at P1's bay, tick
   * stuck at 4241, chip saying play and two players the whole time.
   *
   * So a refusal is treated as what it is - a disagreement about where this
   * run is - and the two numbers that could be wrong are re-read from the node
   * ONCE. `resume` is the same door a reconnect uses and it checks what it is
   * given rather than adopting it. If the next batch is refused after that,
   * the disagreement is not about the numbers and the run ends with the node's
   * own words: a player whose inputs nobody stores is not driving a round, and
   * saying so is the difference between a lost run and a lost run nobody knew
   * about.
   */
  #afterRefusal(r) {
    if (this.ended || !this.where) return;
    if (this.resynced) {
      this.endRun(`the node refuses this run's inputs at tick ${this.nextTick}: `
        + `${this.refusedWhy} - and it still refused after resyncing, so this `
        + 'client cannot publish and nothing from here can be replayed');
      return;
    }
    this.resynced = true;
    this.recovering = this.resume({ roundId: this.where.roundId, entryId: this.where.entryId })
      .then(() => { this.recovering = null; })
      .catch((e) => {
        this.recovering = null;
        this.endRun(`the node refuses this run's inputs at tick ${this.nextTick}: `
          + `${this.refusedWhy} - and it would not say where the run is: ${e.message}`);
      });
    void r;
  }

  /**
   * A mark for a tick, or a count that one was missed.
   *
   * A checkpoint says where the world WAS at a tick. One that could not go out
   * while its moment passed is not that moment any more, so it is skipped
   * rather than queued behind the traffic - which is also what stops a slow
   * link turning into a flood of marks the instant it clears. Ticks are the
   * opposite and are never dropped while there is room: they are the
   * transcript.
   */
  markNow(stateHash, tick, inputChainHash = GENESIS, { final = false } = {}) {
    // A PEER WHOSE FEED STOPPED ON A REFUSAL IS TRIED AGAIN once a second,
    // here, so a peer that was briefly down catches up without a batch of its own.
    this.pumpPeers();
    // A mark after the run has ended would commit to a world whose inputs
    // nobody can produce - it names a tick the transcript cannot reach.
    if (this.ended) return null;
    // A mark needs a socket for the same reason a batch does, and one that
    // cannot go out while its moment passes is skipped - which is what the
    // count is for. Counted rather than silently dropped, so an outage is
    // visible in the same number a slow link is.
    if (this.marking || !this.where || !this.sock || this.sock.readyState !== 1) {
      this.marksSkipped++;
      return null;
    }
    // NOT BEFORE EVERY NODE HOLDS THE INPUTS IT COMES FROM. A node refuses a
    // checkpoint at tick T until it holds every input before T, and when the
    // mark is taken the last of those are still in the hold. So the mark waits
    // - the hold is pushed out now, not on the page's next drain - until this
    // client's node has taken them AND every other committee node has
    // answered that it holds them; then it goes. A mark cannot race its
    // batches and be refused for it, and a node that is behind is caught up
    // from the first batch before it is asked to sign anything.
    //
    // AND NOT FOR EVER. A node that never catches up - stopped, unreachable,
    // refusing - held the mark, and with it every later mark (skipped while
    // one waits) and `awaitPublishes`, which never returned. So the wait is
    // bounded by `markWaitMs`, and when it passes the mark is SENT TO NOBODY.
    // That is failing closed: sent to the nodes that do hold the inputs, it
    // would be stored there and not where the rest could agree, and the next
    // link would name a head the rest of the committee never had. The mark is
    // counted ("timed out N", naming who was behind and how far), the head
    // stays where every node has it, and the next mark tries again.
    // THE RUN'S FINAL MARK IS THE ONE EXCEPTION (ruled 2026-09-23): it waits only for this client's own node to hold its
    // inputs and goes to the nodes that hold them. Every other mark keeps the all-peers wait above and its timeout - it
    // exists so two marks cannot name the same parent, and a final mark has no successor to be that second child. A
    // peer that is behind is caught up afterwards, feed first, on the re-offer of this same mark (`#catchUpFinal`).
    const where = this.where;
    const holds = () => (final ? this.nextTick >= tick : this.#holdsThrough(tick));
    const ready = holds() ? true : new Promise((resolve) => {
      const w = { tick, final, resolve };
      w.timer = setTimeout(() => {
        this.inputWaiters = this.inputWaiters.filter((x) => x !== w);
        resolve(false);
      }, this.markWaitMs);
      if (w.timer && w.timer.unref) w.timer.unref();
      this.inputWaiters.push(w);
    });
    if (ready !== true) {
      this.marksWaited++;
      this.markWaiting = tick;
      const d = this.drain();
      if (d && d.catch) d.catch(() => {});
    }
    this.marking = Promise.resolve(ready).then(async (held) => {
      this.markWaiting = null;
      if (held) {
        // THE PLAYER'S OWN LINK MAY HAVE GONE WHILE THE MARK WAITED - the peers
        // are fed without it, so they can catch up and wake the mark with no
        // socket to this client's own node. Measured before this: the send
        // answered "error there is no socket", it was counted as a REFUSAL,
        // and the mark went to B alone and sat there pending. A mark that
        // cannot reach its own node is skipped and counted, the same rule as
        // when it is taken; nothing is sent to anybody.
        if (!this.sock || this.sock.readyState !== 1) {
          return {
            answer: `${CLOSED}the link to this client's own node went while the mark at tick ${tick} waited`,
            skippedNoSocket: true, refused: [], unreached: [], live: false, receipt: null,
          };
        }
        // AND NEVER A SECOND CHILD OF ONE PARENT. If a mark some node stored
        // was not carried, it goes again first; a new mark chains onto it once
        // it is live. If it still is not, the new mark is NOT sent - it would
        // name the head before the pending link, which the node holding that
        // link reads as a fork - and it is counted as skipped.
        if (this.pendingLink) {
          const again = await this.#relink();
          if (!again.live) {
            return {
              answer: `skipped: the checkpoint at tick ${again.tick} is stored but not carried, `
                + 'and a new one would name the head before it',
              skippedForLink: true, relinkRefused: again.refused, refused: [], live: false, receipt: null,
            };
          }
        }
        return this.mark(stateHash, {
          roundId: where.roundId, entryId: where.entryId, tick, inputChainHash, final,
        });
      }
      return {
        answer: `timed out after ${this.markWaitMs} ms waiting for the inputs before tick ${tick}`,
        timedOut: true, behind: this.#behind(tick), refused: [], live: false, receipt: null,
      };
    }).then((r) => {
      if (r.timedOut) {
        this.marksTimedOut++;
        this.marksTimedOutWhy = `tick ${tick}: ${r.behind.join('; ')}`;
      }
      if (r.skippedForLink || r.skippedNoSocket) this.marksSkipped++;
      if (r.answer === 'receipted') this.marksSent++;
      if (r.live) this.marksAccepted++;
      if (r.refused && r.refused.length) { this.marksRefused++; this.marksRefusedWhy = r.refused.join('; '); }
      if (r.unreached && r.unreached.length) {
        this.marksUnreached++;
        this.marksUnreachedWhy = r.unreached.join('; ');
      }
      this.marking = null;
      return r;
    }).catch((e) => { this.marking = null; throw e; });
    return this.marking;
  }

  /**
   * THE ONE LINE A DEBUG PANEL READS, built here rather than in the page.
   *
   * It was assembled in `blwp.jslib`, which is the file `node --test` cannot
   * load - and that is exactly how it came to print the page's `ready` beside
   * this run's own `ENDED VOID`, and survive an audit saying so. A line built
   * where it can be loaded is a line a test can read the first word of.
   *
   * `seen` is the game's tick counter and comes from the caller: the client
   * counts what it published, not what the renderer drew.
   */
  status(seen = 0) {
    return `${this.state} batches ${this.batchesSent} marks ${this.marksSent}`
      + ` tick ${seen} held ${this.held}`
      + (this.dropped ? ` dropped ${this.dropped}` : '')
      + (this.marksSkipped ? ` skipped ${this.marksSkipped}` : '')
      + (this.peers.length ? ` accepted ${this.marksAccepted}` : '')
      + (this.marksRefused ? ` refused ${this.marksRefused}` : '')
      + (this.marksUnreached ? ` unreached ${this.marksUnreached}` : '')
      + (this.peerBatchesRefused ? ` inputs refused ${this.peerBatchesRefused}` : '')
      + (this.peerDowns ? ` peer drops ${this.peerDowns}` : '')
      + (this.markWaiting !== null ? ` waiting ${this.markWaiting}` : '')
      + (this.marksTimedOut ? ` timed out ${this.marksTimedOut}` : '')
      + (this.pendingLink ? ` pending link ${this.pendingLink.tick}` : '')
      + (this.marksRelinked ? ` relinked ${this.marksRelinked}` : '')
      + (this.drops ? ` drops ${this.drops} tries ${this.tries} resumed ${this.resumedAt}` : '')
      + (this.batchesInterrupted ? ` interrupted ${this.batchesInterrupted}` : '')
      + (this.ended ? ` ${this.ending} ${this.endingReason}` : '');
  }

  /**
   * WAITS FOR WHATEVER IS ON THE WIRE - the batch and the mark in flight.
   *
   * IT WAS CALLED `settle` AND IT SETTLES NOTHING. 9.4's settle is a stake
   * moving on Lightning after a round is final, decided by the committee from
   * the core's own outcome word; this awaits two promises so a caller can read
   * `status()` without racing it. Two things with one name, and the name
   * belonged to the other one - it is the fourth word of M3.2 item 5, and a
   * reader coming to the session flow would find this.
   */
  async awaitPublishes() {
    while (this.publishing || this.marking) {
      try { await Promise.all([this.publishing, this.marking]); } catch { /* named elsewhere */ }
    }
  }

  close() {
    this.stakeWatchStopped = true;
    this.leftPage = true;              // the page left: the final mark is not re-offered any more
    if (this.sock) this.sock.close();
    for (const link of this.peerLinks.values()) if (link.sock) link.sock.close();
  }
}

// ---- protocol/src/display-name.js
// 0.12 DISPLAY NAME. Identity is the player key. The name is presentation.
//
// Daniel 2026-09-08 18:55 (M3): default name is derived from the key so every
// client shows the same string for the same player. A player may override it.
// The override lives next to the secret in the browser, not on the signed
// final, so the board still cannot be injected with a name (letter 20).
// Donation LNURL comments carry the player public key as hex, not the name
// (Daniel 2026-09-08 18:59).
//
//   default = adjective-animal-NNNN
//   digest  = taggedHash('BLWP/v1/DISPLAY_NAME', playerPubkey)
//
// Two wordlists would name one player twice, which is why this file exists
// rather than letting a client invent one.


const DISPLAY_NAME_TAG = 'BLWP/v1/DISPLAY_NAME';
const DISPLAY_NAME_MAX = 32;

const ADJECTIVES = Object.freeze([
  'amber', 'azure', 'bold', 'brave', 'brisk', 'calm', 'cool', 'coral',
  'crisp', 'dark', 'dawn', 'deep', 'dry', 'dusk', 'eager', 'even',
  'fair', 'firm', 'flat', 'glad', 'gold', 'grim', 'harsh', 'holy',
  'icy', 'idle', 'iron', 'jade', 'jolly', 'keen', 'kind', 'late',
  'loud', 'lush', 'merry', 'mild', 'mint', 'neat', 'near', 'noble',
  'odd', 'open', 'pale', 'plain', 'proud', 'quick', 'quiet', 'rapid',
  'rare', 'royal', 'safe', 'sharp', 'silent', 'steel', 'swift', 'tall',
  'true', 'urban', 'vast', 'vivid', 'warm', 'wild', 'young', 'zinc',
]);

const ANIMALS = Object.freeze([
  'otter', 'hawk', 'wolf', 'bear', 'fox', 'lynx', 'stag', 'elk',
  'moose', 'swan', 'crow', 'raven', 'dove', 'lark', 'wren', 'pike',
  'perch', 'trout', 'carp', 'bass', 'eel', 'crab', 'seal', 'whale',
  'shark', 'ray', 'frog', 'toad', 'newt', 'deer', 'boar', 'ram',
  'colt', 'mare', 'ox', 'yak', 'ape', 'bat', 'cub', 'doe',
  'emu', 'gnu', 'hen', 'hog', 'jay', 'owl', 'pup', 'sow',
  'asp', 'bee', 'cat', 'cow', 'dog', 'fly', 'goat', 'hare',
  'ibis', 'koi', 'mole', 'puma', 'rook', 'tern', 'orca', 'kiwi',
]);

if (ADJECTIVES.length !== 64 || ANIMALS.length !== 64) {
  throw new Error('display-name wordlists must be 64 each');
}
if (new Set(ADJECTIVES).size !== 64 || new Set(ANIMALS).size !== 64) {
  throw new Error('display-name wordlists must be unique');
}

function requirePubkey(playerPubkey) {
  if (!(playerPubkey instanceof Uint8Array) || playerPubkey.length !== 32) {
    throw new Error('a display name is derived from a 32-byte player key');
  }
}

/** Default name every client derives for this key. adjective-animal-NNNN */
function displayNameFromKey(playerPubkey) {
  requirePubkey(playerPubkey);
  const d = taggedHash(DISPLAY_NAME_TAG, playerPubkey);
  const adj = ADJECTIVES[d[0] & 63];
  const animal = ANIMALS[d[1] & 63];
  const num = ((d[2] << 8) | d[3]) % 10000;
  return adj + '-' + animal + '-' + String(num).padStart(4, '0');
}

/**
 * A custom name the player typed. Empty / invalid means "use the default".
 * No em dash. Max 32. Printable ASCII letters, digits, space, dot, _ -.
 */
function normalizeDisplayName(raw) {
  if (raw == null) return null;
  if (typeof raw !== 'string') return null;
  const s = raw.trim();
  if (!s) return null;
  if (s.length > DISPLAY_NAME_MAX) return null;
  if (/[—–]/.test(s)) return null;
  if (!/^[A-Za-z0-9][A-Za-z0-9._ -]{0,31}$/.test(s)) return null;
  return s;
}

/** Name to show on the board and in the client. Not the donation comment. */
function displayNameFor(playerPubkey, custom) {
  return normalizeDisplayName(custom) || displayNameFromKey(playerPubkey);
}

/** LNURL-pay comment: the player public key as hex. Not the display name. */
function donationCommentFor(playerPubkey, commentAllowed = 140) {
  requirePubkey(playerPubkey);
  const hex = toHex(playerPubkey);
  const max = Number(commentAllowed);
  if (!Number.isFinite(max) || max < hex.length) return '';
  return hex;
}

/**
 * What the browser stores. secretKey never leaves the machine except via the
 * player's own backup download. displayName null = derive from the key.
 */
function playerStoreRecord({ secretKey, displayName = null }) {
  requirePubkey(secretKey);
  return {
    version: 1,
    secretKey: toHex(secretKey),
    displayName: normalizeDisplayName(displayName),
  };
}

// ---- blwp-client/src/ghost-field.js
// WHAT THE PAGE DOES WITH A PICTURE OF SOMEBODY ELSE'S TRUCK.
//
// Letter 18 got a ghost produced, delivered and decoded: the daemon replays
// what the other player published, pushes it on the /play socket, and
// `Client.takeGhost` hands it to `onGhost` without stealing an RPC answer.
// Measured at the start of 28: `onGhost` had NO consumer anywhere outside the
// tests, `blwp.jslib` had no ghost entry point, and `GhostTruck.Show` had no
// caller. Produced, delivered, decoded - and drawn by nobody.
//
// This is the page's half, and it lives here rather than in `blwp.jslib`
// because that file is the one place `node --test` cannot load: the rule that
// decides whether a player ever sees a competitor should not be the one rule
// with no test. The jslib asks for the frames; this decides what is kept.
//
// NOTHING HERE IS AN INPUT. 0.10: another player's truck is a picture, never
// an input to my simulation. A queue of pictures is handed to a renderer and
// to nothing else - `packages/core` is not imported, and cannot be.


/** How many pictures a page will hold before it starts dropping the oldest. */
const GHOST_BACKLOG = 240;
/**
 * HOW LONG A TRUCK MAY BE QUIET BEFORE ITS PICTURE IS CALLED STALE (a live run sends ten a second).
 *
 * It used to RETIRE the truck at this age, and that is what Daniel photographed on 2026-09-18 10:42: the other truck
 * missing, and then somewhere else. Measured on the Daily the same hour: 5231 pictures, gaps to 5131 ms, nine of them
 * over three seconds - every one of those took a truck off the screen and the next picture put it back, metres away.
 * The pose itself was never drifting (p50 2, p90 3 ticks behind the driver in every third of a round).
 *
 * So silence no longer takes a truck away. It stands where its last picture put it and the label's age grows, which is
 * the truth and is readable; a truck leaves the screen only when the page KNOWS it is gone - the player's next entry
 * supersedes it, or a new round clears the field.
 */
const SILENT_MS = 3000;

/**
 * THE TICK WORD OF A RETIRE. No picture has a negative tick, so the same twelve
 * words `BlwpNextGhost` already carries say "take this entry's truck away" -
 * `GhostField.Show` reads a tick below zero as exactly that.
 */
const RETIRE_TICK = -1;

/**
 * Subscribe for the round this player is in, and keep what arrives.
 *
 * `where` is the client's own `{ roundId, entryId }` - the same object
 * `setRound` was given - and the entry id in it is the one thing that must
 * never be drawn: a player does not need a picture of the truck they are
 * driving. The daemon already refuses to send one (26/18), and this refuses to
 * keep one, because "the other end will not do that" is not a reason to accept
 * it if it does.
 */
function watchGhosts(client, where, { limit = GHOST_BACKLOG, clock = Date.now } = {}) {
  if (!client) throw new Error('no client to watch with');
  if (!where || !where.roundId || !where.entryId)
    throw new Error('a watch names the round and the entry it is watching from');

  const mine = toHex(where.entryId);
  // WHO THIS TAB IS, not only which entry it holds. A reload keeps the player's
  // key and draws a new entry, so this tab's pre-reload entry is still in the
  // round and is still this player (`Client.join` keeps the key it joined).
  const me = where.playerPubkey || client.playerPubkey || null;
  const myKey = me ? toHex(me) : null;
  // ONE TRUCK PER PLAYER, and the picture that arrived LAST is that player's.
  // A reload leaves the player's old entry in the round with a frozen run that
  // may have gone further than the live one - measured 2026-09-10: dead entries
  // at ticks 4229 and 4227, the live other at 3041, and the chip named the
  // dead one at -97,-10 because `newestPose` takes the highest tick. A dead
  // entry never sends again, so the live entry's next picture replaces it. A
  // picture that names no player is keyed by its entry, as before.
  const whoOf = (g) => (g.playerPubkey ? 'p:' + toHex(g.playerPubkey) : 'e:' + toHex(g.entryId));
  // AND ONE ENTRY OF EACH PLAYER IS THE ONE UNITY DRAWS. Unity keeps a truck per
  // entry and never removed one, so every entry a player had left stood frozen:
  // measured 2026-09-10 on the Daily, a reload handed Unity 9 and 11 entries, 8
  // and 10 of them abandoned (one picture each), and a watched player's reload
  // left its 105-picture entry frozen beside the new one. An entry is PROVEN once
  // it sends a second picture - an abandoned entry never does.
  const drawnEntry = new Map();   // player -> { e, entryId, playerPubkey }
  const pictures = new Map();    // entry -> pictures seen
  const queue = [];
  const retire = (entryKey) => {
    queue.push({ entryId: entryKey.entryId, playerPubkey: entryKey.playerPubkey, x: 0, z: 0, heading: 0,
      tick: RETIRE_TICK, retire: true });
    field.retired++;
  };
  // WHO IS HERE, independent of the drain the renderer takes. A picture
  // Unity has already drawn is gone from the queue; it is still a player
  // in the round, and the page's count has to say so.
  const present = new Map();
  // HOW EACH DRAWN TRUCK LAST MOVED, for the debug label over it (Daniel 2026-09-17 19:15): the arrows between its last
  // two pictures and when the newest arrived.
  const motion = new Map();
  const field = {
    present,
    motion,
    seen: 0,
    self: 0,
    shed: 0,
    // entries a player left, told to Unity to take away; and first pictures of
    // another entry while this player's drawn entry is live, never drawn
    retired: 0,
    /** Trucks taken away because this page's own run ended: no picture of that round can arrive again. */
    roundEnded: 0,
    /** Set once the run is over and its trucks have been taken away, so it is done once and not every frame. */
    roundDone: false,
    superseded: 0,
    // pictures dropped because a newer one of the same truck was already waiting, and trucks whose newest picture
    // is older than SILENT_MS (counted, not retired)
    collapsed: 0,
    silenced: 0,
    // HOW MANY PICTURES SOMEBODY ACTUALLY TOOK TO DRAW.
    //
    // A field that is filling and never drained looks exactly like a field
    // that is empty from the outside: `others` counts trucks in the round
    // either way. That is the shape of the 11:51 failure - the chip said five
    // players and the screen showed one truck - and the page had no number
    // that could tell the two apart.
    drawn: 0,
    get size() { return queue.length; },
    get others() { return present.size; },

    /**
     * WHAT THE RENDERER DRAWS NOW: every retire, then the NEWEST picture of each truck - never a backlog of where a truck
     * was (Daniel 2026-09-17 17:05 / 17:12: "the ghost is drawn at a completely different place ... 60 s+ delay ... must
     * be REALTIME"). Pictures queued behind a newer one of the same truck are dropped here, so a tab whose frames paused
     * or fell behind draws each other truck where its newest picture puts it, not where it stood a minute ago. A truck
     * that has sent nothing for SILENT_MS is retired: a live run sends ten pictures a second even parked, so silence is a
     * run that ended or a tab that left, and its truck must not stand frozen. Up to `max` are handed over; the rest stay.
     */
    drain(max = queue.length, nowMs = clock()) {
      // A QUIET TRUCK IS COUNTED, NOT TAKEN AWAY (Daniel 2026-09-18 10:42). A gap of three or five seconds is the
      // signer nodes stalling, not a player leaving, and removing the truck for it is what "missing, then in the
      // wrong place" was: the next picture drew it again somewhere else.
      field.silenced = 0;
      for (const [, d] of drawnEntry) if (nowMs - d.at > SILENT_MS) field.silenced++;

      // BUT A TRUCK OF A ROUND THAT IS OVER GOES (Daniel 2026-09-18 12:02: "after 2nd round Truck 1 cannot see
      // Truck 2. Age 6736ms"). Measured on the Daily with a watcher that kept its field across two boundaries: it
      // carried one truck of the round it had left into each new round and never received a single picture of the
      // new one - first picture NEVER, superseded 0, stale pictures 0 - so that truck stood for ever with its age
      // climbing. Until 0.0.1591 the three-second silence took it away; nothing else ever did.
      //
      // This is not the silence rule coming back: a live round keeps its trucks through any stall. What ends them is
      // the page's OWN run being over, because then no picture of that round can ever arrive again.
      if (!field.roundDone && typeof client.runOver === 'function' && (client.ended || client.runOver())) {
        field.roundDone = true;
        for (const [who, d] of drawnEntry) { retire(d); drawnEntry.delete(who); present.delete(who); field.roundEnded++; }
      }
      const retires = [], newest = new Map();
      for (const g of queue) {
        if (g.retire) { retires.push(g); newest.delete(toHex(g.entryId)); } else newest.set(toHex(g.entryId), g);
      }
      const all = retires.concat([...newest.values()]);
      field.collapsed += queue.length - all.length;
      const took = all.slice(0, Math.max(0, max | 0));
      queue.length = 0;
      for (const g of all.slice(took.length)) queue.push(g);
      field.drawn += took.length;
      return took;
    },

    /**
     * PICTURES ARE ARRIVING AND NOBODY IS DRAWING THEM.
     *
     * True when the field has been sent pictures of somebody else and none of
     * them has ever been taken. A renderer calls `drain` every frame, so one
     * frame of a working page clears this; a page whose `GhostField` is not in
     * the scene, or whose bridge is not wired, never does - and that is a
     * different fault from an empty round, which is what it used to look like.
     */
    get stalled() { return field.seen > field.self && field.drawn === 0; },

    /**
     * The newest picture of each truck, which is what a renderer wants.
     *
     * OFF `present`, NOT OFF THE QUEUE. It used to read the queue, and the
     * queue is what `drain` empties - so a renderer that drew its frame and
     * then asked what it was holding was told NOTHING, while the trucks were
     * still in the round. Measured: two frames in, `latest()` said one
     * picture; after one `drain(24)` - which is exactly what
     * `GhostField.Draw(PerFrame)` does every frame - it said zero.
     *
     * `present` exists for this and says so three lines up: "A picture Unity
     * has already drawn is gone from the queue; it is still a player in the
     * round." Reading the queue made that comment false for every caller but
     * the first.
     */
    latest() {
      return [...present.values()];
    },
  };

  client.onGhost = (ghost) => {
    field.seen++;
    // NEVER YOURSELF - this entry, or any earlier entry of this same player.
    if (toHex(ghost.entryId) === mine
        || (myKey && ghost.playerPubkey && toHex(ghost.playerPubkey) === myKey)) { field.self++; return; }

    const who = whoOf(ghost);
    const entryKey = toHex(ghost.entryId);
    const n = (pictures.get(entryKey) || 0) + 1;
    pictures.set(entryKey, n);
    const drawn = drawnEntry.get(who);
    if (drawn && drawn.e !== entryKey) {
      // A FIRST PICTURE OF ANOTHER ENTRY WHILE THE DRAWN ONE IS LIVE is an entry
      // that player left: it never reaches Unity.
      if (n < 2 && (pictures.get(drawn.e) || 0) >= 2) { field.superseded++; return; }
      // Otherwise the drawn entry is the one superseded, and Unity is told.
      retire(drawn);
    }
    drawnEntry.set(who, { e: entryKey, entryId: ghost.entryId, playerPubkey: ghost.playerPubkey, at: clock() });

    const was = present.get(who);
    const before = motion.get(who);
    motion.set(who, { atMs: clock(),
      glyphs: was && toHex(was.entryId) === entryKey ? moveGlyphs(was, ghost) : (before ? before.glyphs : '') });
    present.set(who, ghost);
    queue.push(ghost);
    // A FULL QUEUE SHEDS PICTURES OLDEST FIRST, which is piece 2 of letter 18
    // stated for the page: a picture of where a truck WAS is worth less than
    // the one behind it, and a backlog of them is worse than none. A RETIRE IS
    // NEVER SHED: dropping one would leave that truck standing for good.
    while (queue.length > limit) {
      const i = queue.findIndex((g) => !g.retire);
      if (i < 0) break;
      queue.splice(i, 1);
      field.shed++;
    }
  };

  field.watching = client.watch(where.roundId, where.entryId);
  return field;
}

/** Q16.16: the words a picture carries, per metre. `GhostTruck.ONE` is the same number. */
const ONE_METRE = 65536;

/**
 * WHICH WAY A TRUCK WENT BETWEEN TWO OF ITS PICTURES, as the debug label draws it (Daniel 2026-09-17 19:15): an up
 * arrow for forward, a down arrow for back, a left or right arrow for a turn, both when it did both. Read off the
 * pictures - what reached this page through the nodes - not off anybody's keys. Forward is the step along the hull
 * (heading in turns: x = sin, z = cos, a growing heading turns right); a turn is the heading's change, mirrored while
 * backing, so a steer to the right reads right either way. Under 2 cm and under 16 of 65536 of a turn is standing.
 */
function moveGlyphs(a, b) {
  const dx = (b.x - a.x) / ONE_METRE, dz = (b.z - a.z) / ONE_METRE;
  const h = (b.heading / 65536) * 2 * Math.PI;
  const along = dx * Math.sin(h) + dz * Math.cos(h);
  const back = along < -0.02;
  let dh = ((((b.heading - a.heading) % 65536) + 98304) % 65536) - 32768;
  if (back) dh = -dh;
  return (along > 0.02 ? '\u2191' : back ? '\u2193' : '') + (dh < -16 ? '\u2190' : dh > 16 ? '\u2192' : '');
}

/**
 * THE WALL CLOCK OF EACH TICK A TAB DROVE, shared with the other tabs of this browser (Daniel 2026-09-17 19:15: "age =
 * how old the last move is, as seen on the other client after it went through the nodes"). A driving tab posts its
 * newest tick and the time it recorded it; a watching tab reads the time of the tick a picture names when that picture
 * is drawn. Only the stamp travels on the channel - the picture itself still comes from the nodes. A tab with no
 * channel, or a truck driven in another browser, has no stamp, and its label says the age since the picture arrived.
 *
 * THE CHANNEL IS HANDED IN, as `sign` and `verify` are: nothing in this package reads a name off the page (the client's
 * own rule, `discovery.test.js`), and a test drives the same door the page does.
 */
function tickClock({ Channel = null, name = 'blwp-ghost-clock', keep = 64 } = {}) {
  const stamps = new Map();
  const put = (e, t, ms) => {
    let a = stamps.get(e);
    if (!a) stamps.set(e, (a = []));
    a.push([t, ms]);
    if (a.length > keep) a.shift();
  };
  let channel = null;
  try { if (typeof Channel === 'function') channel = new Channel(name); } catch { channel = null; }
  if (channel) {
    channel.onmessage = (m) => {
      const d = m && m.data;
      if (d && typeof d.e === 'string' && Number.isInteger(d.t) && Number.isFinite(d.ms)) put(d.e, d.t, d.ms);
    };
  }
  return {
    shared: channel !== null,
    post(entryHex, tick, ms = Date.now()) {
      put(entryHex, tick, ms);
      if (channel) { try { channel.postMessage({ e: entryHex, t: tick, ms }); } catch { /* a closed channel */ } }
    },
    /** When the tab driving `entryHex` recorded `tick`, off its nearest stamp within a second; null when none. */
    sentMs(entryHex, tick) {
      const a = stamps.get(entryHex);
      if (!a) return null;
      let best = null;
      for (const s of a) if (best === null || Math.abs(s[0] - tick) < Math.abs(best[0] - tick)) best = s;
      if (best === null || Math.abs(best[0] - tick) > 60) return null;
      return best[1] + ((tick - best[0]) * 1000) / 60;
    },
    close() { if (channel) channel.close(); },
  };
}

/**
 * ONE DEBUG LABEL PER DRAWN TRUCK: its entry (the key Unity keeps the truck under), the player's name, how old its
 * newest picture is in ms, and how it moved. `estimated` is true when no stamp of the driver's own clock was found and
 * the age is only the time since that picture arrived here.
 */
function ghostLabels(field, { nowMs = Date.now(), nameOf = () => null, clock = null } = {}) {
  const out = [];
  if (!field || !field.present) return out;
  for (const [who, g] of field.present) {
    const entry = toHex(g.entryId);
    const player = g.playerPubkey ? toHex(g.playerPubkey) : null;
    const name = (player && nameOf(player)) || (g.playerPubkey ? displayNameFromKey(g.playerPubkey) : entry.slice(0, 8));
    const sent = clock ? clock.sentMs(entry, g.tick) : null;
    const m = field.motion ? field.motion.get(who) : null;
    const estimated = sent === null;
    const ageMs = Math.max(0, Math.round(nowMs - (estimated ? (m ? m.atMs : nowMs) : sent)));
    out.push({ entry, name, ageMs, estimated, glyphs: m ? m.glyphs : '' });
  }
  return out;
}

/** The labels as the bridge hands them to Unity: one line a truck, tab-separated, line 2 already written. */
function ghostLabelText(labels) {
  return labels.map((l) => `${l.entry}\t${l.name}\t${l.estimated ? '~' : ''}${l.ageMs}ms ${l.glyphs}`.trimEnd()).join('\n');
}

/**
 * WHERE THE NEWEST OTHER TRUCK IS, in metres, or null for nobody.
 *
 * A truck that is drawn 100 m down the frontage and a truck that is not drawn
 * at all look identical through a windscreen, and `stalled` only separates
 * them when NOTHING was ever drawn. Each player parks at their own loading
 * bay - 24 doors at 6.8 m - so two tabs on one round start up to 156 m apart
 * along the same apron, which is exactly far enough to be off screen.
 *
 * So the page says the place. The operator reads it against the position the
 * other tab's own HUD shows: the same two numbers means the picture is right
 * and the camera is pointed elsewhere, different numbers means it is not.
 */
function newestPose(field) {
  if (!field || typeof field.latest !== 'function') return null;
  let best = null;
  for (const g of field.latest()) if (best === null || g.tick > best.tick) best = g;
  return best === null ? null : { x: best.x / ONE_METRE, z: best.z / ONE_METRE, tick: best.tick };
}

/**
 * One line the page can put on screen. Count is 1 (this tab) plus others.
 *
 * `refused` is THIS TAB'S OWN transcript being turned away by the node, and it
 * comes first because it is the one fault the other numbers cannot show. A tab
 * whose batches stopped landing keeps its socket, keeps its player count and
 * keeps driving; what it loses is every watcher's picture of it, frozen at the
 * last tick that landed. That is what the 16:08 two-Chrome close-out saw from
 * the other side, and neither tab had a number that said so.
 */
function playersLine({ joined, others, stalled = false, at = null, refused = null,
  joinRefused = null, stake = null, names = [] } = {}) {
  // WHY THERE IS NO ENTRY, AND NOT MERELY THAT THERE IS NONE.
  //
  // Letter 15 made the page refuse a paying round whose settlement committee
  // it cannot learn - and the refusal went to `console.error`, so the chip
  // read "round named · not joined" exactly as it does for a round nobody was
  // sent to. Worse, the bridge then threw "the page did not say which round to
  // play", which names the wrong cause entirely. A refusal nobody can see is
  // the silent entry again, wearing the other hat.
  if (joinRefused) return `not joined · ${joinRefused}`;
  if (!joined) return 'round named · not joined';
  if (refused) return `not publishing · ${refused}`;

  // AND WHETHER THIS ENTRY IS PAID FOR.
  //
  // A dealt stake is not a funded one: the page deals the preimage and the
  // shares, and paying the hold invoice is a wallet it has not got yet (M3.2).
  // Without this line a free round and a funded entry read identically, which is
  // the thing letter 15 exists to stop.
  //
  // THE WORD IS THE NODE'S. `Client.join` keeps the `x-hold` the node answered
  // when it took the entry; a page that printed "not paid" as a constant would
  // be reporting its own assumption as the player's balance.
  const funding = stakeLine(stake);
  // AND WHO THE OTHERS ARE, BY THE NAMES THEY CHOSE (M3.3-34): each from a
  // record its player signed (identity.js `namesOf`), never a key. A player the
  // entries keep no name for is counted, not stubbed. A named player who has not
  // driven yet is still in the round, so the count is the larger of the two.
  const shown = (Array.isArray(names) ? names : []).filter((x) => typeof x === 'string' && x);
  const n = 1 + Math.max(others | 0, shown.length);
  // THE FUNDING WORD IS ON EVERY BRANCH, and it was not: this returned early
  // for a lone player, so the one line a player sits looking at while they
  // wait for somebody else - the longest-lived line on the chip - was the one
  // that did not say the entry was unpaid. Its own test caught it.
  if (n <= 1) return '1 player · waiting' + funding;
  // A PAGE THAT IS BEING SENT TRUCKS AND DRAWING NONE SAYS SO. Without this
  // the line reads the same as a page that is drawing them, which is what
  // made the 11:51 retest a guess: five players on the chip, one truck on the
  // screen, and no number between them.
  const where = at ? ` · other at ${Math.round(at.x)},${Math.round(at.z)} m` : '';
  const who = shown.length ? ': ' + shown.join(', ') + (n - 1 > shown.length ? ` +${n - 1 - shown.length} more` : '') : '';
  return n + ' players in this round' + who + (stalled ? ' · none drawn' : '') + where + funding;
}

/**
 * WHAT THE ENTRY COST, IN THE WORDS THE NODE USED.
 *
 * `free round` is a round that asks no stake - there is nothing to pay and nothing was dealt.
 *
 * A STAKE IS COUNTED, NOT NAMED (23.1 step 5): "not yet counted" until `stakeSeenBy` has asked the
 * settlement entries, then "stake seen by N of M nodes (T needed)", with the entries that did not answer
 * named and "committed" only at N >= T. A signer node sees a stake when it has verified its federation
 * lock. There used to be a second source here - the node's join-time `x-hold` word, which named a
 * hold invoice's state and its reason for having none - and it went with the hold invoice, which was
 * the withdrawn Lightning custody's (§23.6, RULED 2026-09-22 22:59).
 */
function stakeLine(stake, nowMs = Date.now()) {
  if (!stake) return '';
  if (stake.free) return ' · free round';
  if (!stake.dealt) return '';
  const s = stake.seen;
  if (s && typeof s.seen === 'number') {
    return ` · stake seen by ${s.seen} of ${s.of} nodes (${s.needed} needed)`
      + (s.unanswered ? `, ${s.unanswered} did not answer` : '')
      + (s.committed ? ' · committed' : '')
      + settlementLine(s.settlement, nowMs);
  }
  return ' · stake dealt, not yet counted';
}

/**
 * WHERE THE STAKE STANDS AFTER THE RUN, in the settlement entries' words (MF
 * item 14): "the player is waiting on other people's machines and must be told
 * so, with the refund path visible the whole time". `s` is `settlementBy`'s
 * answer. Nothing is added until the entries have a result to wait on - before
 * that the count above is the whole story.
 *
 * SETTLED says the run lost the stake, and no more: where a settled stake goes
 * next is a ruling still open, and the chip does not claim it.
 */
function settlementLine(s, nowMs = Date.now()) {
  if (!s || !s.answered) return '';
  // WHERE THE RUN'S RESULT STANDS, AND NOTHING ABOUT A HOLD. The hold's own states - SETTLED, CANCELLED,
  // EXPIRED - and the height a hold refunded itself at were the withdrawn Lightning custody's, and the signer nodes no longer
  // report them (§23.6). A lock's money moves in the one settlement, which this chip does not narrate.
  if (s.finality === 'SUSPENDED') return ' · suspended by an objection';
  if (s.finality === 'FINAL') return ' · final: the committee is settling it';
  if (s.finality === 'PROVISIONALLY_FINAL' && Number.isFinite(s.windowClosesAtMs)) {
    const left = Math.max(0, Math.ceil((s.windowClosesAtMs - nowMs) / 1000));
    return ` · waiting for the objection window, ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')} left`;
  }
  return '';
}

// ---- blwp-client/src/backup-gate.js
// THE BACKUP WARNING (§24B, as ruled 2026-09-21 20:01): nothing is refused, and the player is told.
//
// An earlier cut of this file GATED the first deposit and the first paid join on the phrase being typed
// back. That is overridden: PLAY is always allowed, free or paid, and so is putting money in. What stands
// in the lobby instead is a large warning with its own Backup button, and it stays until one full-phrase
// verification has succeeded.
//
// So `mayDeposit` and `mayPayStake` are gone rather than left exported and unused - a refusal nothing
// calls is a rule somebody will wire back up by accident. What is left is what the warning needs: is this
// seed backed up, and did the player type its phrase back correctly.
//
// WHERE THE FLAG LIVES, and why that is not a hole. It is the player's own browser. A player who clears
// it and re-verifies has only made himself type the words again; a player who forges it has unlocked his
// OWN deposit against his OWN warning. This gate protects the player from losing his money, not the
// operator from the player - so there is nothing here for a node to check and nothing to forge that
// costs anybody else a satoshi. A rule the node must enforce is a different rule and is not this one.
//
// THE PHRASE ITSELF IS NOT THIS FILE'S. Whatever encodes a seed into words hands it in; this checks what
// was typed against it. That keeps the check honest about one thing only - did he write them down - and
// keeps a wordlist's correctness where it belongs.


const VERIFIED_KEY = 'blwp.backup.verified';

/**
 * THE FLAG IS BOUND TO THE SEED IT VERIFIED, AND THAT IS NOT A DETAIL.
 *
 * Measured on the first cut of this file: the seed lives in sessionStorage (`tabSeed` mints a fresh 32
 * bytes when it finds none), so a new tab is a NEW WALLET - while a bare "verified" flag in localStorage
 * outlives every tab. Verify once, open a second tab, and a wallet nobody has ever written down would
 * have been allowed to deposit and to stake. The gate would have been answering about a wallet that no
 * longer existed.
 *
 * So what is recorded is a digest of the seed that was verified, and the gate opens only when the seed in
 * hand hashes to it. A new seed is unverified however many older ones were not.
 */
const digestOf = (seed) => (seed instanceof Uint8Array && seed.length === 32
  ? toHex(sha256(seed)) : null);

/** One word, as a comparison sees it: case and stray spacing are the player's, not the phrase's. */
const normalise = (word) => String(word || '').trim().toLowerCase();

/** The phrase as a list of words, from a string or a list. */
const wordsOf = (phrase) => (Array.isArray(phrase)
  ? phrase.map(normalise) : normalise(phrase).split(/\s+/)).filter(Boolean);

/**
 * EVERY WORD, IN ORDER, ALL OF THEM (§24B; §23A.8's three-word check is withdrawn).
 *
 * A player who can produce three of twelve has not shown he wrote twelve down, and three is exactly what
 * somebody copying a screenshot has. What is checked here is what would actually restore the wallet.
 *
 * The answer says WHERE the first wrong word is, because a player who mistyped word nine wants to know
 * that and an attacker learns nothing he did not type himself.
 */
function verifyPhrase(typed, phrase) {
  const want = wordsOf(phrase);
  const got = wordsOf(typed);
  if (!want.length) return { ok: false, why: 'there is no phrase to check against' };
  if (!got.length) return { ok: false, why: 'type the whole phrase back, every word, in order' };
  if (got.length !== want.length)
    return { ok: false, why: `that is ${got.length} words and the phrase is ${want.length}`, wrongAt: null };
  for (let i = 0; i < want.length; i++)
    if (got[i] !== want[i]) return { ok: false, why: `word ${i + 1} is not the one in the phrase`, wrongAt: i };
  return { ok: true };
}

/** Has THIS seed's phrase been typed back in full, once, in this browser? */
function isVerified(storage, seed) {
  const want = digestOf(seed);
  if (!want) return false;
  try { return storage.getItem(VERIFIED_KEY) === want; } catch { return false; }
}

/** Record that it has, against the seed it was. Only `verifyPhrase` saying ok should reach this. */
function recordVerified(storage, seed) {
  const want = digestOf(seed);
  if (!want) return false;
  try { storage.setItem(VERIFIED_KEY, want); return true; } catch { return false; }
}

/**
 * The one call the page makes for a typed phrase: check it, and record it only if it was right.
 * A wrong word never sets the flag, so a near miss leaves the gate exactly where it was.
 */
function verifyAndRecord({ typed, phrase, storage, seed }) {
  const said = verifyPhrase(typed, phrase);
  if (!said.ok) return said;
  return { ok: true, recorded: recordVerified(storage, seed) };
}

/** What the lobby's first line and the Settings screen say until a verification has succeeded. */
const NO_BACKUP_LINE = 'This wallet has no backup. Lose this browser and the money in it is gone - '
  + 'write your 24 words down now.';
function backupLine(storage, seed) {
  return isVerified(storage, seed) ? '' : NO_BACKUP_LINE;
}



// ---- blwp-client/src/bip39-wordlist.js
// THE BIP-39 ENGLISH WORDLIST, 2048 WORDS, TAKEN AND NOT TYPED.
//
// SOURCE: the reference list from bitcoin/bips `bip-0039/english.txt`, copied out of Trezor's
// `python-mnemonic` (/usr/local/lib/python3.10/dist-packages/mnemonic/wordlist/english.txt) and checked
// against a second, independent copy - @scure/bip39's `english.js`, via ethereum-cryptography. The two
// agree word for word.
//
//   sha256 of the newline-separated list: 2f5eed53a4727b4bf8880d8f3f199efc90e58503646d9ff8eff3a2ed3b24dbda
//   2048 words, "abandon" first and "zoo" last
